module.exports = /*#__PURE__*/JSON.parse('[{"id":"a1-01","level":"a1","title":"En el supermercado","duration":"45s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/a1/A1_01_audio.mp3","snippet":"Es sábado por la mañana y Laura va al supermercado. Ella necesita comprar frutas, verduras y pan.","transcript":"Es sábado por la mañana y Laura va al supermercado. Ella necesita comprar frutas, verduras y pan. Primero busca los plátanos, después las manzanas y las uvas. El vendedor le ofrece mangos, pero están muy caros. Laura sonríe y dice: \\"Gracias, tal vez la próxima semana\\". Luego compra pan y leche. Al final, paga en la caja y vuelve a casa contenta porque compró todo lo necesario.","vocab":[{"term":"supermercado","meaning":"supermarket"},{"term":"verduras","meaning":"vegetables"},{"term":"plátanos","meaning":"bananas"},{"term":"caro","meaning":"expensive"},{"term":"sonríe","meaning":"smiles"},{"term":"pagar","meaning":"to pay"},{"term":"caja","meaning":"checkout counter"},{"term":"volver a casa","meaning":"to go back home"},{"term":"necesario","meaning":"necessary"}],"quiz":[{"id":"q1","type":"single","question":"¿Qué día va Laura al supermercado?","options":["El sábado","El domingo","El viernes"],"answerIndex":0,"explanation":"Laura va al supermercado el sábado por la mañana."},{"id":"q2","type":"single","question":"¿Qué necesita comprar Laura?","options":["Ropa y zapatos","Frutas, verduras y pan","Libros y cuadernos"],"answerIndex":1,"explanation":"Laura necesita comprar frutas, verduras y pan."},{"id":"q3","type":"single","question":"¿Por qué no compra los mangos?","options":["Porque no le gustan","Porque están muy caros","Porque no hay mangos"],"answerIndex":1,"explanation":"Laura no compra los mangos porque están muy caros."},{"id":"q4","type":"single","question":"¿Qué compra al final?","options":["Pan y leche","Agua y arroz","Pan y jugo"],"answerIndex":0,"explanation":"Al final, Laura compra pan y leche."},{"id":"q5","type":"single","question":"¿Cómo se siente Laura al final?","options":["Triste","Cansada","Contenta"],"answerIndex":2,"explanation":"Laura se siente contenta porque compró todo lo necesario."}]},{"id":"a1-02","level":"a1","title":"Un día en el parque","duration":"55s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/a1/A1_02_audio.mp3","snippet":"Hoy hace buen tiempo y Miguel decide ir al parque. Lleva una botella de agua, su gorra y su pelota.","transcript":"Hoy hace buen tiempo y Miguel decide ir al parque. Lleva una botella de agua, su gorra y su pelota. En el parque hay muchas personas: niños que juegan, adultos que caminan y algunos perros corriendo. Miguel se sienta bajo un árbol y escucha a los pájaros. Después, juega con su pelota y conoce a un niño llamado Pablo. Juegan juntos y se ríen mucho. Más tarde, Miguel compra un helado de chocolate y se sienta en una banca. Ve pasar a una familia con una bicicleta grande y un perro pequeño. Cuando el sol empieza a bajar, Miguel vuelve a casa cansado, pero contento. Fue un buen día.","vocab":[{"term":"parque","meaning":"park"},{"term":"gorra","meaning":"cap / hat"},{"term":"pelota","meaning":"ball"},{"term":"pájaros","meaning":"birds"},{"term":"reírse","meaning":"to laugh"},{"term":"helado","meaning":"ice cream"},{"term":"banca","meaning":"bench"},{"term":"bicicleta","meaning":"bicycle"},{"term":"cansado","meaning":"tired"},{"term":"contento","meaning":"happy"}],"quiz":[{"id":"q1","type":"single","question":"¿A dónde va Miguel?","options":["Al parque","A la escuela","Al cine"],"answerIndex":0,"explanation":"Miguel decide ir al parque porque hace buen tiempo."},{"id":"q2","type":"single","question":"¿Qué lleva Miguel al parque?","options":["Una mochila y un libro","Una botella de agua, una gorra y una pelota","Un paraguas y una cámara"],"answerIndex":1,"explanation":"Miguel lleva una botella de agua, su gorra y su pelota."},{"id":"q3","type":"single","question":"¿Con quién juega Miguel?","options":["Con su hermana","Con un perro","Con un niño llamado Pablo"],"answerIndex":2,"explanation":"Miguel conoce a un niño llamado Pablo y juegan juntos."},{"id":"q4","type":"single","question":"¿Qué compra Miguel?","options":["Un refresco","Una bicicleta","Un helado de chocolate"],"answerIndex":2,"explanation":"Miguel compra un helado de chocolate."},{"id":"q5","type":"single","question":"¿Cómo se siente Miguel al final del día?","options":["Cansado pero contento","Nervioso","Triste"],"answerIndex":0,"explanation":"Miguel vuelve a casa cansado, pero contento porque fue un buen día."}]},{"id":"a1-03","level":"a1","title":"En el café","duration":"40s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/a1/A1_03_audio.mp3","snippet":"Camarero: Buenos días, ¿qué desea tomar?\\nAna: Buenos días. Quisiera un café con leche, por favor.","transcript":"Camarero: Buenos días, ¿qué desea tomar?\\nAna: Buenos días. Quisiera un café con leche, por favor.\\nCamarero: Claro. ¿Desea algo para comer?\\nAna: Sí, una rebanada de pastel de chocolate.\\nCamarero: Perfecto. ¿Algo más?\\nAna: No, gracias. ¿Cuánto cuesta?\\nCamarero: Son cuarenta pesos en total.\\nAna: Aquí tiene.\\nCamarero: Gracias. Su café estará listo en un momento.\\nAna: Muy bien, muchas gracias.\\nCamarero: Que tenga un buen día.\\nAna: Igualmente.","vocab":[{"term":"camarero","meaning":"waiter"},{"term":"café con leche","meaning":"coffee with milk"},{"term":"rebanada","meaning":"slice"},{"term":"pastel","meaning":"cake"},{"term":"cuesta","meaning":"costs"},{"term":"en total","meaning":"in total"},{"term":"aquí tiene","meaning":"here you go"},{"term":"listo","meaning":"ready"},{"term":"buen día","meaning":"good day"},{"term":"igualmente","meaning":"same to you"}],"quiz":[{"id":"q1","type":"single","question":"¿Dónde ocurre la conversación?","options":["En un café","En un supermercado","En una tienda de ropa"],"answerIndex":0,"explanation":"La conversación ocurre en un café entre el camarero y Ana."},{"id":"q2","type":"single","question":"¿Qué pide Ana para tomar?","options":["Un café con leche","Un jugo","Un té"],"answerIndex":0,"explanation":"Ana pide un café con leche."},{"id":"q3","type":"single","question":"¿Qué pide Ana para comer?","options":["Un sándwich","Una ensalada","Una rebanada de pastel de chocolate"],"answerIndex":2,"explanation":"Ana pide una rebanada de pastel de chocolate."},{"id":"q4","type":"single","question":"¿Cuánto cuesta todo?","options":["Cuarenta pesos","Cincuenta pesos","Treinta pesos"],"answerIndex":0,"explanation":"El total es cuarenta pesos."},{"id":"q5","type":"single","question":"¿Cómo termina la conversación?","options":["Con una queja","Con un agradecimiento y un saludo","Con un pedido nuevo"],"answerIndex":1,"explanation":"La conversación termina con agradecimientos y saludos cordiales."}]},{"id":"a1-04","level":"a1","title":"En la parada del autobús","duration":"50s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/a1/A1_04_audio.mp3","snippet":"Luis: Hola, ¿esperas el autobús 23?\\nClara: Sí, lo espero desde hace diez minutos. ¿Tú también?","transcript":"Luis: Hola, ¿esperas el autobús 23?\\nClara: Sí, lo espero desde hace diez minutos. ¿Tú también?\\nLuis: Sí. Siempre llega tarde por la mañana.\\nClara: ¡Qué mal! Tengo una cita a las nueve.\\nLuis: Entonces espero que llegue pronto. ¿Vas al centro?\\nClara: Sí, trabajo cerca del parque principal. ¿Y tú?\\nLuis: Yo estudio en la universidad que está en la misma calle.\\nClara: Ah, qué bien. ¡Mira! Ahí viene el autobús.\\nLuis: Por fin. Espero que no esté lleno.\\nClara: Sí, yo también.","vocab":[{"term":"parada","meaning":"bus stop"},{"term":"autobús","meaning":"bus"},{"term":"cita","meaning":"appointment / meeting"},{"term":"llegar tarde","meaning":"to arrive late"},{"term":"el centro","meaning":"downtown"},{"term":"universidad","meaning":"university"},{"term":"por fin","meaning":"finally"},{"term":"lleno","meaning":"full / crowded"}],"quiz":[{"id":"q1","type":"single","question":"¿Qué número de autobús esperan Luis y Clara?","options":["El 23","El 30","El 10"],"answerIndex":0,"explanation":"Luis y Clara esperan el autobús número 23."},{"id":"q2","type":"single","question":"¿Desde cuándo espera Clara el autobús?","options":["Desde hace diez minutos","Desde hace media hora","Desde hace cinco minutos"],"answerIndex":0,"explanation":"Clara espera el autobús desde hace diez minutos."},{"id":"q3","type":"single","question":"¿Por qué está preocupada Clara?","options":["Porque perdió su dinero","Porque olvidó su bolsa","Porque tiene una cita a las nueve"],"answerIndex":2,"explanation":"Clara está preocupada porque tiene una cita a las nueve y el autobús llega tarde."},{"id":"q4","type":"single","question":"¿A dónde va Clara?","options":["A la universidad","Al centro","A su casa"],"answerIndex":1,"explanation":"Clara va al centro donde trabaja cerca del parque principal."},{"id":"q5","type":"single","question":"¿Qué hace Luis?","options":["Estudia en la universidad","Espera a un amigo","Trabaja en una tienda"],"answerIndex":0,"explanation":"Luis estudia en la universidad que está en la misma calle."},{"id":"q6","type":"single","question":"¿Qué dicen cuando llega el autobús?","options":["Tal vez mañana","Por fin","No viene"],"answerIndex":1,"explanation":"Luis dice \'Por fin\' cuando llega el autobús."},{"id":"q7","type":"single","question":"¿Qué esperan Luis y Clara al final?","options":["Que el autobús no esté lleno","Que el autobús cambie de ruta","Que el autobús esté vacío"],"answerIndex":0,"explanation":"Luis y Clara esperan que el autobús no esté lleno."}]},{"id":"a1-05","level":"a1","title":"En el trabajo","duration":"45s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/a1/A1_05_audio.mp3","snippet":"Lucía: ¡Hola, Pedro! ¿Es tu primer día en la oficina?\\nPedro: Sí, hoy empiezo. Estoy un poco nervioso.","transcript":"Lucía: ¡Hola, Pedro! ¿Es tu primer día en la oficina?\\nPedro: Sí, hoy empiezo. Estoy un poco nervioso.\\nLucía: No te preocupes. Todos son muy amables aquí.\\nPedro: Gracias. ¿Dónde está mi escritorio?\\nLucía: Está junto a la ventana, al lado de Marta.\\nPedro: Perfecto. ¿A qué hora tenemos la reunión?\\nLucía: A las nueve y media. El jefe siempre llega puntual.\\nPedro: Bien, entonces voy a encender la computadora.\\nLucía: Muy bien. ¡Bienvenido al equipo!\\nPedro: ¡Gracias, Lucía!","vocab":[{"term":"oficina","meaning":"office"},{"term":"escritorio","meaning":"desk"},{"term":"nervioso","meaning":"nervous"},{"term":"amable","meaning":"kind"},{"term":"ventana","meaning":"window"},{"term":"reunión","meaning":"meeting"},{"term":"jefe","meaning":"boss"},{"term":"encender","meaning":"to turn on"},{"term":"computadora","meaning":"computer"},{"term":"equipo","meaning":"team"}],"quiz":[{"id":"q1","type":"single","question":"¿Dónde trabaja Lucía?","options":["En una tienda","En una oficina","En un hospital"],"answerIndex":1,"explanation":"La conversación ocurre en una oficina."},{"id":"q2","type":"single","question":"¿Qué hace Pedro en la oficina?","options":["Empieza su primer día de trabajo","Visita a un amigo","Busca información"],"answerIndex":0,"explanation":"Es el primer día de trabajo de Pedro en la oficina."},{"id":"q3","type":"single","question":"¿Cómo es el jefe?","options":["Muy amable","Siempre llega puntual","Un poco nervioso"],"answerIndex":1,"explanation":"Lucía dice que el jefe siempre llega puntual."},{"id":"q4","type":"single","question":"¿Dónde está el escritorio de Pedro?","options":["Junto a la puerta","En el pasillo","Junto a la ventana"],"answerIndex":2,"explanation":"El escritorio de Pedro está junto a la ventana, al lado de Marta."},{"id":"q5","type":"single","question":"¿Qué hace Pedro al final del diálogo?","options":["Llama al jefe","Enciende la computadora","Sale de la oficina"],"answerIndex":1,"explanation":"Pedro dice que va a encender la computadora."}]},{"id":"a1-06","level":"a1","title":"Profesiones","duration":"40s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/a1/A1_06_audio.mp3","snippet":"Lucía es doctora. Trabaja en un hospital. Ayuda a las personas todos los días.","transcript":"Lucía es doctora. Trabaja en un hospital. Ayuda a las personas todos los días. Su amigo Carlos es maestro. Enseña a los niños en una escuela. Los niños leen y escriben con él. La amiga de Lucía se llama Ana. Ella es cocinera. Prepara comida en un restaurante. Los tres están contentos con su trabajo.","vocab":[{"term":"doctora","meaning":"doctor"},{"term":"hospital","meaning":"hospital"},{"term":"ayudar","meaning":"to help"},{"term":"maestro","meaning":"teacher"},{"term":"enseñar","meaning":"to teach"},{"term":"escuela","meaning":"school"},{"term":"cocinera","meaning":"cook"},{"term":"preparar comida","meaning":"to prepare food"},{"term":"restaurante","meaning":"restaurant"},{"term":"trabajo","meaning":"job / work"}],"quiz":[{"id":"q1","type":"single","question":"¿Dónde trabaja Lucía?","options":["En una escuela","En un hospital","En una tienda"],"answerIndex":1,"explanation":"Lucía es doctora y trabaja en un hospital."},{"id":"q2","type":"single","question":"¿Qué hace Carlos?","options":["Cocina","Enseña a los niños","Conduce un autobús"],"answerIndex":1,"explanation":"Carlos es maestro y enseña a los niños en una escuela."},{"id":"q3","type":"single","question":"¿Dónde trabaja Ana?","options":["En un restaurante","En una oficina","En un hospital"],"answerIndex":0,"explanation":"Ana es cocinera y prepara comida en un restaurante."},{"id":"q4","type":"single","question":"¿Qué hacen los niños con Carlos?","options":["Leen y escriben","Duermen","Juegan fútbol"],"answerIndex":0,"explanation":"Los niños leen y escriben con Carlos en la escuela."},{"id":"q5","type":"single","question":"¿Cómo están Lucía, Carlos y Ana?","options":["Tristes","Cansados","Contentos"],"answerIndex":2,"explanation":"Los tres están contentos con su trabajo."}]},{"id":"a2-01","level":"a2","title":"El nuevo vecino","duration":"1m 10s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/a2/A2_01_audio.mp3","snippet":"Hace dos semanas llegó un nuevo vecino al edificio de Marta. Se llama Tomás y viene de Argentina.","transcript":"Hace dos semanas llegó un nuevo vecino al edificio de Marta. Se llama Tomás y viene de Argentina. Es muy amable y siempre saluda a todos con una sonrisa. El primer día, Marta lo vio en el ascensor y comenzaron a hablar. Tomás le contó que trabaja desde casa y que le encanta cocinar. También mencionó que todavía no conoce bien la ciudad y que está buscando lugares para comer buena comida mexicana.\\n\\nMarta le recomendó una taquería cerca del parque y le dijo que los tacos al pastor son los mejores. Al día siguiente, Tomás le agradeció el consejo y le comentó que había probado los tacos. \\"¡Tenías razón!\\", le dijo. Desde entonces, se ven seguido en el pasillo y siempre conversan un poco antes de entrar a sus departamentos.","vocab":[{"term":"vecino","meaning":"neighbor"},{"term":"edificio","meaning":"building"},{"term":"amable","meaning":"kind"},{"term":"ascensor","meaning":"elevator"},{"term":"taquería","meaning":"taco restaurant"},{"term":"al pastor","meaning":"marinated pork taco style"},{"term":"consejo","meaning":"advice"},{"term":"probar","meaning":"to try (food)"},{"term":"pasillo","meaning":"hallway"},{"term":"departamento","meaning":"apartment"}],"quiz":[{"id":"q1","type":"single","question":"¿De dónde viene Tomás?","options":["De México","De Argentina","De España"],"answerIndex":1,"explanation":"Tomás viene de Argentina."},{"id":"q2","type":"single","question":"¿Dónde conoció Marta a su nuevo vecino?","options":["En el parque","En el supermercado","En el ascensor"],"answerIndex":2,"explanation":"Marta conoció a Tomás en el ascensor el primer día."},{"id":"q3","type":"single","question":"¿Qué le gusta hacer a Tomás?","options":["Correr y leer","Ver televisión","Cocinar"],"answerIndex":2,"explanation":"A Tomás le encanta cocinar."},{"id":"q4","type":"single","question":"¿Qué le recomendó Marta a Tomás?","options":["Un museo famoso","Un gimnasio nuevo","Una taquería cerca del parque"],"answerIndex":2,"explanation":"Marta le recomendó una taquería cerca del parque."},{"id":"q5","type":"single","question":"¿Qué hizo Tomás después de visitar la taquería?","options":["Se mudó de edificio","Le agradeció a Marta","Compró más tacos para su familia"],"answerIndex":1,"explanation":"Tomás le agradeció a Marta el consejo al día siguiente."}]},{"id":"a2-02","level":"a2","title":"El viaje de fin de semana","duration":"1m 15s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/a2/A2_02_audio.mp3","snippet":"Sofía y su hermano Andrés preparan sus maletas para pasar el fin de semana fuera de la ciudad.","transcript":"El viernes por la tarde, Sofía y su hermano Andrés preparan sus maletas para pasar el fin de semana fuera de la ciudad. Van a visitar a sus abuelos, que viven en un pueblo cerca de las montañas.\\n\\nSofía prepara ropa cómoda, una chaqueta y su cámara de fotos. Andrés lleva una pelota, un libro y algunos bocadillos para el camino. Salen temprano el sábado y el viaje en coche dura unas tres horas.\\n\\nCuando llegan, los abuelos los reciben con un gran abrazo y un desayuno delicioso. Después descansan un poco y dan un paseo por el bosque. Ven mariposas, flores de muchos colores y un pequeño río. Por la noche, cenan juntos y cuentan historias frente a la chimenea.\\n\\nEl domingo regresan a casa cansados, pero felices. Dicen que fue el mejor fin de semana del año.","vocab":[{"term":"maleta","meaning":"suitcase"},{"term":"pueblo","meaning":"small town"},{"term":"montaña","meaning":"mountain"},{"term":"chaqueta","meaning":"jacket"},{"term":"bocadillo","meaning":"snack / sandwich"},{"term":"chimenea","meaning":"fireplace"},{"term":"paseo","meaning":"walk / stroll"},{"term":"bosque","meaning":"forest"},{"term":"mariposa","meaning":"butterfly"},{"term":"cansado","meaning":"tired"}],"quiz":[{"id":"q1","type":"single","question":"¿A dónde van Sofía y Andrés?","options":["A la playa","A la casa de sus abuelos","A la escuela"],"answerIndex":1,"explanation":"Sofía y Andrés van a visitar a sus abuelos que viven en un pueblo cerca de las montañas."},{"id":"q2","type":"single","question":"¿Qué lleva Sofía en su maleta?","options":["Una pelota y un libro","Comida para el viaje","Ropa cómoda y su cámara"],"answerIndex":2,"explanation":"Sofía prepara ropa cómoda, una chaqueta y su cámara de fotos."},{"id":"q3","type":"single","question":"¿Cuánto dura el viaje en coche?","options":["Una hora","Cinco horas","Tres horas"],"answerIndex":2,"explanation":"El viaje en coche dura unas tres horas."},{"id":"q4","type":"single","question":"¿Qué hacen cuando llegan?","options":["Van al cine","Comen, descansan y dan un paseo","Ven televisión"],"answerIndex":1,"explanation":"Los abuelos los reciben con desayuno, después descansan y dan un paseo por el bosque."},{"id":"q5","type":"single","question":"¿Cómo describen el fin de semana?","options":["Cansado y aburrido","Muy corto y sin diversión","El mejor del año"],"answerIndex":2,"explanation":"Dicen que fue el mejor fin de semana del año."}]},{"id":"a2-03","level":"a2","title":"Reservando un hotel","duration":"1m 5s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/a2/A2_03_audio.mp3","snippet":"Recepcionista: Buenas tardes, Hotel Sol del Valle, ¿en qué puedo ayudarle?\\nCarlos: Buenas tardes. Quiero reservar una habitación para este fin de semana.","transcript":"Recepcionista: Buenas tardes, Hotel Sol del Valle, ¿en qué puedo ayudarle?\\nCarlos: Buenas tardes. Quiero reservar una habitación para este fin de semana.\\nRecepcionista: Claro, ¿para cuántas personas?\\nCarlos: Para dos, por favor.\\nRecepcionista: Perfecto. Tenemos habitaciones dobles con desayuno incluido. ¿Desea una con vista al mar o al jardín?\\nCarlos: Con vista al mar, por favor. ¿Cuál es el precio por noche?\\nRecepcionista: Son mil doscientos pesos por noche.\\nCarlos: Muy bien. ¿Puedo pagar con tarjeta?\\nRecepcionista: Sí, aceptamos todas las tarjetas de crédito y débito.\\nCarlos: Perfecto. Llegaremos el viernes por la tarde.\\nRecepcionista: Excelente. ¿Me puede dar su nombre completo, por favor?\\nCarlos: Sí, Carlos Méndez García.\\nRecepcionista: Listo, señor Méndez. Su reserva está confirmada para el viernes. Lo esperamos.\\nCarlos: Muchas gracias.\\nRecepcionista: A usted. Que tenga un buen día.","vocab":[{"term":"habitación","meaning":"room"},{"term":"reservar","meaning":"to book / to reserve"},{"term":"doble","meaning":"double (room)"},{"term":"desayuno incluido","meaning":"breakfast included"},{"term":"vista al mar","meaning":"sea view"},{"term":"jardín","meaning":"garden"},{"term":"precio por noche","meaning":"price per night"},{"term":"pagar con tarjeta","meaning":"pay by card"},{"term":"nombre completo","meaning":"full name"},{"term":"lo esperamos","meaning":"we\'ll be expecting you"}],"quiz":[{"id":"q1","type":"single","question":"¿Qué quiere hacer Carlos?","options":["Cancelar una reserva","Pedir comida","Reservar una habitación"],"answerIndex":2,"explanation":"Carlos quiere reservar una habitación para el fin de semana."},{"id":"q2","type":"single","question":"¿Para cuántas personas es la habitación?","options":["Para una","Para dos","Para tres"],"answerIndex":1,"explanation":"La habitación es para dos personas."},{"id":"q3","type":"single","question":"¿Qué tipo de habitación elige Carlos?","options":["Con vista al jardín","Con vista al mar","Sin desayuno"],"answerIndex":1,"explanation":"Carlos elige una habitación con vista al mar."},{"id":"q4","type":"single","question":"¿Cuánto cuesta por noche?","options":["Ochocientos pesos","Mil quinientos pesos","Mil doscientos pesos"],"answerIndex":2,"explanation":"El precio es mil doscientos pesos por noche."},{"id":"q5","type":"single","question":"¿Cómo puede pagar Carlos?","options":["Solo en efectivo","Con tarjeta","Con transferencia"],"answerIndex":1,"explanation":"Carlos puede pagar con tarjeta de crédito o débito."},{"id":"q6","type":"single","question":"¿Cuándo llegará al hotel?","options":["El jueves","El sábado","El viernes"],"answerIndex":2,"explanation":"Carlos llegará al hotel el viernes por la tarde."}]},{"id":"a2-04","level":"a2","title":"Información turística","duration":"1m 10s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/a2/A2_04_audio.mp3","transcript":"Empleada: Buenos días, oficina de información turística, ¿en qué puedo ayudarle?\\nMaría: Buenos días. Es mi primera vez en la ciudad. ¿Podría recomendarme algunos lugares para visitar?\\nEmpleada: Claro. El museo de arte está muy cerca y también puede caminar por el centro histórico.\\nMaría: Perfecto. ¿Dónde está el museo exactamente?\\nEmpleada: Está en la avenida principal, a unos diez minutos a pie. Si quiere, puede tomar el autobús número 12.\\nMaría: Gracias. ¿Y algún restaurante que recomiende?\\nEmpleada: Sí, el restaurante \\"La Plaza\\" tiene muy buena comida local. Está frente a la catedral.\\nMaría: Excelente. ¿A qué hora cierra el museo?\\nEmpleada: Cierra a las seis de la tarde, pero los domingos la entrada es gratis.\\nMaría: Perfecto. Muchas gracias por la información.\\nEmpleada: De nada. Disfrute su visita.","vocab":[{"term":"oficina de información turística","meaning":"tourist information office"},{"term":"recomendar","meaning":"to recommend"},{"term":"centro histórico","meaning":"historic center"},{"term":"avenida principal","meaning":"main avenue"},{"term":"a pie","meaning":"on foot"},{"term":"autobús","meaning":"bus"},{"term":"frente a","meaning":"in front of"},{"term":"catedral","meaning":"cathedral"},{"term":"comida local","meaning":"local food"},{"term":"entrada gratis","meaning":"free entry"}],"quiz":[{"id":"q1","type":"single","question":"¿Dónde ocurre la conversación?","options":["En un restaurante","En una oficina de información turística","En un hotel"],"answerIndex":1,"explanation":"La conversación ocurre en una oficina de información turística."},{"id":"q2","type":"single","question":"¿Qué quiere hacer María?","options":["Comprar boletos","Ir de compras","Visitar lugares turísticos"],"answerIndex":2,"explanation":"María quiere visitar lugares turísticos porque es su primera vez en la ciudad."},{"id":"q3","type":"single","question":"¿Dónde está el museo de arte?","options":["En el centro histórico","En la avenida principal","En la estación de tren"],"answerIndex":1,"explanation":"El museo de arte está en la avenida principal."},{"id":"q4","type":"single","question":"¿Qué número de autobús puede tomar María?","options":["El número 21","El número 5","El número 12"],"answerIndex":2,"explanation":"María puede tomar el autobús número 12 para ir al museo."},{"id":"q5","type":"single","question":"¿Qué tipo de comida hay en el restaurante \\"La Plaza\\"?","options":["Comida italiana","Comida rápida","Comida local"],"answerIndex":2,"explanation":"El restaurante \\"La Plaza\\" tiene comida local."},{"id":"q6","type":"single","question":"¿Cuándo es gratis la entrada al museo?","options":["Los sábados","Los domingos","Los lunes"],"answerIndex":1,"explanation":"Los domingos la entrada al museo es gratis."}],"snippet":"Empleada: Buenos días, oficina de información turística, ¿en qué puedo ayudarle. María: Buenos días."},{"id":"a2-05","level":"a2","title":"Mi rutina diaria","duration":"1m 5s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/a2/A2_05_audio.mp3","snippet":"Me llamo Clara y soy estudiante. De lunes a viernes me levanto a las siete de la mañana.","transcript":"Me llamo Clara y soy estudiante. De lunes a viernes me levanto a las siete de la mañana. Después me ducho y me visto rápidamente. Siempre desayuno café con pan antes de salir.\\n\\nA las ocho voy a la universidad. Las clases empiezan a las ocho y media y terminan al mediodía. Luego almuerzo con mis amigos en la cafetería.\\n\\nPor la tarde estudio un poco y escucho música. A veces salgo a caminar con mi perro. Por la noche ceno con mi familia y veo la televisión. Finalmente me acuesto a las once.\\n\\nEs un día normal, pero me gusta mi rutina.","vocab":[{"term":"levantarse","meaning":"to get up"},{"term":"ducharse","meaning":"to take a shower"},{"term":"desayunar","meaning":"to have breakfast"},{"term":"almorzar","meaning":"to have lunch"},{"term":"cenar","meaning":"to have dinner"},{"term":"acostarse","meaning":"to go to bed"}],"quiz":[{"id":"q1","type":"single","question":"¿A qué hora se levanta Clara?","options":["A las seis","A las siete","A las ocho"],"answerIndex":1,"explanation":"Clara se levanta a las siete de la mañana de lunes a viernes."},{"id":"q2","type":"single","question":"¿Qué toma Clara en el desayuno?","options":["Jugo y fruta","Café con pan","Té con leche"],"answerIndex":1,"explanation":"Clara siempre desayuna café con pan antes de salir."},{"id":"q3","type":"single","question":"¿Con quién almuerza Clara?","options":["Con su familia","Con sus amigos","Sola"],"answerIndex":1,"explanation":"Clara almuerza con sus amigos en la cafetería."},{"id":"q4","type":"single","question":"¿Qué hace por la tarde?","options":["Trabaja en una oficina","Estudia y escucha música","Va al cine"],"answerIndex":1,"explanation":"Por la tarde Clara estudia un poco y escucha música."},{"id":"q5","type":"single","question":"¿A qué hora se acuesta Clara?","options":["A las once","A las diez","A las doce"],"answerIndex":0,"explanation":"Clara se acuesta a las once de la noche."}]},{"id":"a2-06","level":"a2","title":"El cumpleaños de Ana","duration":"55s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/a2/A2_06_audio.mp3","snippet":"Hoy es el cumpleaños de Ana. Ella cumple veinticinco años y está muy contenta.","transcript":"Hoy es el cumpleaños de Ana. Ella cumple veinticinco años y está muy contenta. Por la mañana recibe mensajes de sus amigos y habla con su familia por teléfono.\\n\\nPor la tarde va al supermercado para comprar refrescos, pastel y globos. A las siete, llegan sus amigos con regalos y música.\\n\\nTodos cantan \\"Feliz cumpleaños\\" y comen pastel. Después bailan y toman fotos. Ana dice gracias y dice: \\"¡Fue un día perfecto!\\".","vocab":[{"term":"cumpleaños","meaning":"birthday"},{"term":"regalo","meaning":"gift"},{"term":"pastel","meaning":"cake"},{"term":"globos","meaning":"balloons"},{"term":"cantar","meaning":"to sing"},{"term":"bailar","meaning":"to dance"},{"term":"mensaje","meaning":"message"},{"term":"supermercado","meaning":"supermarket"},{"term":"refresco","meaning":"soft drink / soda"},{"term":"foto","meaning":"photo"}],"quiz":[{"id":"q1","type":"single","question":"¿Cuántos años cumple Ana?","options":["20","25","30"],"answerIndex":1,"explanation":"Ana cumple veinticinco años."},{"id":"q2","type":"single","question":"¿Qué compra en el supermercado?","options":["Ropa y flores","Refrescos, pastel y globos","Pan y café"],"answerIndex":1,"explanation":"Ana va al supermercado para comprar refrescos, pastel y globos."},{"id":"q3","type":"single","question":"¿Qué hacen sus amigos en la fiesta?","options":["Ven una película","Juegan videojuegos","Cantan y bailan"],"answerIndex":2,"explanation":"Todos cantan \'Feliz cumpleaños\', comen pastel y después bailan."},{"id":"q4","type":"single","question":"¿Con quién habla Ana por la mañana?","options":["Con su familia","Con su jefe","Con su doctora"],"answerIndex":0,"explanation":"Por la mañana Ana habla con su familia por teléfono."},{"id":"q5","type":"single","question":"¿Cómo describe Ana el día?","options":["Un día aburrido","Un día perfecto","Un día normal"],"answerIndex":1,"explanation":"Ana dice: \'¡Fue un día perfecto!\'."}]},{"id":"b1-01","level":"b1","title":"El mensaje equivocado","duration":"1m 15s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/b1/B1_01_audio.mp3","transcript":"Lucía trabaja en una pequeña oficina de arquitectura. Un lunes por la mañana, su jefe le pidió que enviara un correo importante a un cliente llamado Javier Torres con los nuevos planos de una casa. Todo parecía fácil, pero Lucía, sin darse cuenta, escribió mal la dirección y envió el correo a otro Javier, un antiguo compañero de universidad.\\n\\nUnas horas después, recibió una respuesta:\\n\\n\\"Hola, Lucía. Gracias por los planos, pero creo que te has equivocado de persona. Aun así, ¡me alegra saber de ti después de tanto tiempo!\\".\\n\\nLucía se puso roja de vergüenza. Llamó a su jefe para explicarle lo que había pasado. Él, sorprendentemente, se rió y le dijo: \\"No te preocupes, todos cometemos errores. Solo asegúrate de revisarlo dos veces la próxima vez\\". Desde ese día, Lucía siempre revisa cada dirección antes de enviar un correo electrónico.","vocab":[{"term":"planos","meaning":"blueprints"},{"term":"equivocarse","meaning":"to make a mistake"},{"term":"compañero de universidad","meaning":"college classmate"},{"term":"ponerse rojo/a","meaning":"to blush / get embarrassed"},{"term":"revisar","meaning":"to check / review"},{"term":"dirección de correo","meaning":"email address"},{"term":"cliente","meaning":"client"},{"term":"sorprendentemente","meaning":"surprisingly"},{"term":"cometer un error","meaning":"to make a mistake"},{"term":"asegurarse","meaning":"to make sure"}],"quiz":[{"id":"q1","type":"single","question":"¿Dónde trabaja Lucía?","options":["En un hospital","En una escuela","En una oficina de arquitectura"],"answerIndex":2,"explanation":"Lucía trabaja en una pequeña oficina de arquitectura."},{"id":"q2","type":"single","question":"¿Qué debía enviar Lucía?","options":["Una invitación","Unos planos","Un contrato"],"answerIndex":1,"explanation":"Lucía debía enviar los nuevos planos de una casa a un cliente."},{"id":"q3","type":"single","question":"¿A quién envió el correo por error?","options":["A su jefe","Al cliente correcto","A otro Javier"],"answerIndex":2,"explanation":"Lucía envió el correo por error a otro Javier, un antiguo compañero de universidad."},{"id":"q4","type":"single","question":"¿Cómo reaccionó el jefe de Lucía?","options":["Se enojó mucho","Ignoró el problema","Se rió y le dio un consejo"],"answerIndex":2,"explanation":"El jefe se rió y le dijo que todos cometemos errores, dándole el consejo de revisar dos veces."},{"id":"q5","type":"single","question":"¿Qué hace Lucía desde ese día?","options":["No usa más el correo electrónico","Revisa las direcciones antes de enviar un mensaje","Le pide ayuda a su jefe siempre"],"answerIndex":1,"explanation":"Desde ese día, Lucía siempre revisa cada dirección antes de enviar un correo electrónico."}],"snippet":"Lucía trabaja en una pequeña oficina de arquitectura. Un lunes por la mañana, su jefe le pidió que enviara un correo importante a un cliente llamad..."},{"id":"b1-02","level":"b1","title":"El día que perdí el tren","duration":"1m 10s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/b1/B1_02_audio.mp3","transcript":"Eran las siete y media de la mañana y todavía estaba en casa. El tren salía a las ocho, así que tenía media hora para llegar a la estación. \\"Tengo tiempo\\", pensé, pero mientras buscaba mis llaves, recordé que el celular estaba descargado. Corrí a conectarlo y perdí varios minutos.\\n\\nCuando por fin salí, había mucho tráfico. El autobús avanzaba muy lento y yo miraba el reloj cada dos segundos. En la estación, corrí hasta la puerta del tren, pero justo cuando llegué… se cerraron las puertas.\\n\\nMe quedé allí, sin aire, viendo cómo el tren se alejaba. Al principio sentí enojo conmigo misma, pero después respiré profundo. Llamé a mi jefe, le expliqué la situación y tomé el siguiente tren. Llegué tarde, sí, pero más tranquila. Ese día aprendí que a veces perder algo no es el fin del mundo, sino una forma de detenerse y respirar.","vocab":[{"term":"estación","meaning":"station"},{"term":"tráfico","meaning":"traffic"},{"term":"descargar (el celular)","meaning":"to be out of battery / to discharge"},{"term":"avanzar","meaning":"to move forward"},{"term":"reloj","meaning":"watch / clock"},{"term":"puerta del tren","meaning":"train door"},{"term":"alejarse","meaning":"to move away"},{"term":"respirar profundo","meaning":"to take a deep breath"},{"term":"tranquilo/a","meaning":"calm"},{"term":"detenerse","meaning":"to stop oneself"}],"quiz":[{"id":"q1","type":"single","question":"¿A qué hora salía el tren?","options":["A las siete y media","A las ocho y media","A las ocho"],"answerIndex":2,"explanation":"El tren salía a las ocho."},{"id":"q2","type":"single","question":"¿Por qué perdió tiempo antes de salir de casa?","options":["Porque no tenía dinero","Porque no encontraba su teléfono","Porque no encontraba el boleto"],"answerIndex":1,"explanation":"Perdió tiempo porque recordó que el celular estaba descargado y corrió a conectarlo."},{"id":"q3","type":"single","question":"¿Qué ocurrió cuando llegó a la estación?","options":["El tren estaba retrasado","El tren se descompuso","El tren ya había salido"],"answerIndex":2,"explanation":"Cuando llegó a la estación, las puertas del tren se cerraron y el tren se alejó."},{"id":"q4","type":"single","question":"¿Cómo se sintió al principio?","options":["Tranquilo","Enojado","Feliz"],"answerIndex":1,"explanation":"Al principio sintió enojo consigo misma."},{"id":"q5","type":"single","question":"¿Qué hizo después de perder el tren?","options":["Se fue a casa","Llamó a un amigo","Tomó el siguiente tren"],"answerIndex":2,"explanation":"Llamó a su jefe, le explicó la situación y tomó el siguiente tren."},{"id":"q6","type":"single","question":"¿Qué aprendió al final del día?","options":["Que no le gusta viajar en tren","Que llegar tarde no es tan grave","Que debe cambiar de trabajo"],"answerIndex":1,"explanation":"Aprendió que a veces perder algo no es el fin del mundo, sino una forma de detenerse y respirar."}],"snippet":"Eran las siete y media de la mañana y todavía estaba en casa. El tren salía a las ocho, así que tenía media hora para llegar a la estación."},{"id":"b1-03","level":"b1","title":"La decisión más difícil","duration":"1m 20s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/b1/B1_03_audio.mp3","transcript":"Durante años, Carla soñó con tener su propio negocio. Trabajaba en una empresa grande, con un salario estable y compañeros amables, pero cada día sentía que algo le faltaba. En las noches pensaba: \\"¿Y si renuncio y empiezo de nuevo?\\". Sin embargo, el miedo siempre ganaba.\\n\\nUn día, su mejor amiga le envió un mensaje: \\"Encontré un local perfecto para tu idea de pastelería. Solo falta tu decisión.\\" Carla leyó el mensaje varias veces. Tenía ahorros, tenía un plan… pero no tenía seguridad.\\n\\nEsa noche no durmió. Al día siguiente, mientras preparaba café, pensó en todo lo que había aprendido en su trabajo: organización, atención al cliente, esfuerzo. Sonrió. Tal vez ya estaba lista.\\n\\nUna semana después, presentó su renuncia. No fue fácil, pero al abrir su tienda por primera vez y oler el pan recién horneado, supo que había tomado la mejor decisión de su vida.","vocab":[{"term":"negocio","meaning":"business"},{"term":"salario estable","meaning":"steady salary"},{"term":"renunciar","meaning":"to quit (a job)"},{"term":"local","meaning":"shop space / premises"},{"term":"pastelería","meaning":"bakery / cake shop"},{"term":"ahorros","meaning":"savings"},{"term":"seguridad","meaning":"certainty / confidence"},{"term":"atención al cliente","meaning":"customer service"},{"term":"esfuerzo","meaning":"effort"},{"term":"recién horneado","meaning":"freshly baked"}],"quiz":[{"id":"q1","type":"single","question":"¿Cuál era el sueño de Carla?","options":["Ser jefa en su empresa","Viajar por el mundo","Tener su propio negocio"],"answerIndex":2,"explanation":"Carla soñó durante años con tener su propio negocio."},{"id":"q2","type":"single","question":"¿Por qué no tomaba la decisión al principio?","options":["Porque no tenía dinero","Porque tenía miedo","Porque no tenía apoyo"],"answerIndex":1,"explanation":"El miedo siempre ganaba y no le permitía tomar la decisión."},{"id":"q3","type":"single","question":"¿Qué le escribió su amiga?","options":["Que debía quedarse en su trabajo","Que había un local disponible para su pastelería","Que el negocio no era buena idea"],"answerIndex":1,"explanation":"Su amiga le escribió que encontró un local perfecto para su idea de pastelería."},{"id":"q4","type":"single","question":"¿Qué recordó Carla mientras preparaba café?","options":["Los errores de su empresa","Los problemas con su jefa","Todo lo que había aprendido"],"answerIndex":2,"explanation":"Carla pensó en todo lo que había aprendido: organización, atención al cliente, esfuerzo."},{"id":"q5","type":"single","question":"¿Qué sintió cuando abrió su tienda?","options":["Duda","Arrepentimiento","Orgullo y alegría"],"answerIndex":2,"explanation":"Al abrir su tienda y oler el pan recién horneado, supo que había tomado la mejor decisión de su vida."},{"id":"q6","type":"single","question":"¿Qué aprendemos de la historia?","options":["Que es mejor no arriesgarse","Que a veces hay que vencer el miedo para crecer","Que los amigos siempre tienen razón"],"answerIndex":1,"explanation":"La historia nos enseña que a veces hay que vencer el miedo para lograr nuestros sueños y crecer."}],"snippet":"Durante años, Carla soñó con tener su propio negocio. Trabajaba en una empresa grande, con un salario estable y compañeros amables, pero cada día s..."},{"id":"b1-04","level":"b1","title":"Redes sociales y tiempo libre","duration":"1m 15s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/b1/B1_04_audio.mp3","transcript":"Diego: Hola, Laura. ¿Viste que hoy todos hablan del nuevo reto en redes sociales?\\nLaura: Sí, lo vi esta mañana. Me parece divertido, pero también un poco exagerado.\\nDiego: Yo creo que depende de cómo se use. A mí me gusta subir fotos cuando viajo, pero no publico todo.\\nLaura: A mí me pasa igual. Antes pasaba horas mirando videos, pero ahora trato de usar el teléfono solo un rato al día.\\nDiego: Yo también. A veces siento que las redes me quitan tiempo para otras cosas.\\nLaura: Sí, pero también tienen cosas buenas. Yo encontré mi trabajo actual gracias a una red profesional.\\nDiego: Es verdad. Creo que todo es cuestión de encontrar un equilibrio.\\nLaura: Exacto. Hay que saber controlarse.\\nDiego: Totalmente de acuerdo.\\nLaura: Bueno, es genial charlar de esto. Nos vemos luego.\\nDiego: Hasta pronto, Laura.","vocab":[{"term":"reto","meaning":"challenge"},{"term":"exagerado","meaning":"exaggerated"},{"term":"subir fotos","meaning":"to upload photos"},{"term":"publicar","meaning":"to post (online)"},{"term":"pasar horas","meaning":"to spend hours"},{"term":"red social","meaning":"social network"},{"term":"equilibrio","meaning":"balance"},{"term":"controlarse","meaning":"to control oneself"},{"term":"quitar tiempo","meaning":"to take away time"},{"term":"genial","meaning":"great / awesome"}],"quiz":[{"id":"q1","type":"single","question":"¿De qué hablan Diego y Laura?","options":["De su trabajo","De las redes sociales","De los viajes"],"answerIndex":1,"explanation":"Diego y Laura hablan sobre las redes sociales y cómo las usan."},{"id":"q2","type":"single","question":"¿Qué opina Laura sobre el reto en redes?","options":["Que es peligroso","Que no lo conoce","Que es divertido pero exagerado"],"answerIndex":2,"explanation":"Laura dice que le parece divertido, pero también un poco exagerado."},{"id":"q3","type":"single","question":"¿Qué hacen ambos ahora con el uso del teléfono?","options":["Pasan muchas horas conectados","Lo usan solo un rato al día","Lo dejaron de usar por completo"],"answerIndex":1,"explanation":"Laura dice que ahora trata de usar el teléfono solo un rato al día, y Diego está de acuerdo."},{"id":"q4","type":"single","question":"¿Qué ventaja menciona Laura sobre las redes sociales?","options":["Que ayudan a dormir mejor","Que encontró su trabajo gracias a ellas","Que no tienen nada positivo"],"answerIndex":1,"explanation":"Laura menciona que encontró su trabajo actual gracias a una red profesional."},{"id":"q5","type":"single","question":"¿En qué están de acuerdo al final?","options":["En que las redes deben eliminarse","En que deberían publicar más","En que hay que encontrar un equilibrio"],"answerIndex":2,"explanation":"Ambos están de acuerdo en que todo es cuestión de encontrar un equilibrio."}],"snippet":"Diego: Hola, Laura. ¿Viste que hoy todos hablan del nuevo reto en redes sociales."},{"id":"b1-05","level":"b1","title":"La entrevista de trabajo","duration":"1m 10s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/b1/B1_05_audio.mp3","snippet":"Laura tenía una entrevista en una empresa de tecnología y estaba un poco nerviosa. Había preparado su currículum y practicado sus respuestas frente al espejo.","transcript":"Laura tenía una entrevista en una empresa de tecnología y estaba un poco nerviosa. Había preparado su currículum y practicado sus respuestas frente al espejo.\\n\\nCuando llegó, el entrevistador, el señor Ramírez, la saludó con amabilidad.\\n—Buenos días, Laura. ¿Cómo estás?\\n—Buenos días, un poco nerviosa, pero muy contenta de estar aquí —respondió ella sonriendo.\\n\\nDurante la entrevista, hablaron sobre su experiencia anterior. Laura explicó que había trabajado tres años como asistente administrativa y que le gustaba aprender cosas nuevas.\\n—¿Por qué quieres trabajar con nosotros? —preguntó el señor Ramírez.\\n—Porque quiero seguir creciendo profesionalmente y creo que esta empresa me puede dar esa oportunidad —dijo Laura con confianza.\\n\\nAl final, el entrevistador le agradeció su tiempo y le dijo que la llamarían en unos días. Laura salió de la oficina con una sonrisa. Había hecho lo mejor que podía.","vocab":[{"term":"entrevista","meaning":"interview (formal conversation for a job)"},{"term":"currículum","meaning":"resume / CV"},{"term":"empresa","meaning":"company"},{"term":"experiencia","meaning":"experience"},{"term":"oportunidad","meaning":"opportunity"},{"term":"confianza","meaning":"confidence"},{"term":"asistente administrativa","meaning":"administrative assistant"},{"term":"crecer profesionalmente","meaning":"to grow professionally"},{"term":"frente al espejo","meaning":"in front of the mirror"},{"term":"amabilidad","meaning":"kindness"}],"quiz":[{"id":"q1","type":"single","question":"¿Dónde tenía la entrevista Laura?","options":["En un hospital","En una empresa de tecnología","En una escuela"],"answerIndex":1,"explanation":"Laura tenía una entrevista en una empresa de tecnología."},{"id":"q2","type":"single","question":"¿Cómo se sentía antes de la entrevista?","options":["Tranquila","Cansada","Nerviosa"],"answerIndex":2,"explanation":"Laura estaba un poco nerviosa antes de la entrevista."},{"id":"q3","type":"single","question":"¿Qué hizo para prepararse?","options":["Practicó sus respuestas","Hizo ejercicio","Escribió una carta"],"answerIndex":0,"explanation":"Laura había preparado su currículum y practicado sus respuestas frente al espejo."},{"id":"q4","type":"single","question":"¿Cuántos años trabajó como asistente administrativa?","options":["Dos","Tres","Cinco"],"answerIndex":1,"explanation":"Laura explicó que había trabajado tres años como asistente administrativa."},{"id":"q5","type":"single","question":"¿Cómo terminó la entrevista?","options":["Con una sonrisa","Con una discusión","Con una llamada telefónica"],"answerIndex":0,"explanation":"Laura salió de la oficina con una sonrisa después de la entrevista."}]},{"id":"b1-06","level":"b1","title":"En una peluquería","duration":"1m 5s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/b1/B1_06_audio.mp3","snippet":"Carla entró a la peluquería un sábado por la mañana. Quería cambiar de look porque tenía una fiesta importante esa noche.","transcript":"Carla entró a la peluquería un sábado por la mañana. Quería cambiar de look porque tenía una fiesta importante esa noche. La recibió Sofía, la estilista, con una sonrisa.\\n\\n—¡Hola! ¿Qué te gustaría hacerte hoy? —preguntó Sofía.\\n—Quiero cortarme el cabello un poco y también cambiar el color —respondió Carla.\\n\\nSofía le mostró algunas fotos con distintos tonos y estilos.\\n—Este tono de castaño claro te quedaría muy bien —dijo.\\n—Perfecto, confío en ti —respondió Carla.\\n\\nMientras hablaban, Carla contó que hacía meses que no visitaba una peluquería. Le encantaba el ambiente: la música, el aroma del champú y la sensación de renovarse.\\n\\nCuando Sofía terminó, Carla se miró al espejo y sonrió. El cambio era justo lo que necesitaba.","vocab":[{"term":"peluquería","meaning":"hair salon"},{"term":"estilista","meaning":"stylist / hairdresser"},{"term":"corte","meaning":"haircut"},{"term":"color","meaning":"color (hair dye)"},{"term":"tono","meaning":"tone / shade"},{"term":"cabello","meaning":"hair"},{"term":"champú","meaning":"shampoo"},{"term":"renovarse","meaning":"to renew oneself / to feel refreshed"},{"term":"castaño claro","meaning":"light brown"},{"term":"cambiar de look","meaning":"to change one\'s look"}],"quiz":[{"id":"q1","type":"single","question":"¿Por qué fue Carla a la peluquería?","options":["Porque tenía una entrevista de trabajo","Porque tenía una fiesta importante","Porque quería visitar a una amiga"],"answerIndex":1,"explanation":"Carla quería cambiar de look porque tenía una fiesta importante esa noche."},{"id":"q2","type":"single","question":"¿Qué quería hacer con su cabello?","options":["Cortarlo y cambiar el color","Peinarlo para una boda","Hacerse un tratamiento"],"answerIndex":0,"explanation":"Carla quería cortarse el cabello un poco y también cambiar el color."},{"id":"q3","type":"single","question":"¿Qué tono le recomendó Sofía?","options":["Negro oscuro","Castaño claro","Rubio intenso"],"answerIndex":1,"explanation":"Sofía le recomendó el tono de castaño claro."},{"id":"q4","type":"single","question":"¿Cómo reaccionó Sofía cuando la vio?","options":["Estaba apurada","Estaba seria","La recibió con una sonrisa"],"answerIndex":2,"explanation":"La recibió Sofía, la estilista, con una sonrisa."},{"id":"q5","type":"single","question":"¿Cómo se sintió Carla al final?","options":["Decepcionada","Cansada del cambio","Feliz con el resultado"],"answerIndex":2,"explanation":"Cuando Sofía terminó, Carla se miró al espejo y sonrió. El cambio era justo lo que necesitaba."}]},{"id":"b2-01","level":"b2","title":"La invitación inesperada","duration":"1m 30s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/b2/B2_01_audio.mp3","transcript":"Sofía trabaja en una empresa de marketing digital y lleva meses colaborando con Daniel, un diseñador del mismo equipo. Se llevan bien, aunque casi siempre hablan solo de trabajo.\\n\\nUn viernes, antes de salir de la oficina, Daniel le dijo con una sonrisa:\\n\\n—Oye, este fin de semana hay una exposición de arte moderno. ¿Te gustaría ir?\\n\\nSofía dudó unos segundos. No sabía si era una invitación amistosa o algo más. Finalmente respondió:\\n\\n—Claro, me encanta el arte.\\n\\nEl sábado se encontraron en el museo. Durante la visita, hablaron de sus artistas favoritos, pero también de sus sueños, viajes y cosas personales. Daniel parecía nervioso y, en un momento, mencionó:\\n\\n—Nunca pensé que tendríamos tanto en común.\\n\\nSofía sonrió, pero no dijo nada. Al despedirse, él le escribió al día siguiente:\\n\\n\\"Gracias por acompañarme, la pasé muy bien.\\"\\n\\nElla leyó el mensaje varias veces antes de responder:\\n\\n\\"Yo también.\\"","vocab":[{"term":"exposición","meaning":"exhibition"},{"term":"arte moderno","meaning":"modern art"},{"term":"colaborar","meaning":"to work together"},{"term":"dudar","meaning":"to hesitate"},{"term":"amistoso","meaning":"friendly"},{"term":"en común","meaning":"in common"},{"term":"acompañar","meaning":"to accompany"},{"term":"nervioso","meaning":"nervous"},{"term":"mensaje","meaning":"message"},{"term":"responder","meaning":"to reply"}],"quiz":[{"id":"q1","type":"single","question":"¿Dónde trabajan Sofía y Daniel?","options":["En un museo","En una escuela","En una empresa de marketing digital"],"answerIndex":2,"explanation":"Sofía trabaja en una empresa de marketing digital y Daniel es diseñador del mismo equipo."},{"id":"q2","type":"single","question":"¿Qué hizo Daniel el viernes antes de salir de la oficina?","options":["Invitó a Sofía a una exposición","Le pidió ayuda con un proyecto","Le dijo adiós rápidamente"],"answerIndex":0,"explanation":"Daniel invitó a Sofía a una exposición de arte moderno el fin de semana."},{"id":"q3","type":"single","question":"¿Qué pensó Sofía cuando recibió la invitación?","options":["Que era un error","Que era una reunión de trabajo","Que podría ser una cita"],"answerIndex":2,"explanation":"Sofía dudó porque no sabía si era una invitación amistosa o algo más (una cita)."},{"id":"q4","type":"single","question":"¿Cómo fue la conversación durante la exposición?","options":["Solo hablaron de arte","Hablaron de temas personales también","Discutieron por una pintura"],"answerIndex":1,"explanation":"Hablaron de sus artistas favoritos, pero también de sus sueños, viajes y cosas personales."},{"id":"q5","type":"single","question":"¿Qué se puede inferir del final de la historia?","options":["Que Sofía no disfrutó la cita","Que no volverán a hablar","Que ambos sienten interés mutuo"],"answerIndex":2,"explanation":"Los mensajes intercambiados y las respuestas sugieren que ambos disfrutaron y hay interés mutuo."}],"snippet":"Sofía trabaja en una empresa de marketing digital y lleva meses colaborando con Daniel, un diseñador del mismo equipo. Se llevan bien, aunque casi ..."},{"id":"b2-02","level":"b2","title":"La comida que nadie quiso probar","duration":"1m 45s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/b2/B2_02_audio.mp3","transcript":"El viernes por la noche, Lucía invitó a sus amigos a cenar en su casa. Todos llegaron puntuales y con mucha hambre. En la mesa había pan, frutas, refrescos y un plato cubierto con una tapa metálica.\\n\\n—Bueno —dijo Lucía sonriendo—, este es el plato principal, una receta tradicional de mi familia.\\n\\nTodos la miraron con curiosidad. Cuando levantó la tapa, apareció un guiso oscuro con un olor fuerte, lleno de especias y trozos de carne que nadie pudo reconocer.\\n\\n—¿Qué es? —preguntó Marcos, un poco nervioso.\\n—Es mole de olla —respondió Lucía—. Mi abuela lo prepara en todas las fiestas.\\n\\nHubo silencio. Nadie se movió. Entonces, Lucía sirvió un poco en su propio plato, lo probó y sonrió.\\n—Está buenísimo —dijo.\\n\\nPoco a poco, los demás se animaron. Primero probaron una cucharada, luego otra… y al final repitieron.\\n\\n—No puedo creerlo —dijo Marcos—. Pensé que no me iba a gustar, ¡pero está delicioso!\\n\\nLucía se rió.\\n—Por eso, en mi casa decimos: \\"si no lo pruebas, te pierdes la sorpresa\\".","vocab":[{"term":"guiso","meaning":"stew"},{"term":"receta tradicional","meaning":"traditional recipe"},{"term":"especias","meaning":"spices"},{"term":"trozos","meaning":"pieces / chunks"},{"term":"tapa metálica","meaning":"metal lid"},{"term":"probar","meaning":"to taste / to try"},{"term":"animarse","meaning":"to get encouraged / to dare"},{"term":"repetir","meaning":"to have seconds (eat again)"},{"term":"delicioso","meaning":"delicious"},{"term":"sorpresa","meaning":"surprise"}],"quiz":[{"id":"q1","type":"single","question":"¿Por qué Lucía decidió preparar un platillo tradicional?","options":["Para presumir sus habilidades como cocinera","Porque no tenía tiempo de cocinar otra cosa","Para compartir una parte de su cultura con sus amigos"],"answerIndex":2,"explanation":"Lucía preparó una receta tradicional de su familia para compartir su cultura con sus amigos."},{"id":"q2","type":"single","question":"¿Qué sugiere la reacción inicial de los invitados al ver el plato?","options":["Que no confiaban en la comida desconocida","Que estaban cansados","Que ya habían comido antes de llegar"],"answerIndex":0,"explanation":"El silencio y la falta de movimiento sugieren desconfianza hacia la comida que no reconocían."},{"id":"q3","type":"single","question":"¿Qué efecto produce el silencio cuando Lucía levanta la tapa?","options":["Indica que el guiso huele mal","Es una señal de respeto hacia la anfitriona","Muestra curiosidad y desconfianza al mismo tiempo"],"answerIndex":2,"explanation":"El silencio refleja que los invitados tienen curiosidad pero también dudas sobre el plato."},{"id":"q4","type":"single","question":"¿Por qué Lucía decide servirse primero?","options":["Porque tenía hambre","Para demostrar que el platillo era seguro y sabroso","Porque quería comer antes que los demás"],"answerIndex":1,"explanation":"Al probarlo primero y mostrar que le gusta, Lucía anima a los demás a probarlo."},{"id":"q5","type":"single","question":"¿Qué transformación ocurre en los invitados a lo largo de la historia?","options":["Pasan del entusiasmo al aburrimiento","Pasan del interés a la indiferencia","Pasan del rechazo a la aceptación"],"answerIndex":2,"explanation":"Los invitados pasan de no querer probar el plato a repetir y decir que está delicioso."},{"id":"q6","type":"single","question":"¿Qué enseñanza deja el final de la historia?","options":["Que la comida tradicional siempre es mejor","Que las primeras impresiones pueden ser engañosas","Que no hay que invitar amigos a cenar"],"answerIndex":1,"explanation":"La historia enseña que no debemos juzgar sin probar, porque podemos perdernos una sorpresa agradable."}],"snippet":"El viernes por la noche, Lucía invitó a sus amigos a cenar en su casa. Todos llegaron puntuales y con mucha hambre."},{"id":"b2-03","level":"b2","title":"El consejo de mi abuelo","duration":"1m 30s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/b2/B2_03_audio.mp3","transcript":"Cuando era niño, solía visitar a mi abuelo todos los fines de semana. Vivía en una casa pequeña, con un jardín lleno de árboles y herramientas viejas. Siempre tenía algo que reparar, pero también tiempo para sentarse conmigo a conversar.\\n\\nUn día le pregunté por qué nunca se quejaba de nada. Él sonrió y me dijo:\\n—Porque aprendí que quejarse no cambia las cosas, pero actuar sí.\\n\\nEn ese momento no entendí del todo lo que quería decir. Sin embargo, con los años, esas palabras empezaron a tener sentido. Cada vez que algo salía mal —un trabajo perdido, una discusión o un error— recordaba su voz tranquila.\\n\\nHace poco, cuando un proyecto importante fracasó, sentí ganas de rendirme. Pero en lugar de eso, respiré, preparé un café y volví a empezar.\\n\\nEse día comprendí que los consejos sencillos a veces son los que más fuerza tienen.","vocab":[{"term":"quejarse","meaning":"to complain"},{"term":"reparar","meaning":"to fix / to repair"},{"term":"discusión","meaning":"argument / discussion"},{"term":"rendirse","meaning":"to give up"},{"term":"fracasó","meaning":"failed"},{"term":"tranquilamente","meaning":"calmly"},{"term":"herramienta","meaning":"tool"},{"term":"consejo","meaning":"advice"},{"term":"tener sentido","meaning":"to make sense"},{"term":"volver a empezar","meaning":"to start again"}],"quiz":[{"id":"q1","type":"single","question":"¿Cómo era el abuelo del narrador?","options":["Impaciente y distraído","Tranquilo y trabajador","Estricto y distante"],"answerIndex":1,"explanation":"El abuelo siempre tenía algo que reparar pero también tiempo para conversar, mostrando que era tranquilo y trabajador."},{"id":"q2","type":"single","question":"¿Qué hacía el abuelo cada fin de semana?","options":["Dormía todo el día","Salía de viaje","Recibía visitas y arreglaba cosas"],"answerIndex":2,"explanation":"El narrador visitaba a su abuelo los fines de semana y el abuelo siempre tenía algo que reparar."},{"id":"q3","type":"single","question":"¿Qué quiso decir el abuelo con su consejo?","options":["Que es mejor evitar los problemas","Que hay que aceptar todo sin cambiar nada","Que actuar es más útil que quejarse"],"answerIndex":2,"explanation":"El abuelo dijo: \'quejarse no cambia las cosas, pero actuar sí\', enfatizando la importancia de la acción."},{"id":"q4","type":"single","question":"¿Por qué el narrador recuerda las palabras del abuelo?","options":["Porque le ayudaron en momentos difíciles","Porque se sintió confundido","Porque le recordaban su infancia feliz"],"answerIndex":0,"explanation":"Cada vez que algo salía mal, el narrador recordaba las palabras de su abuelo, lo que le ayudaba."},{"id":"q5","type":"single","question":"¿Qué hace el narrador cuando su proyecto fracasa?","options":["Se rinde y cambia de trabajo","Ignora el problema","Toma un descanso y empieza de nuevo"],"answerIndex":2,"explanation":"En lugar de rendirse, respiró, preparó un café y volvió a empezar."},{"id":"q6","type":"single","question":"¿Cuál es el mensaje principal del texto?","options":["Los abuelos siempre tienen razón","Los consejos simples pueden tener un gran impacto","Los problemas se resuelven con suerte"],"answerIndex":1,"explanation":"El narrador concluye que \'los consejos sencillos a veces son los que más fuerza tienen\'."}],"snippet":"Cuando era niño, solía visitar a mi abuelo todos los fines de semana. Vivía en una casa pequeña, con un jardín lleno de árboles y herramientas viejas."},{"id":"b2-04","level":"b2","title":"El humor en diferentes países","duration":"1m 40s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/b2/B2_04_audio.mp3","transcript":"Carla: Oye, Mateo, ¿te diste cuenta de que la gente aquí se ríe de cosas muy distintas?\\nMateo: Totalmente. El otro día conté un chiste en la oficina y nadie se rió.\\nCarla: ¿En serio? ¿Sobre qué era?\\nMateo: Sobre mi jefe… pero en mi país ese tipo de humor es normal. Aquí lo tomaron como falta de respeto.\\nCarla: Sí, eso pasa mucho. En México, por ejemplo, la gente se burla de sí misma todo el tiempo, pero hay temas que son muy delicados.\\nMateo: En mi país, si te ríes de ti mismo, la gente piensa que no te tomas en serio.\\nCarla: Qué curioso. Supongo que el humor refleja la cultura.\\n\\nMateo: Exacto. Y entender el humor local es casi tan difícil como aprender el idioma.\\nCarla: Pero cuando logras hacer reír a alguien en otra lengua… ahí sabes que realmente la dominas.\\nMateo: O al menos que ya no te da miedo equivocarte.\\nCarla: Eso también es parte del humor, ¿no? Reírse un poco de los errores.\\nMateo: Sí, y por suerte, todos los cometemos.","vocab":[{"term":"chiste","meaning":"joke"},{"term":"falta de respeto","meaning":"disrespect"},{"term":"burlarse de sí mismo","meaning":"to laugh at oneself"},{"term":"delicado","meaning":"sensitive / delicate"},{"term":"tomarse en serio","meaning":"to take oneself seriously"},{"term":"reflejar","meaning":"to reflect"},{"term":"equivocarse","meaning":"to make a mistake"},{"term":"dominar un idioma","meaning":"to master a language"},{"term":"por suerte","meaning":"luckily"},{"term":"tema","meaning":"topic / subject"}],"quiz":[{"id":"q1","type":"single","question":"¿Qué le pasó a Mateo en la oficina?","options":["Hizo un comentario serio","Ofendió a su jefe directamente","Contó un chiste que no causó risa"],"answerIndex":2,"explanation":"Mateo contó un chiste en la oficina y nadie se rió porque fue tomado como falta de respeto."},{"id":"q2","type":"single","question":"¿Por qué no se rieron sus compañeros?","options":["Porque el chiste era aburrido","Porque no entendieron el idioma","Porque el tema se consideró inapropiado"],"answerIndex":2,"explanation":"En ese país, bromear sobre el jefe se tomó como falta de respeto, aunque en el país de Mateo es normal."},{"id":"q3","type":"single","question":"¿Qué diferencia cultural menciona Carla sobre México?","options":["Que la gente evita bromear","Que se ríen de sí mismos con frecuencia","Que no entienden el humor extranjero"],"answerIndex":1,"explanation":"Carla menciona que en México la gente se burla de sí misma todo el tiempo."},{"id":"q4","type":"single","question":"Según Mateo, ¿qué piensa la gente en su país si te ríes de ti mismo?","options":["Que eres humilde","Que eres divertido","Que no te tomas en serio"],"answerIndex":2,"explanation":"Mateo dice que en su país, si te ríes de ti mismo, la gente piensa que no te tomas en serio."},{"id":"q5","type":"single","question":"¿Qué compara Carla con aprender el humor local?","options":["Aprender el idioma","Conocer la historia del país","Entender los gestos"],"answerIndex":0,"explanation":"Mateo dice que entender el humor local es casi tan difícil como aprender el idioma."},{"id":"q6","type":"single","question":"¿Qué idea comparten ambos al final?","options":["Que el humor solo funciona en el propio idioma","Que los chistes deben evitarse en otros países","Que reírse de los errores es parte de aprender"],"answerIndex":2,"explanation":"Ambos concluyen que reírse de los errores es parte del humor y del aprendizaje."}],"snippet":"Carla: Oye, Mateo, ¿te diste cuenta de que la gente aquí se ríe de cosas muy distintas. Mateo: Totalmente."},{"id":"b2-05","level":"b2","title":"El vecino misterioso","duration":"1m 20s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/b2/B2_05_audio.mp3","snippet":"Durante semanas, Laura observó que su nuevo vecino salía solo por la noche. Apenas lo veía durante el día y, cuando lo hacía, él apenas saludaba.","transcript":"Durante semanas, Laura observó que su nuevo vecino salía solo por la noche. Apenas lo veía durante el día y, cuando lo hacía, él apenas saludaba. En el edificio todos hablaban de él: algunos decían que trabajaba con computadoras, otros que simplemente era antisocial.\\n\\nUna noche, un apagón dejó sin luz a todo el edificio. Laura estaba buscando velas cuando alguien tocó a su puerta. Era el vecino, con una linterna en la mano.\\n\\n—Vi que estabas sin luz —le dijo—, tengo una batería extra, si quieres te la dejo.\\n\\nConversaron unos minutos, y Laura descubrió que él era enfermero y que sus turnos nocturnos lo obligaban a dormir de día.\\n\\nDesde entonces, cada vez que lo ve, le sonríe con cierta vergüenza. Había pasado semanas imaginando historias… y todas eran falsas.","vocab":[{"term":"apagón","meaning":"power outage"},{"term":"linterna","meaning":"flashlight"},{"term":"turno nocturno","meaning":"night shift"},{"term":"antisocial","meaning":"antisocial / unfriendly"},{"term":"batería extra","meaning":"extra battery"},{"term":"imaginar historias","meaning":"to imagine / make up stories"},{"term":"vergüenza","meaning":"shame / embarrassment"},{"term":"falsa impresión","meaning":"false impression"},{"term":"enfermero","meaning":"nurse"},{"term":"prejuicio","meaning":"prejudice"}],"quiz":[{"id":"q1","type":"single","question":"¿Qué pensaban los vecinos sobre el hombre?","options":["Que era amable con todos","Que tenía un trabajo extraño o era antisocial","Que organizaba fiestas nocturnas"],"answerIndex":1,"explanation":"En el edificio todos hablaban de él: algunos decían que trabajaba con computadoras, otros que simplemente era antisocial."},{"id":"q2","type":"single","question":"¿Qué reveló el apagón sobre el vecino?","options":["Que en realidad era ingeniero eléctrico","Que trabajaba de noche y era solidario","Que tenía miedo a la oscuridad"],"answerIndex":1,"explanation":"Laura descubrió que él era enfermero y que sus turnos nocturnos lo obligaban a dormir de día, y él le ofreció ayuda con la batería."},{"id":"q3","type":"single","question":"¿Por qué Laura sintió vergüenza al final?","options":["Porque el vecino no aceptó su ayuda","Porque se dio cuenta de que lo había juzgado mal","Porque olvidó darle las gracias"],"answerIndex":1,"explanation":"Laura sintió vergüenza porque había pasado semanas imaginando historias sobre él y todas eran falsas."},{"id":"q4","type":"single","question":"¿Qué actitud tiene la historia hacia los prejuicios?","options":["Los considera inevitables","Los presenta como algo divertido","Los critica mostrando una lección"],"answerIndex":2,"explanation":"La historia muestra cómo Laura juzgó mal a su vecino basándose en apariencias, enseñando una lección sobre los prejuicios."},{"id":"q5","type":"single","question":"¿Qué mensaje principal transmite la historia?","options":["Que hay que desconfiar de los vecinos","Que las apariencias pueden engañar","Que el trabajo nocturno es difícil"],"answerIndex":1,"explanation":"El mensaje principal es que las apariencias pueden engañar y no debemos juzgar sin conocer a las personas."}]},{"id":"b2-06","level":"b2","title":"El error en la presentación","duration":"1m 15s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/b2/B2_06_audio.mp3","snippet":"Daniel llevaba dos semanas preparando una presentación muy importante para su empresa. Revisó cada dato, cada gráfico y ensayó su discurso varias veces frente al espejo.","transcript":"Daniel llevaba dos semanas preparando una presentación muy importante para su empresa. Revisó cada dato, cada gráfico y ensayó su discurso varias veces frente al espejo.\\n\\nEl día de la reunión, todo marchaba perfecto hasta que, en medio de la exposición, notó que el gráfico principal tenía una cifra equivocada. Por un instante, sintió que el suelo se movía bajo sus pies.\\n\\nSin embargo, respiró hondo, sonrió y dijo:\\n—Parece que mi gráfico también necesita un café, igual que yo.\\n\\nLa sala estalló en risas, y Daniel continuó sin perder el control. Al final, su jefe se acercó y le dijo:\\n—Tu presentación fue excelente. Los errores ocurren, lo importante es cómo reaccionas.","vocab":[{"term":"ensayar","meaning":"to rehearse / to practice"},{"term":"cifra","meaning":"number / figure"},{"term":"equivocada","meaning":"wrong / incorrect"},{"term":"respirar hondo","meaning":"to take a deep breath / to calm down"},{"term":"perder el control","meaning":"to lose control"},{"term":"estallar en risas","meaning":"to burst out laughing"},{"term":"reaccionar","meaning":"to react"},{"term":"confianza","meaning":"confidence"},{"term":"exposición","meaning":"presentation / exposition"},{"term":"gráfico","meaning":"chart / graph"}],"quiz":[{"id":"q1","type":"single","question":"¿Qué demuestra la reacción de Daniel ante el error?","options":["Que se rinde fácilmente","Que ignora los problemas","Que mantiene la calma y usa el humor"],"answerIndex":2,"explanation":"Daniel respiró hondo, sonrió y usó el humor para manejar la situación del error en el gráfico."},{"id":"q2","type":"single","question":"¿Por qué el jefe valora su presentación?","options":["Porque el contenido era perfecto","Porque supo manejar bien la situación","Porque nadie notó el error"],"answerIndex":1,"explanation":"El jefe dijo que los errores ocurren, lo importante es cómo reaccionas, valorando la forma en que Daniel manejó la situación."},{"id":"q3","type":"single","question":"¿Qué enseñanza deja la historia?","options":["Que los errores deben ocultarse","Que es mejor no hacer presentaciones","Que la actitud puede ser más importante que la perfección"],"answerIndex":2,"explanation":"La historia enseña que cómo reaccionas ante los errores puede ser más importante que ser perfecto."},{"id":"q4","type":"single","question":"¿Qué simboliza la frase \'mi gráfico también necesita un café\'?","options":["Una excusa técnica","Una forma ligera de reconocer el fallo","Un comentario sin sentido"],"answerIndex":1,"explanation":"La frase fue una forma humorística y ligera de reconocer el error sin perder la compostura."},{"id":"q5","type":"single","question":"¿Qué cualidad destaca más en Daniel?","options":["Su memoria","Su honestidad y autocontrol","Su velocidad para corregir errores"],"answerIndex":1,"explanation":"Daniel destaca por su honestidad al reconocer el error y su autocontrol al no perder la calma."}]},{"id":"c1-01","level":"c1","title":"El silencio en las conversaciones","duration":"1m 50s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/c1/C1_01_audio.mp3","transcript":"Entrevistadora: Hoy hablamos con Carlos Méndez, psicólogo especializado en comunicación interpersonal. Carlos, en tus charlas mencionas que el silencio es una forma de comunicación. ¿A qué te refieres exactamente?\\n\\nCarlos: Muchas personas piensan que comunicarse es hablar, pero el silencio también transmite mensajes. En una conversación, el silencio puede significar incomodidad, desacuerdo o simplemente reflexión. Lo interesante es que cada cultura interpreta esos silencios de manera diferente.\\n\\nEntrevistadora: ¿Podrías darnos un ejemplo?\\n\\nCarlos: Claro. En algunos países asiáticos, guardar silencio se considera una señal de respeto. En cambio, en muchos países occidentales, el silencio se percibe como algo negativo, como si faltara interés o no hubiera nada que decir. Sin embargo, cuando las personas aprenden a tolerar el silencio, descubren que en esos momentos también puede haber conexión, empatía o incluso confianza.\\n\\nEntrevistadora: Entonces, ¿escuchar también es una forma de hablar?\\n\\nCarlos: Exactamente. Escuchar con atención es una forma profunda de comunicación. A veces, lo más valioso que podemos decir… es nada.","vocab":[{"term":"comunicación interpersonal","meaning":"interpersonal communication"},{"term":"transmitir","meaning":"to convey / communicate"},{"term":"incomodidad","meaning":"discomfort"},{"term":"desacuerdo","meaning":"disagreement"},{"term":"reflexión","meaning":"reflection / deep thought"},{"term":"respeto","meaning":"respect"},{"term":"empatía","meaning":"empathy"},{"term":"confianza","meaning":"trust"},{"term":"tolerar","meaning":"to tolerate"},{"term":"atención plena","meaning":"full attention / mindfulness"}],"quiz":[{"id":"q1","type":"single","question":"Según Carlos, ¿qué papel juega el silencio en la comunicación?","options":["Es un obstáculo para entender a los demás","Es una muestra de falta de educación","Es una herramienta que puede tener diferentes significados"],"answerIndex":2,"explanation":"Carlos explica que el silencio transmite mensajes y puede significar diferentes cosas según el contexto."},{"id":"q2","type":"single","question":"¿Por qué menciona Carlos las diferencias culturales?","options":["Para demostrar que el silencio no tiene un solo sentido","Para resaltar que hablar demasiado es mejor","Para justificar que el silencio es incómodo"],"answerIndex":0,"explanation":"Carlos usa ejemplos culturales para mostrar que el silencio se interpreta de manera diferente según la cultura."},{"id":"q3","type":"single","question":"Cuando Carlos dice que \\"escuchar también es una forma de hablar\\", quiere decir que:","options":["Las personas que escuchan poco hablan mejor","La escucha activa también comunica algo importante","Las palabras son más valiosas que el silencio"],"answerIndex":1,"explanation":"Carlos enfatiza que escuchar con atención es una forma profunda de comunicación."},{"id":"q4","type":"single","question":"¿Qué tipo de actitud propone Carlos hacia los silencios?","options":["Rechazarlos porque generan tensión","Evitarlos en toda conversación","Aprender a tolerarlos y comprender su valor"],"answerIndex":2,"explanation":"Carlos sugiere que al tolerar el silencio, las personas descubren su valor para la conexión y empatía."},{"id":"q5","type":"single","question":"¿Qué significado implícito se puede deducir de la última frase de Carlos (\\"A veces, lo más valioso que podemos decir… es nada\\")?","options":["Que el silencio demuestra inseguridad","Que callar puede expresar más que hablar","Que no vale la pena escuchar a los demás"],"answerIndex":1,"explanation":"La frase sugiere que a veces el silencio comunica más profundamente que las palabras."}],"snippet":"Entrevistadora: Hoy hablamos con Carlos Méndez, psicólogo especializado en comunicación interpersonal. Carlos, en tus charlas mencionas que el sile..."},{"id":"c1-02","level":"c1","title":"La frontera invisible","duration":"2m 00s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/c1/C1_02_audio.mp3","transcript":"No todas las fronteras se pueden ver en un mapa. Algunas existen solo en la mente: límites invisibles que separan a las personas aunque compartan el mismo lugar.\\n\\nCuando Daniel se mudó a la gran ciudad, sintió esa frontera cada día. No era un muro real, sino una distancia hecha de miradas, acentos y silencios. En su trabajo, todos lo saludaban con cortesía, pero pocas veces con interés. \\"Habla raro\\", escuchó una vez por casualidad. Desde entonces, se volvió más cuidadoso con sus palabras.\\n\\nCon el tiempo, aprendió a moverse entre dos mundos: el de donde venía y el que intentaba habitar. Sin embargo, algo en él empezó a cambiar. Ya no sabía si debía adaptarse o resistirse, si perder su forma de hablar era ganar o rendirse.\\n\\nUna tarde, en el metro, una niña le preguntó de dónde era. \\"De aquí\\", respondió después de una pausa. Y por primera vez, lo dijo sin miedo, sin disculpas.\\n\\nEntonces comprendió que la frontera no estaba afuera, sino dentro: entre lo que los demás ven y lo que uno decide ser.","vocab":[{"term":"frontera invisible","meaning":"invisible boundary"},{"term":"acento","meaning":"accent"},{"term":"cortesía","meaning":"politeness / courtesy"},{"term":"adaptarse","meaning":"to adapt"},{"term":"rendirse","meaning":"to give up / to surrender"},{"term":"habitar","meaning":"to inhabit"},{"term":"distancia simbólica","meaning":"symbolic distance"},{"term":"disculparse","meaning":"to apologize"},{"term":"resistirse","meaning":"to resist"},{"term":"pertenecer","meaning":"to belong"}],"quiz":[{"id":"q1","type":"single","question":"¿Qué tipo de frontera experimenta Daniel al llegar a la ciudad?","options":["Una frontera económica","Una frontera geográfica","Una frontera cultural y emocional, más que física"],"answerIndex":2,"explanation":"El texto describe fronteras invisibles que existen en la mente y en las actitudes, no físicas."},{"id":"q2","type":"single","question":"¿Qué significado tiene la frase \\"no era un muro real, sino una distancia hecha de miradas\\"?","options":["Que la exclusión se manifestaba de forma sutil, no abierta","Que la gente lo ignoraba por completo","Que la distancia física era muy grande"],"answerIndex":0,"explanation":"La frase describe cómo la exclusión social se expresa de manera indirecta a través de miradas y actitudes."},{"id":"q3","type":"single","question":"¿Por qué Daniel se volvió más cuidadoso con sus palabras?","options":["Porque empezó a estudiar otro idioma","Porque tenía miedo de cometer errores","Porque no entendía el acento local"],"answerIndex":1,"explanation":"Después de escuchar que \\"habla raro\\", Daniel se hizo más consciente y cuidadoso al hablar."},{"id":"q4","type":"single","question":"¿Qué dilema interior enfrenta el protagonista?","options":["Si debe mudarse de nuevo","Si debe mejorar su educación formal","Si debe cambiar para integrarse o mantenerse fiel a sí mismo"],"answerIndex":2,"explanation":"Daniel se debate entre adaptarse (perdiendo su forma de hablar) o resistirse y mantener su identidad."},{"id":"q5","type":"single","question":"¿Qué representa la respuesta \\"De aquí\\" al final del texto?","options":["Una mentira para evitar conflicto","Una forma de cerrar la conversación rápidamente","Una declaración de identidad y aceptación"],"answerIndex":2,"explanation":"Al responder \\"De aquí\\" sin miedo ni disculpas, Daniel afirma su derecho a pertenecer al lugar."},{"id":"q6","type":"single","question":"¿Cuál podría considerarse el mensaje central de la historia?","options":["La pertenencia no depende del lugar, sino de la aceptación personal","Los acentos siempre causan discriminación","Las grandes ciudades son frías e impersonales"],"answerIndex":0,"explanation":"El texto concluye que la frontera está dentro, sugiriendo que la pertenencia es una decisión personal."},{"id":"q7","type":"single","question":"¿Qué tono domina el texto?","options":["Crítico y agresivo","Alegre y optimista","Melancólico y reflexivo"],"answerIndex":2,"explanation":"El texto mantiene un tono reflexivo sobre la identidad y la pertenencia, con un matiz melancólico."},{"id":"q8","type":"single","question":"¿Por qué el título \\"La frontera invisible\\" resulta adecuado?","options":["Porque el protagonista trabaja en una frontera","Porque hace referencia a límites internos e intangibles","Porque simboliza una línea física no reconocida por el gobierno"],"answerIndex":1,"explanation":"El título refiere a las fronteras mentales y sociales, no físicas, que separan a las personas."}],"snippet":"No todas las fronteras se pueden ver en un mapa. Algunas existen solo en la mente: límites invisibles que separan a las personas aunque compartan e..."},{"id":"c1-03","level":"c1","title":"El cerebro y la creatividad","duration":"2m 10s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/c1/C1_03_audio.mp3","transcript":"Durante mucho tiempo, la ciencia creyó que el cerebro funcionaba como una máquina: una estructura rígida, donde cada parte tenía una tarea fija. Sin embargo, hoy sabemos que no es así. El cerebro cambia, se adapta y se reinventa constantemente.\\n\\nLa creatividad nace de esa flexibilidad. No aparece solo cuando un artista pinta o un músico compone; surge también cuando alguien encuentra una nueva forma de resolver un problema cotidiano. Cada vez que unimos ideas que nunca habían estado juntas, estamos creando algo.\\n\\nCuriosamente, los estudios muestran que el cerebro creativo no trabaja más, sino de otra manera. En lugar de seguir un camino lógico y lineal, explora rutas paralelas, conexiones inesperadas. Por eso muchas ideas brillantes surgen cuando estamos distraídos, caminando o en la ducha: el cerebro aprovecha ese espacio libre para conectar puntos invisibles.\\n\\nPero la creatividad no depende solo de la inspiración. También exige disciplina, paciencia y tolerancia al error. Un buen artista, un buen científico o un buen maestro no crean por accidente, sino porque practican la curiosidad cada día.\\n\\nEn el fondo, ser creativo no es inventar algo nuevo, sino mirar lo viejo con ojos distintos.","vocab":[{"term":"estructura rígida","meaning":"rigid structure"},{"term":"adaptarse","meaning":"to adapt"},{"term":"reinventarse","meaning":"to reinvent oneself"},{"term":"flexibilidad","meaning":"flexibility"},{"term":"resolver un problema","meaning":"to solve a problem"},{"term":"conexiones inesperadas","meaning":"unexpected connections"},{"term":"lineal","meaning":"linear"},{"term":"tolerancia al error","meaning":"tolerance for error"},{"term":"inspiración","meaning":"inspiration"}],"quiz":[{"id":"q1","type":"single","question":"¿Qué idea principal cuestiona el texto sobre el cerebro?","options":["Que solo los artistas son creativo","Que funciona de forma predecible y fija","Que la creatividad no tiene base científica"],"answerIndex":1,"explanation":"El texto cuestiona la vieja idea de que el cerebro funciona como una máquina rígida."},{"id":"q2","type":"single","question":"Según el texto, ¿dónde puede manifestarse la creatividad?","options":["Solo en el arte y la música","En los sueños o estados inconscientes","En cualquier situación donde se combinen ideas nuevas"],"answerIndex":2,"explanation":"El texto señala que la creatividad surge cuando alguien encuentra una nueva forma de resolver cualquier problema."},{"id":"q3","type":"single","question":"¿Qué revela el hecho de que las ideas surjan cuando estamos distraídos?","options":["Que la inspiración depende de la suerte","Que el cerebro necesita descanso para procesar información de manera libre","Que el pensamiento lógico no es importante"],"answerIndex":1,"explanation":"El cerebro aprovecha ese espacio libre para conectar puntos invisibles cuando estamos distraídos."},{"id":"q4","type":"single","question":"¿Qué actitud propone el texto hacia el error?","options":["Evitarlo a toda costa","Analizarlo solo desde la ciencia","Considerarlo parte del proceso creativo"],"answerIndex":2,"explanation":"El texto menciona que la creatividad exige tolerancia al error como parte del proceso."},{"id":"q5","type":"single","question":"¿Qué relación establece el autor entre creatividad y disciplina?","options":["Se complementan: la creatividad requiere constancia","Son opuestas: una espontánea, la otra rígida","La disciplina impide que surjan ideas nuevas"],"answerIndex":0,"explanation":"El texto afirma que la creatividad no depende solo de la inspiración, sino también de disciplina y práctica diaria."},{"id":"q6","type":"single","question":"¿Qué metáfora resume mejor el mensaje del texto?","options":["El cerebro como una máquina que ejecuta órdenes","El cerebro como un mapa que se reconfigura con cada pensamiento","El cerebro como una caja que guarda recuerdos"],"answerIndex":1,"explanation":"El texto enfatiza que el cerebro cambia, se adapta y se reinventa constantemente."},{"id":"q7","type":"single","question":"¿Qué significado tiene \\"mirar lo viejo con ojos distintos\\"?","options":["Recordar experiencias del pasado","Valorar lo tradicional por encima de lo nuevo","Ver lo conocido desde una nueva perspectiva"],"answerIndex":2,"explanation":"La frase final sugiere que ser creativo es ver las cosas conocidas desde una perspectiva diferente."},{"id":"q8","type":"single","question":"¿Qué tono domina el texto?","options":["Humorístico y ligero","Científico con matices inspiradores","Pesimista y crítico"],"answerIndex":1,"explanation":"El texto combina información científica sobre el cerebro con un mensaje inspirador sobre la creatividad."}],"snippet":"Durante mucho tiempo, la ciencia creyó que el cerebro funcionaba como una máquina: una estructura rígida, donde cada parte tenía una tarea fija. Si..."},{"id":"c1-04","level":"c1","title":"Entre la ironía y la verdad","duration":"2m 00s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/c1/C1_04_audio.mp3","transcript":"Locutora: Bienvenidos a \\"Conversaciones al margen\\". Hoy hablaremos de un tema que todos usamos, pero pocos comprendemos: la ironía. ¿Es una forma de humor o un disfraz de la verdad?\\n\\nInvitado: Depende del contexto. La ironía tiene algo de espejo: refleja lo que pensamos, pero distorsionado. No siempre se usa para hacer reír; a veces sirve para decir lo que no puede decirse directamente.\\n\\nLocutora: Como una especie de lenguaje secreto.\\n\\nInvitado: Exacto. La ironía puede protegernos de la confrontación. Por ejemplo, cuando alguien dice \\"Qué puntual eres\\" a quien llega media hora tarde, no pretende elogiarlo. Pero ese mismo tono, en otro país o en otra generación, podría sonar simplemente educado.\\n\\nLocutora: Entonces, ¿la ironía es universal?\\n\\nInvitado: No del todo. En algunos lugares, se percibe como una muestra de inteligencia; en otros, como falta de sinceridad. Lo fascinante es que exige complicidad: si nadie la entiende, deja de ser ironía y se convierte en malentendido.\\n\\nLocutora: En resumen, la ironía habita ese espacio ambiguo entre el ingenio y la provocación.\\n\\nInvitado: Sí. Y quizás por eso incomoda tanto: porque revela la verdad, pero disfrazada de sonrisa.","vocab":[{"term":"ironía","meaning":"irony — recurso lingüístico donde se expresa lo contrario de lo que se quiere decir"},{"term":"disfrazar","meaning":"to disguise — encubrir una intención o sentimiento verdadero"},{"term":"distorsionado","meaning":"distorted — alterado o modificado en su forma o sentido"},{"term":"confrontación","meaning":"confrontation — enfrentamiento directo o verbal"},{"term":"elogiar","meaning":"to praise — expresar admiración o reconocimiento"},{"term":"universal","meaning":"universal — que se aplica a todas las culturas o contextos"},{"term":"complicidad","meaning":"complicity — entendimiento implícito o conexión entre quienes comparten un código"},{"term":"ambigüedad","meaning":"ambiguity — cualidad de algo que puede interpretarse de varias maneras"},{"term":"ingenio","meaning":"wit — habilidad para expresar ideas de manera original o inteligente"},{"term":"provocación","meaning":"provocation — acción que busca generar una reacción emocional o intelectual"}],"quiz":[{"id":"q1","type":"single","question":"Según el invitado, ¿cuál es la función más profunda de la ironía?","options":["Provocar risa de manera ligera","Evitar cualquier tipo de conflicto","Expresar verdades de forma indirecta"],"answerIndex":2,"explanation":"El invitado explica que la ironía sirve para decir lo que no puede decirse directamente."},{"id":"q2","type":"single","question":"¿Qué papel juega el contexto en la interpretación de la ironía?","options":["Es esencial, porque determina si el mensaje resulta gracioso o hiriente","Es irrelevante: la ironía siempre se entiende igual","Solo influye en conversaciones formales"],"answerIndex":0,"explanation":"El invitado menciona que el mismo tono puede interpretarse diferente en otro país o generación."},{"id":"q3","type":"single","question":"¿Qué implica que la ironía \\"exija complicidad\\"?","options":["Que depende del tono de voz","Que solo funciona entre personas que se comprenden mutuamente","Que debe ser utilizada con humor inteligente"],"answerIndex":1,"explanation":"El invitado afirma que si nadie la entiende, deja de ser ironía y se convierte en malentendido."},{"id":"q4","type":"single","question":"¿Qué diferencia cultural menciona el invitado?","options":["En América Latina no existe la ironía","En Europa se considera una forma de insulto","En algunos países la ironía se asocia con inteligencia; en otros, con falta de sinceridad"],"answerIndex":2,"explanation":"El invitado señala que la ironía se percibe de manera diferente según el lugar."},{"id":"q5","type":"single","question":"¿Qué relación establece la locutora entre ironía y verdad?","options":["La ironía oculta la verdad detrás del sarcasmo","La ironía destruye la verdad","La ironía sustituye la verdad por humor"],"answerIndex":0,"explanation":"La locutora pregunta si la ironía es un disfraz de la verdad, lo que el invitado confirma."},{"id":"q6","type":"single","question":"¿Qué se sugiere sobre el tono irónico en distintos contextos culturales?","options":["Que siempre produce confusión","Que su interpretación depende del entorno y del vínculo entre interlocutores","Que es más fácil de entender por escrito que en voz"],"answerIndex":1,"explanation":"El texto explica que el contexto cultural y generacional determina cómo se interpreta la ironía."},{"id":"q7","type":"single","question":"¿Por qué, según el invitado, la ironía puede incomodar?","options":["Porque no todos entienden los chistes","Porque interrumpe la conversación formal","Porque obliga a reconocer verdades que preferimos ignorar"],"answerIndex":2,"explanation":"El invitado concluye que la ironía incomoda porque revela la verdad, aunque disfrazada."},{"id":"q8","type":"single","question":"¿Qué metáfora resume el sentido final del texto?","options":["\\"La ironía es una máscara de respeto.\\"","\\"La ironía revela la verdad, pero disfrazada de sonrisa.\\"","\\"La ironía es el idioma del humor.\\""],"answerIndex":1,"explanation":"Esta frase del invitado sintetiza la idea central: la ironía como vehículo de verdades incómodas."}],"snippet":"Locutora: Bienvenidos a \\"Conversaciones al margen\\". Hoy hablaremos de un tema que todos usamos, pero pocos comprendemos: la ironía."},{"id":"c1-05","level":"c1","title":"Las decisiones y el azar","duration":"1m 45s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/c1/C1_05_audio.mp3","snippet":"Locutora: Bienvenidos a \\"Perspectivas\\", el espacio donde exploramos cómo pensamos y decidimos. Hoy hablamos de un tema tan cotidiano como misterioso: el azar.","transcript":"Locutora: Bienvenidos a \\"Perspectivas\\", el espacio donde exploramos cómo pensamos y decidimos. Hoy hablamos de un tema tan cotidiano como misterioso: el azar.\\n\\nInvitado: Solemos creer que nuestras decisiones son racionales, que controlamos cada paso que damos. Pero, si miramos con atención, descubrimos que muchos de nuestros grandes cambios empezaron con algo pequeño e inesperado: una conversación, una coincidencia, un retraso, una llamada.\\n\\nLocutora: Es verdad. A veces basta un minuto para que todo cambie.\\n\\nInvitado: Exacto. Lo interesante es que el azar no elimina nuestra libertad, sino que la desafía. Podemos elegir, sí, pero lo hacemos dentro de un escenario que no controlamos. Y en ese equilibrio entre lo planeado y lo imprevisible se juega gran parte de nuestra vida.\\n\\nLocutora: Entonces, ¿somos responsables de lo que elegimos, incluso si el contexto nos empuja?\\n\\nInvitado: Tal vez la libertad no esté en controlar las circunstancias, sino en cómo respondemos a ellas. No elegimos los dados, pero sí cómo jugamos la partida.","vocab":[{"term":"azar","meaning":"chance / randomness"},{"term":"coincidencia","meaning":"coincidence"},{"term":"circunstancia","meaning":"circumstance"},{"term":"equilibrio","meaning":"balance"},{"term":"desafiar","meaning":"to challenge"},{"term":"imprevisible","meaning":"unpredictable"},{"term":"racional","meaning":"rational"},{"term":"libertad","meaning":"freedom"},{"term":"escenario","meaning":"scenario / setting"},{"term":"partida","meaning":"game / match"}],"quiz":[{"id":"q1","type":"single","question":"Según el invitado, ¿qué papel juega el azar en nuestras vidas?","options":["Controla absolutamente todo lo que ocurre","Elimina completamente la libertad","Desafía nuestra libertad y forma parte de nuestras decisiones"],"answerIndex":2,"explanation":"El invitado menciona que el azar no elimina nuestra libertad, sino que la desafía."},{"id":"q2","type":"single","question":"¿Qué ejemplo se da para mostrar cómo algo pequeño puede cambiarlo todo?","options":["Un viaje planificado con meses de anticipación","Una conversación o coincidencia inesperada","Un estudio científico sobre decisiones"],"answerIndex":1,"explanation":"El invitado menciona que muchos cambios empezaron con algo pequeño e inesperado: una conversación, una coincidencia, un retraso, una llamada."},{"id":"q3","type":"single","question":"¿Qué significa la frase \'no elegimos los dados, pero sí cómo jugamos la partida\'?","options":["Que el azar determina totalmente el resultado","Que no controlamos las circunstancias, pero sí nuestras reacciones","Que debemos evitar los riesgos al decidir"],"answerIndex":1,"explanation":"Esta frase simboliza que aunque no podemos controlar las circunstancias (los dados), sí podemos elegir cómo respondemos a ellas (cómo jugamos)."},{"id":"q4","type":"single","question":"¿Qué relación propone el texto entre libertad y contexto?","options":["La libertad depende de ignorar el contexto","El contexto determina completamente la libertad","La libertad existe dentro de límites que no controlamos"],"answerIndex":2,"explanation":"El invitado explica que podemos elegir, pero lo hacemos dentro de un escenario que no controlamos."},{"id":"q5","type":"single","question":"¿Cuál podría ser el mensaje principal del texto?","options":["No vale la pena planear porque todo depende del azar","La vida es un equilibrio entre lo planeado y lo imprevisible","El azar es más importante que la responsabilidad"],"answerIndex":1,"explanation":"El invitado menciona que en ese equilibrio entre lo planeado y lo imprevisible se juega gran parte de nuestra vida."}]},{"id":"c1-06","level":"c1","title":"Una noche inolvidable en el Bernabéu","duration":"2m 05s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/c1/C1_06_audio.mp3","snippet":"Locutor: Anoche, el estadio Santiago Bernabéu volvió a vivir una de esas noches que quedan grabadas en la memoria colectiva.","transcript":"Locutor: Anoche, el estadio Santiago Bernabéu volvió a vivir una de esas noches que quedan grabadas en la memoria colectiva. El Real Madrid se impuso tres a dos frente al Manchester City en un partido que tuvo de todo: emoción, polémica y momentos de auténtico arte futbolístico.\\n\\nReportera: Desde el primer minuto, ambos equipos mostraron sus cartas. El City dominó la posesión, fiel a su estilo de pases cortos y ritmo constante. Pero el Madrid respondió con lo que mejor sabe hacer: transiciones rápidas y una fe que parece no tener límites.\\n\\nLocutor: El primer gol llegó en el minuto veintidós, con un disparo impecable de Bellingham desde fuera del área. La grada explotó. Sin embargo, la alegría duró poco: apenas siete minutos después, Haaland empató con un cabezazo imposible para el portero.\\n\\nReportera: En el segundo tiempo, el encuentro se convirtió en un auténtico ajedrez táctico. Los entrenadores movían las piezas con precisión quirúrgica, sabiendo que un error podía costarles el partido.\\n\\nLocutor: Y cuando todo parecía encaminado a un empate, apareció Vinícius. En el minuto ochenta y nueve, controló el balón con una elegancia casi insultante y, con un toque sutil, lo envió al fondo de la red. El estadio estalló. Miles de voces coreaban su nombre mientras los jugadores se abrazaban.\\n\\nReportera: Fue una victoria que no solo vale tres puntos, sino también un golpe anímico que puede definir la temporada. En Madrid ya se habla de \\"la noche de Vinícius\\", y muchos la comparan con las grandes gestas europeas del club.\\n\\nLocutor: Una vez más, el Bernabéu demostró que el fútbol no se explica solo con estadísticas. Hay algo más: ese impulso invisible que hace creer a los que nunca dejan de luchar.","vocab":[{"term":"gesta","meaning":"heroic deed / memorable achievement"},{"term":"transición","meaning":"transition / quick change from defense to attack"},{"term":"ajedrez táctico","meaning":"tactical chess (metaphor for strategic play)"},{"term":"anímico","meaning":"emotional / related to mood"},{"term":"disparo impecable","meaning":"perfect shot / flawless strike"},{"term":"grada","meaning":"stands / bleachers (in a stadium)"},{"term":"memoria colectiva","meaning":"collective memory"},{"term":"polémica","meaning":"controversy"},{"term":"precisión quirúrgica","meaning":"surgical precision"},{"term":"corear","meaning":"to chant / to cheer in unison"}],"quiz":[{"id":"q1","type":"single","question":"¿Qué característica destaca del juego del Manchester City en el partido?","options":["Su defensa cerrada y juego físico","Su dominio de la posesión y pases cortos","Su estilo de contraataque rápido"],"answerIndex":1,"explanation":"El City dominó la posesión, fiel a su estilo de pases cortos y ritmo constante."},{"id":"q2","type":"single","question":"¿Cómo reaccionó el Real Madrid al dominio del City?","options":["Con un estilo defensivo muy conservador","Con transiciones rápidas y confianza en sí mismo","Con una estrategia completamente improvisada"],"answerIndex":1,"explanation":"El Madrid respondió con transiciones rápidas y una fe que parece no tener límites."},{"id":"q3","type":"single","question":"¿Qué simboliza el gol de Vinícius en el minuto ochenta y nueve?","options":["Un golpe de suerte sin importancia","El momento decisivo que cambió el resultado y el ánimo del equipo","Un error del portero rival"],"answerIndex":1,"explanation":"Fue una victoria que vale tres puntos y también un golpe anímico que puede definir la temporada."},{"id":"q4","type":"single","question":"¿Qué significa la frase \'un auténtico ajedrez táctico\'?","options":["Que los jugadores discutieron en el campo","Que el partido fue aburrido y lento","Que ambos entrenadores tomaban decisiones muy estratégicas"],"answerIndex":2,"explanation":"Los entrenadores movían las piezas con precisión quirúrgica, sabiendo que un error podía costarles el partido."},{"id":"q5","type":"single","question":"¿Qué idea resume el cierre del reportaje?","options":["El fútbol solo se entiende con estadísticas y análisis","La suerte es lo único que decide los partidos","En el fútbol hay una energía emocional que trasciende los números"],"answerIndex":2,"explanation":"El Bernabéu demostró que el fútbol no se explica solo con estadísticas. Hay algo más: ese impulso invisible que hace creer."}]},{"id":"c2-01","level":"c2","title":"El valor de cambiar de opinión","duration":"2m 15s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/c2/C2_01_audio.mp3","transcript":"Cambiar de opinión es, para muchos, una señal de debilidad. \\"Si cambias de idea\\", dicen algunos, \\"significa que no estabas seguro desde el principio\\". Sin embargo, cada vez más estudios muestran que la capacidad de cambiar de opinión no solo es una virtud intelectual, sino también una forma de inteligencia emocional.\\n\\nPensemos en lo que implica mantener una creencia. Cada idea que tenemos está sostenida por experiencias, emociones y contextos específicos. Pero cuando esos contextos cambian, ¿no debería cambiar también nuestra opinión? Si alguien se aferra a una idea solo para no parecer inconstante, en realidad está sacrificando su crecimiento personal por orgullo.\\n\\nCambiar de opinión requiere valentía: aceptar que podemos habernos equivocado, escuchar argumentos que desafían nuestras creencias, e incluso admitir que quien antes considerábamos \\"oponente\\" tenía algo de razón.\\n\\nNo se trata de cambiar por impulso ni por moda. Se trata de hacerlo porque hemos comprendido algo nuevo, porque la evidencia o la experiencia nos mostraron un ángulo diferente.\\n\\nEn última instancia, cambiar de opinión no significa perder identidad, sino actualizarla. Tal vez la mente más sabia no sea la que nunca duda, sino la que se atreve a hacerlo con honestidad.","vocab":[{"term":"En última instancia","meaning":"Ultimately"},{"term":"virtud","meaning":"virtue"},{"term":"inteligencia emocional","meaning":"emotional intelligence"},{"term":"aferrarse","meaning":"to cling / to hold on"},{"term":"inconstante","meaning":"inconsistent / changeable"},{"term":"desafiar","meaning":"to challenge"},{"term":"evidencia","meaning":"evidence"},{"term":"identidad","meaning":"identity"},{"term":"actualizar","meaning":"to update / refresh"},{"term":"atreverse","meaning":"to dare"}],"quiz":[{"id":"q1","type":"single","question":"¿Cuál es la idea principal del discurso?","options":["Que cambiar de opinión demuestra falta de carácter","Que cambiar de opinión puede ser un signo de crecimiento personal","Que debemos evitar cambiar para no confundir a los demás"],"answerIndex":1,"explanation":"El texto argumenta que cambiar de opinión es una virtud intelectual y forma de inteligencia emocional."},{"id":"q2","type":"single","question":"Según el texto, ¿por qué algunas personas evitan cambiar de opinión?","options":["Porque no saben escuchar","Porque temen parecer débiles o inconstantes","Porque confían demasiado en los demás"],"answerIndex":1,"explanation":"El texto menciona que algunas personas se aferran a ideas para no parecer inconstantes."},{"id":"q3","type":"single","question":"¿Qué papel juega la \\"evidencia\\" en el proceso de cambio?","options":["No influye en las creencias personales","Es una excusa para justificar indecisión","Es un elemento que puede modificar nuestra perspectiva"],"answerIndex":2,"explanation":"El texto señala que la evidencia o la experiencia nos muestran ángulos diferentes que justifican el cambio."},{"id":"q4","type":"single","question":"Cuando el autor dice \\"actualizar nuestra identidad\\", ¿qué quiere decir?","options":["Que la identidad evoluciona con lo que aprendemos","Que cambiar es traicionar lo que somos","Que debemos olvidar nuestras ideas anteriores"],"answerIndex":0,"explanation":"El autor concluye que cambiar de opinión no significa perder identidad, sino actualizarla con lo aprendido."},{"id":"q5","type":"single","question":"¿Qué tono general transmite la charla?","options":["Sarcástico y crítico","Distante y académico","Reflexivo y conciliador"],"answerIndex":2,"explanation":"El texto mantiene un tono reflexivo que invita a reconsiderar la percepción negativa del cambio de opinión."}],"snippet":"Cambiar de opinión es, para muchos, una señal de debilidad. \\"Si cambias de idea\\", dicen algunos, \\"significa que no estabas seguro desde el principio\\"."},{"id":"c2-02","level":"c2","title":"El universo como espejo del tiempo","duration":"2m 20s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/c2/C2_02_audio.mp3","transcript":"Cuando miramos el cielo nocturno, no observamos el presente, sino una secuencia infinita de pasados. Cada punto luminoso que vemos es una historia que ocurrió hace miles o millones de años. La luz de una estrella tarda tanto en llegar hasta nosotros que, mientras la contemplamos, quizá ya no exista.\\n\\nEsa paradoja —ver lo que fue y no lo que es— convierte al universo en un espejo del tiempo. Un espejo imperfecto, que refleja fragmentos dispersos de un relato cósmico que aún intentamos descifrar.\\n\\nDurante siglos, el ser humano creyó que el cosmos giraba a su alrededor. Hoy sabemos que somos apenas una nota en una sinfonía inmensa, una vibración minúscula dentro de un tejido en expansión constante. Sin embargo, cuanto más comprendemos del universo, más preguntas aparecen: ¿qué había antes del tiempo?, ¿qué hay más allá de los límites de nuestra percepción?, ¿y qué significa \\"antes\\" o \\"más allá\\" cuando hablamos del espacio y la luz?\\n\\nLa astronomía moderna busca respuestas con telescopios, fórmulas y partículas. Pero hay algo que los instrumentos no pueden medir: el asombro. Esa sensación de pequeñez y pertenencia al mismo tiempo.\\n\\nQuizás entender el universo no sea cuestión de dominarlo, sino de aprender a escucharlo. Porque cada estrella, cada silencio entre galaxias, nos recuerda lo mismo: que mirar el cielo es, en el fondo, mirar hacia adentro.","vocab":[{"term":"paradoja","meaning":"situación aparentemente contradictoria que encierra una verdad"},{"term":"fragmentos dispersos","meaning":"partes separadas o inconexas de un todo"},{"term":"relato cósmico","meaning":"metáfora del universo como una historia en curso"},{"term":"sinfonía inmensa","meaning":"metáfora que expresa armonía universal"},{"term":"tejido en expansión","meaning":"imagen poética del espacio-tiempo en crecimiento"},{"term":"percepción","meaning":"capacidad de captar o interpretar estímulos"},{"term":"partículas","meaning":"unidades elementales de la materia"},{"term":"asombro","meaning":"mezcla de admiración y desconcierto ante lo desconocido"},{"term":"pequeñez","meaning":"sensación de insignificancia frente a la magnitud del universo"},{"term":"pertenencia","meaning":"sentimiento de formar parte de un todo mayor"}],"quiz":[{"id":"q1","type":"single","question":"¿Por qué el autor describe el universo como un \\"espejo del tiempo\\"?","options":["Porque refleja la luz del presente","Porque nos permite ver el pasado a través de la luz que llega tarde","Porque distorsiona la realidad física de las estrellas"],"answerIndex":1,"explanation":"El texto explica que vemos el pasado porque la luz de las estrellas tarda en llegar."},{"id":"q2","type":"single","question":"¿Qué efecto tiene la paradoja de ver estrellas que ya no existen?","options":["Confirma que el universo es caótico e impredecible","Refuerza la idea de que el tiempo no existe","Genera una reflexión sobre la ilusión de la percepción humana"],"answerIndex":2,"explanation":"La paradoja invita a reflexionar sobre cómo percibimos la realidad y el tiempo."},{"id":"q3","type":"single","question":"¿Qué crítica implícita hace el texto al conocimiento científico?","options":["Que intenta imponer certezas donde solo hay misterio","Que excluye la participación humana","Que no tiene rigor suficiente"],"answerIndex":0,"explanation":"El texto sugiere que hay algo más allá de lo medible: el asombro y el misterio."},{"id":"q4","type":"single","question":"¿Qué significado simbólico tiene la frase \\"mirar el cielo es mirar hacia adentro\\"?","options":["Que las estrellas influyen en nuestro comportamiento","Que la observación del universo nos ayuda a comprender nuestra propia existencia","Que la astronomía moderna está centrada en la psicología"],"answerIndex":1,"explanation":"La frase sugiere que contemplar el cosmos es también una forma de autoconocimiento."},{"id":"q5","type":"single","question":"¿Qué tono domina el texto?","options":["Satírico y provocador","Didáctico y técnico","Contemplativo y filosófico"],"answerIndex":2,"explanation":"El texto combina reflexiones filosóficas con un tono contemplativo sobre el cosmos."},{"id":"q6","type":"single","question":"¿Cuál es la idea principal sobre el conocimiento humano frente al cosmos?","options":["Que la comprensión total del universo es imposible","Que la ciencia y la poesía son opuestas","Que la búsqueda del conocimiento es inseparable del asombro"],"answerIndex":2,"explanation":"El texto enfatiza que el asombro es parte fundamental de la comprensión del universo."},{"id":"q7","type":"single","question":"¿Qué estructura retórica se repite en el texto?","options":["Citas literarias de autores clásicos","Ejemplos científicos rigurosos","Preguntas retóricas que invitan a la reflexión"],"answerIndex":2,"explanation":"El texto incluye varias preguntas retóricas sobre el tiempo, el espacio y la percepción."},{"id":"q8","type":"single","question":"¿Qué podría simbolizar el silencio entre galaxias al final?","options":["La ausencia de vida","La distancia entre planetas","El espacio para la introspección humana"],"answerIndex":2,"explanation":"El silencio representa un espacio de reflexión y conexión interior con el universo."}],"snippet":"Cuando miramos el cielo nocturno, no observamos el presente, sino una secuencia infinita de pasados. Cada punto luminoso que vemos es una historia ..."},{"id":"c2-03","level":"c2","title":"Conversación en el bar: lo que no se dice","duration":"2m 30s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/c2/C2_03_audio.mp3","transcript":"Dos hombres, Andrés y Julián, amigos desde la universidad, se encuentran en un bar después de años sin verse. Ambos han tomado caminos distintos —uno trabaja en política, el otro en periodismo— y la charla mezcla nostalgia, escepticismo y crítica social. El ruido del bar y la música de fondo crean una atmósfera íntima, pero cargada de subtexto.\\n\\nAndrés: No puedo creer que hayan pasado diez años. El mismo bar, las mismas luces… solo nosotros cambiamos.\\n\\nJulián: ¿Cambiar? No estoy tan seguro. Seguimos hablando de política, solo que ahora con más cinismo.\\n\\nAndrés: Tú lo llamas cinismo, yo lo llamo experiencia.\\n\\nJulián: O resignación.\\n\\n[Ríen brevemente.]\\n\\nAndrés: ¿Y sigues escribiendo?\\n\\nJulián: Claro. Aunque ya nadie lee crónicas largas. Todo tiene que caber en doscientos ochenta caracteres.\\n\\nAndrés: Bienvenido a la era del pensamiento instantáneo.\\n\\nJulián: ¿Te das cuenta? Vivimos informados, pero no entendemos nada.\\n\\nAndrés: Y lo peor es que nos acostumbramos. El ruido constante se volvió normal.\\n\\nJulián: (con tono irónico) Lo llamamos libertad de expresión, pero en realidad es saturación de expresión.\\n\\nAndrés: Exacto. Hoy todo el mundo opina, pero casi nadie escucha.\\n\\nJulián: ¿Y tú? ¿Aún crees que desde la política se puede cambiar algo?\\n\\nAndrés: A veces. Pero cada decisión tiene un costo moral. El poder no te cambia de golpe; te desgasta, lentamente.\\n\\nJulián: (pausa) Quizás por eso dejé de cubrir campañas.\\n\\nAndrés: Tal vez por eso sigo en ellas.\\n\\n[Silencio breve. Se oye el tintineo de vasos.]\\n\\nJulián: Brindemos, entonces.\\n\\nAndrés: ¿Por qué?\\n\\nJulián: Por lo que todavía no sabemos cómo decir.\\n\\n[Se escucha el sonido de un brindis. Música sube y se desvanece lentamente.]","vocab":[{"term":"cinismo","meaning":"actitud escéptica o desengañada ante la moral o la política"},{"term":"resignación","meaning":"aceptación pasiva de algo inevitable"},{"term":"crónica","meaning":"artículo narrativo que combina hechos y reflexión"},{"term":"pensamiento instantáneo","meaning":"idea expresada sin reflexión profunda (concepto moderno)"},{"term":"saturación de expresión","meaning":"exceso de comunicación que impide la comprensión real"},{"term":"costo moral","meaning":"dilema ético asociado a decisiones profesionales o políticas"},{"term":"desgastar","meaning":"debilitar gradualmente, tanto física como emocionalmente"},{"term":"brindis","meaning":"acto simbólico de celebrar o cerrar un momento significativo"},{"term":"subtexto","meaning":"significado implícito o emocional detrás de las palabras"},{"term":"ironía","meaning":"decir lo contrario de lo que se piensa, con intención crítica o humorística"}],"quiz":[{"id":"q1","type":"single","question":"¿Qué simboliza el bar en esta conversación?","options":["Un espacio de distracción pasajera","Un lugar donde el pasado y el presente se encuentran","Una metáfora del desencanto político"],"answerIndex":1,"explanation":"El bar es el lugar donde los amigos se reencuentran después de años, conectando su pasado universitario con su presente."},{"id":"q2","type":"single","question":"¿Qué significa que \\"el poder no te cambia de golpe; te desgasta\\"?","options":["Que el poder fortalece con el tiempo","Que los políticos envejecen más rápido","Que la corrupción ocurre de forma lenta y gradual"],"answerIndex":2,"explanation":"Andrés sugiere que el poder corrompe o deteriora moralmente de manera gradual, no instantánea."},{"id":"q3","type":"single","question":"¿Qué crítica implícita hace Julián cuando dice \\"vivimos informados, pero no entendemos nada\\"?","options":["A la superficialidad del consumo mediático actual","A la falta de educación formal","A la censura gubernamental"],"answerIndex":0,"explanation":"Julián critica el exceso de información sin comprensión profunda en la era digital."},{"id":"q4","type":"single","question":"¿Qué intención tiene la frase \\"Por lo que todavía no sabemos cómo decir\\"?","options":["Evadir el silencio incómodo","Terminar la conversación con humor","Reconocer lo inefable y lo emocional detrás del diálogo"],"answerIndex":2,"explanation":"El brindis reconoce que hay emociones y pensamientos complejos que no pueden expresarse fácilmente con palabras."},{"id":"q5","type":"single","question":"¿Qué tono domina la conversación?","options":["Enfadado y pesimista","Reflexivo y melancólico con ironía sutil","Alegórico y distante"],"answerIndex":1,"explanation":"La conversación mezcla reflexiones sobre cambios personales y sociales con toques de ironía y nostalgia."}],"snippet":"Dos hombres, Andrés y Julián, amigos desde la universidad, se encuentran en un bar después de años sin verse. Ambos han tomado caminos distintos —u..."},{"id":"c2-04","level":"c2","title":"El poder de las narrativas políticas","duration":"2m 10s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/c2/C2_04_audio.mp3","transcript":"A lo largo de la historia, los líderes han comprendido algo que a veces los ciudadanos olvidan: el poder no reside únicamente en las armas o en la economía, sino en las historias que logran que una sociedad crea en algo. Las narrativas políticas son el combustible invisible de las civilizaciones. Una nación se mantiene unida no solo por leyes, sino por relatos compartidos: la idea de justicia, la promesa del progreso o la ilusión de pertenecer a un destino común.\\n\\nEl lenguaje político, sin embargo, no solo describe la realidad: la fabrica. Una palabra puede legitimar una guerra o justificar una reforma; puede convertir un error en \\"sacrificio\\" o una mentira en \\"versión\\". Por eso los discursos no son inocentes: cada término, cada pausa, cada apelación emocional está cuidadosamente calibrada para producir efecto.\\n\\nEn la era digital, las narrativas se multiplican y fragmentan. Ya no hay un solo relato dominante, sino miles de microhistorias que compiten por atención. El algoritmo se ha convertido en el nuevo narrador: selecciona, omite, repite. Y en ese proceso, transforma la percepción colectiva del mundo.\\n\\nEl reto contemporáneo no es decidir en qué historia creer, sino aprender a reconocer cuándo una historia nos está creyendo a nosotros. Porque toda narrativa política —por más seductora o noble que parezca— encierra un propósito: mantener el poder de definir qué es real y qué no.","vocab":[{"term":"narrativa política","meaning":"conjunto de relatos y símbolos que construyen la identidad ideológica de una sociedad"},{"term":"legitimar","meaning":"dar apariencia de validez o justicia a una acción o idea"},{"term":"calibrar","meaning":"ajustar con precisión un mensaje o estrategia"},{"term":"microhistorias","meaning":"relatos breves o fragmentados que influyen en la opinión pública"},{"term":"relato dominante","meaning":"discurso oficial o hegemónico que define una versión colectiva de la realidad"},{"term":"algoritmo","meaning":"sistema digital que selecciona información y condiciona la visibilidad de contenidos"},{"term":"percepción colectiva","meaning":"interpretación compartida de la realidad por una comunidad"},{"term":"seductor/a","meaning":"atractivo, persuasivo o convincente"},{"term":"hegemonía","meaning":"dominio cultural o ideológico de un grupo sobre otro"},{"term":"legitimidad simbólica","meaning":"autoridad basada en la creencia, no en la fuerza"}],"quiz":[{"id":"q1","type":"single","question":"Según el texto, ¿dónde reside realmente el poder político?","options":["En las armas y la economía exclusivamente","En las historias que logran que una sociedad crea en algo","En las leyes y el sistema judicial"],"answerIndex":1,"explanation":"El texto afirma que el poder reside en las historias, no únicamente en armas o economía."},{"id":"q2","type":"single","question":"¿Qué significa que \\"el lenguaje político fabrica la realidad\\"?","options":["Que las palabras simplemente describen los hechos","Que el lenguaje puede transformar errores en sacrificios y mentiras en versiones","Que los políticos siempre mienten"],"answerIndex":1,"explanation":"El texto explica que las palabras no solo describen, sino que construyen y transforman la percepción de la realidad."},{"id":"q3","type":"single","question":"¿Qué papel juega el algoritmo en la era digital según el texto?","options":["Simplemente organiza contenido de manera neutral","Elimina las narrativas políticas tradicionales","Se ha convertido en el nuevo narrador que selecciona y omite información"],"answerIndex":2,"explanation":"El texto describe al algoritmo como el nuevo narrador que transforma la percepción colectiva."},{"id":"q4","type":"single","question":"¿Cuál es el \\"reto contemporáneo\\" mencionado al final del texto?","options":["Decidir en qué historia creer","Aprender a reconocer cuándo una historia nos está creyendo a nosotros","Crear narrativas más convincentes"],"answerIndex":1,"explanation":"El texto plantea que el desafío no es elegir una historia, sino reconocer cuándo somos controlados por ella."},{"id":"q5","type":"single","question":"¿Qué crítica implícita hace el texto sobre las narrativas políticas?","options":["Que son innecesarias en democracia","Que solo existen en regímenes autoritarios","Que siempre buscan mantener el poder de definir qué es real"],"answerIndex":2,"explanation":"El texto concluye que toda narrativa política encierra el propósito de mantener el poder de definir la realidad."}],"snippet":"A lo largo de la historia, los líderes han comprendido algo que a veces los ciudadanos olvidan: el poder no reside únicamente en las armas o en la ..."},{"id":"c2-05","level":"c2","title":"Biografía de Albert Einstein","duration":"2m 20s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/c2/C2_05_audio.mp3","snippet":"Albert Einstein nació el 14 de marzo de 1879 en la ciudad de Ulm, en Alemania. Provenía de una familia judía secular.","transcript":"Albert Einstein nació el 14 de marzo de 1879 en la ciudad de Ulm, en Alemania.\\n\\nProvenía de una familia judía secular; su padre, Hermann Einstein, era empresario, y su madre, Pauline Koch, una pianista aficionada. Desde pequeño mostró una profunda curiosidad por los misterios del mundo físico. A los cinco años, una simple brújula despertó en él la fascinación por las fuerzas invisibles que gobiernan la naturaleza.\\n\\nEinstein estudió en Múnich, pero pronto abandonó el sistema educativo alemán por considerarlo demasiado estricto. Continuó su formación en Suiza, donde más tarde obtuvo la ciudadanía y el título de profesor de física.\\n\\nEl año 1905 es conocido como su \\"año milagroso\\". En ese periodo publicó varios artículos revolucionarios en la revista Annalen der Physik, entre ellos el que presentó la teoría especial de la relatividad y la célebre ecuación E=mc², que demuestra la equivalencia entre masa y energía.\\n\\nUna década después, en 1915, desarrolló la teoría general de la relatividad, que transformó para siempre la manera en que la humanidad entiende el espacio, el tiempo y la gravedad.\\n\\nEn 1921 recibió el Premio Nobel de Física, no por la relatividad, sino por sus aportes al estudio del efecto fotoeléctrico, un descubrimiento clave para el desarrollo de la física cuántica.\\n\\nEn 1933, ante el ascenso del nazismo en Alemania, Einstein se exilió en Estados Unidos, donde aceptó una plaza en el Institute for Advanced Study, en Princeton, Nueva Jersey. Desde allí continuó su trabajo científico y su activismo por la paz y los derechos humanos.\\n\\nAlbert Einstein falleció el 18 de abril de 1955 en Princeton. Su legado transformó la ciencia moderna y sentó las bases de campos como la cosmología, la energía nuclear y la tecnología satelital. Más allá de sus teorías, dejó una profunda reflexión sobre el valor de la imaginación, la curiosidad y la responsabilidad ética del conocimiento.","vocab":[{"term":"fascinación","meaning":"intense attraction / deep interest"},{"term":"fuerzas invisibles","meaning":"invisible forces (physical phenomena not directly visible)"},{"term":"revolucionario","meaning":"revolutionary / that produces radical change"},{"term":"equivalencia","meaning":"equivalence / equality in value or meaning"},{"term":"efecto fotoeléctrico","meaning":"photoelectric effect"},{"term":"exilio","meaning":"exile"},{"term":"cosmología","meaning":"cosmology (science of the universe)"},{"term":"legado","meaning":"legacy"},{"term":"año milagroso","meaning":"miracle year"},{"term":"responsabilidad ética","meaning":"ethical responsibility"}],"quiz":[{"id":"q1","type":"single","question":"Según el texto, ¿qué aspecto de la infancia de Einstein anticipaba su manera futura de pensar?","options":["Su fascinación por lo invisible y su curiosidad por las leyes naturales","Su rechazo a la música y las artes, por considerarlas poco útiles","Su gusto por las matemáticas aplicadas a la ingeniería"],"answerIndex":0,"explanation":"Desde pequeño mostró curiosidad por los misterios del mundo físico, como las fuerzas invisibles que observó en una brújula."},{"id":"q2","type":"single","question":"La decisión de Einstein de abandonar el sistema educativo alemán puede interpretarse como…","options":["Una muestra de rebeldía adolescente sin consecuencias posteriores","Un indicio temprano de su pensamiento independiente y crítico","Una estrategia para evitar el servicio militar obligatorio"],"answerIndex":1,"explanation":"Einstein abandonó el sistema por considerarlo demasiado estricto, lo que refleja su pensamiento independiente."},{"id":"q3","type":"single","question":"¿Qué sugiere el texto sobre el impacto de la teoría de la relatividad en la ciencia moderna?","options":["Que fue una idea innovadora pero rápidamente superada","Que cambió radicalmente la comprensión del tiempo, el espacio y la gravedad","Que generó controversia por falta de evidencia experimental"],"answerIndex":1,"explanation":"La teoría transformó para siempre la manera en que la humanidad entiende el espacio, el tiempo y la gravedad."},{"id":"q4","type":"single","question":"¿Por qué se menciona que Einstein recibió el Nobel por el efecto fotoeléctrico y no por la relatividad?","options":["Para destacar que incluso sus teorías \'secundarias\' eran revolucionarias","Porque el jurado del Nobel no entendía la relatividad","Para señalar que su obra fue reconocida más por la política que por la ciencia"],"answerIndex":0,"explanation":"El texto resalta que su trabajo sobre el efecto fotoeléctrico fue un descubrimiento clave para la física cuántica."},{"id":"q5","type":"single","question":"En el texto, el traslado de Einstein a Estados Unidos representa…","options":["Una derrota personal frente a las dificultades políticas de Europa","El inicio de su retiro definitivo de la investigación","Una transición desde el científico teórico hacia el pensador humanista"],"answerIndex":2,"explanation":"Desde Estados Unidos continuó su trabajo científico y su activismo por la paz y los derechos humanos."}]},{"id":"c2-06","level":"c2","title":"Desigualdad social y movilidad económica en el siglo XXI","duration":"2m 30s","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/c2/C2_06_audio.mp3","snippet":"La desigualdad social se manifiesta como la acumulación de diferencias profundas en el acceso a recursos, oportunidades y poder entre individuos y grupos dentro de una sociedad.","transcript":"La desigualdad social se manifiesta como la acumulación de diferencias profundas en el acceso a recursos, oportunidades y poder entre individuos y grupos dentro de una sociedad. En el siglo XXI, esta forma de desigualdad no solo persiste, sino que adopta nuevos rostros: brechas en ingresos, en riqueza heredada, en la calidad de educación, en la atención sanitaria, en la conectividad digital y en la movilidad intergeneracional.\\n\\nLa movilidad económica —o movilidad social ascendente— se refiere al grado en que los miembros de una sociedad pueden cambiar su posición socioeconómica respecto de la de sus padres o de su situación de origen.\\n\\nSin embargo, cuando la desigualdad es alta, la llamada \\"curva de la gran Gatsby\\" (la relación entre nivel de desigualdad y baja movilidad) muestra que la capacidad de ascender se reduce significativamente.\\n\\nEn muchas economías modernas, se observa que aunque haya crecimiento económico agregado, la distribución de sus frutos no es equitativa. Los ingresos derivados del capital crecen más rápido que los ingresos del trabajo, lo que intensifica la concentración de riqueza en un reducido número de personas.\\n\\nPor lo tanto, aunque una persona use todos sus recursos y talentos, su posición de origen—su familia, entorno, raza, género o región—puede seguir siendo un factor determinante de su futuro económico.\\n\\nLa consecuencia de esta dinámica es doble: por un lado, se perpetúan las desigualdades intergeneracionales; por otro, la movilidad social real se reduce, lo que afecta la cohesión social, la justicia y el sentido de que \\"todos tienen oportunidad\\". Por ejemplo, en la práctica, muchas personas que nacen en entornos de menores recursos encuentran barreras estructurales para mejorar su situación económica, aunque se eduquen y trabajen diligentemente.\\n\\nPara abordar esta problemática, es crucial diseñar políticas integradas que incluyan la redistribución efectiva de recursos, inversión sustancial en educación de calidad, igualdad de oportunidades desde la infancia, y mecanismos que permitan que el acceso al capital —no solo al trabajo— no esté reservado a unos pocos. Asimismo, resulta indispensable medir y monitorear tanto la desigualdad como la movilidad con indicadores sólidos como el coeficiente de Gini, el índice de Palma o la elasticidad intergeneracional del ingreso.\\n\\nEn resumen, en el siglo XXI la desigualdad social y la movilidad económica están íntimamente ligadas: una elevada desigualdad suele traducirse en menor movilidad. Para que una sociedad sea verdaderamente justa y dinámica, no basta con crecimiento económico: debe acompañarse de igualdad de condiciones y posibilidad real de ascenso para todos.\\n\\nMuchas gracias por escuchar.","vocab":[{"term":"movilidad intergeneracional","meaning":"ability to improve or worsen one\'s socioeconomic position compared to parents"},{"term":"curva de la gran Gatsby","meaning":"relationship showing how societies with greater inequality have lower social mobility"},{"term":"concentración de riqueza","meaning":"accumulation of large economic resources in a small number of individuals"},{"term":"brechas estructurales","meaning":"deep and persistent differences in opportunities or social conditions"},{"term":"cohesión social","meaning":"degree of unity, trust and sense of belonging within a society"},{"term":"redistribución de recursos","meaning":"policies aimed at balancing economic differences between social groups"},{"term":"elasticidad intergeneracional del ingreso","meaning":"measure indicating how much parents\' economic level influences their children\'s"},{"term":"equidad","meaning":"fairness / equity"},{"term":"coeficiente de Gini","meaning":"Gini coefficient (inequality measure)"},{"term":"perpetuar","meaning":"to perpetuate"}],"quiz":[{"id":"q1","type":"single","question":"¿Cuál es la relación entre desigualdad y movilidad según la llamada \'curva de la gran Gatsby\'?","options":["A mayor desigualdad, mayor posibilidad de movilidad social","A mayor desigualdad, menor movilidad social","No existe relación entre ambas variables"],"answerIndex":1,"explanation":"La curva de la gran Gatsby muestra que cuando la desigualdad es alta, la capacidad de ascender se reduce significativamente."},{"id":"q2","type":"single","question":"El texto sugiere que la desigualdad contemporánea es más compleja que la del pasado porque…","options":["Ya no depende de la educación ni de la riqueza heredada","Se manifiesta en múltiples dimensiones, no solo en los ingresos","Afecta solo a los países en desarrollo"],"answerIndex":1,"explanation":"El texto menciona que la desigualdad adopta nuevos rostros: brechas en ingresos, riqueza heredada, educación, atención sanitaria, conectividad digital y movilidad intergeneracional."},{"id":"q3","type":"single","question":"Según el texto, ¿qué efecto tiene la concentración de riqueza sobre la movilidad social?","options":["Fomenta la competencia económica y el mérito individual","Incentiva el crecimiento económico inclusivo","Reduce las oportunidades de ascenso para los sectores más desfavorecidos"],"answerIndex":2,"explanation":"El texto explica que las personas que nacen en entornos de menores recursos encuentran barreras estructurales para mejorar su situación económica."},{"id":"q4","type":"single","question":"Cuando el texto afirma que \'el acceso al capital no debe estar reservado a unos pocos\', se está defendiendo…","options":["Una política de privatización total de los recursos financieros","La ampliación del acceso a inversiones y créditos como vía de equidad","La sustitución del trabajo por el capital en la economía"],"answerIndex":1,"explanation":"El texto propone mecanismos que permitan que el acceso al capital no esté reservado a unos pocos como parte de políticas integradas para reducir la desigualdad."},{"id":"q5","type":"single","question":"¿Qué enfoque global propone el texto para reducir la desigualdad y mejorar la movilidad?","options":["Aumentar el PIB y reducir los impuestos a las grandes empresas","Reformar únicamente el sistema educativo","Implementar políticas integrales que combinen redistribución, educación y acceso al capital"],"answerIndex":2,"explanation":"El texto propone políticas integradas que incluyan redistribución de recursos, inversión en educación de calidad, igualdad de oportunidades y acceso al capital."}]},{"id":"b2-2-01","level":"b2-2","title":"Reservando un hotel","duration":"2:30","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/b2/B2_07_audio.mp3","snippet":"Buenas tardes, Hotel Mirador, ¿en qué puedo ayudarle? Quisiera saber si tienen habitaciones disponibles para este fin de semana.","transcript":"Reservando un hotel\\n\\nLlamando para reservar\\n\\nRecepcionista y Cliente\\n\\n—Buenas tardes, Hotel Mirador, ¿en qué puedo ayudarle?\\n\\n—Hola, buenas tardes. Quisiera saber si tienen habitaciones disponibles para este fin de semana.\\n\\n—Claro, permítame un momento… Sí, tenemos habitaciones estándar y también una suite. ¿Para cuántas personas sería?\\n\\n—Para dos personas, por favor.\\n\\n—Perfecto. La habitación estándar tiene cama king, desayuno incluido y cancelación gratuita. La suite es más amplia y tiene vista al mar. ¿Cuál prefiere?\\n\\n—Creo que la estándar está bien. ¿Cuál sería el precio por noche?\\n\\n—Son 95 dólares por noche, impuestos incluidos.\\n\\n—Está bien. ¿Puedo hacer la reserva para viernes y sábado?\\n\\n—Claro que sí. ¿A nombre de quién la pongo?\\n\\n—A nombre de José Martínez.\\n\\n—Perfecto, señor Martinez. ¿Me puede proporcionar un número de teléfono y un correo electrónico?\\n\\n—Sí, claro: 555-982-443 y josejose@email.com.\\n\\n—Listo. Su reserva está confirmada. Le llegará un correo en unos minutos. Si necesita hacer cambios, solo llame aquí mismo.\\n\\n—Perfecto, muchas gracias por la ayuda.\\n\\n—Con gusto. ¡Lo esperamos el viernes!\\n\\nLlegando al hotel – Check-in\\n\\n—Buenas tardes, bienvenido al Hotel Mirador. ¿Tiene una reserva?\\n\\n—Sí, está a nombre de José Martínez.\\n\\n—Permítame verificar… Sí, aquí está: habitación estándar, dos noches. ¿Trae una identificación, por favor?\\n\\n—Sí, aquí tiene.\\n\\n—Gracias. ¿Desea pagar ahora o al momento del check-out?\\n\\n—Pago ahora, por favor.\\n\\n—Perfecto. ¿Tarjeta o efectivo?\\n\\n—Con tarjeta.\\n\\n—Muy bien... Aquí está su tarjeta… ¿Desea que le abra una cuenta para consumo en restaurante o minibar?\\n\\n—No, gracias. Prefiero pagar cada vez.\\n\\nAquí tiene sus llaves. Su habitación está en el piso cuatro, número 417. Los elevadores están a la derecha.\\n\\n—Perfecto. ¿A qué hora es el desayuno?\\n\\n—De 7 a 11 de la mañana en el restaurante del lobby.\\n\\n—Excelente. Muchas gracias.\\n\\n—Con gusto, señor Martínez. Que tenga una estancia muy agradable.","vocab":[{"term":"disponible","meaning":"available"},{"term":"estándar","meaning":"standard"},{"term":"suite","meaning":"suite"},{"term":"impuestos","meaning":"taxes"},{"term":"cancelación","meaning":"cancellation"},{"term":"consumo","meaning":"charges / consumption"},{"term":"estancia","meaning":"stay"}],"quiz":[{"id":"q1","type":"single","question":"¿Qué tipo de habitaciones tenía disponibles el hotel?","options":["Solo habitaciones estándar","Habitaciones estándar y una suite","Solo suites"],"answerIndex":1,"explanation":"El hotel tenía habitaciones estándar y también una suite disponibles."},{"id":"q2","type":"single","question":"¿Cuánto cuesta la habitación estándar por noche?","options":["75 dólares","95 dólares","120 dólares"],"answerIndex":1,"explanation":"La habitación estándar cuesta 95 dólares por noche, impuestos incluidos."},{"id":"q3","type":"single","question":"¿Qué información pidió la recepcionista para completar la reserva?","options":["Pasaporte y dirección","País de origen y fecha de nacimiento","Número de teléfono y correo electrónico"],"answerIndex":2,"explanation":"La recepcionista pidió un número de teléfono y un correo electrónico para completar la reserva."},{"id":"q4","type":"single","question":"Al llegar al hotel, ¿qué le pide la recepcionista a José?","options":["Un depósito en efectivo","Su tarjeta de crédito","Su identificación"],"answerIndex":2,"explanation":"Al llegar al hotel, la recepcionista le pide a José su identificación."},{"id":"q5","type":"single","question":"¿A qué hora es el desayuno?","options":["De 6 a 10 de la mañana","De 7 a 11 de la mañana","De 8 a 12 de la tarde"],"answerIndex":1,"explanation":"El desayuno es de 7 a 11 de la mañana en el restaurante del lobby."}]},{"id":"arg-01","level":"accent-argentine","title":"Comprando mate y bombilla","duration":"1:35","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/argentina/Argentino_01_audio.mp3","snippet":"Diálogo entre una vendedora y un cliente que quiere empezar a tomar mate. Aprenderás vocabulario argentino como \'che\', \'viste\', \'te copa\' y más.","transcript":"Vendedora: —¡Buen día, che! ¿En qué te puedo ayudar?\\n\\nCliente: —Hola, viste que estoy empezando con esto del mate y quería llevar una yerba y una bombilla, pero no tengo idea de las diferencias.\\n\\nVendedora: —Tranqui, te cuento. Tenés yerba suave, que es más livianita; intensa, que pega un poco más; con palo, que es la más tradicional; y sin palo, que es más fuerte y dura menos. ¿Te copa algo más suave para empezar?\\n\\nCliente: —Sí, creo que suave estaría bien. ¿Y el mate? Hay un montón…\\n\\nVendedora: —Claro. Podés elegir uno de calabaza, que es el clásico; uno de madera, que mantiene bien el sabor; o de acero inoxidable, que es fácil de limpiar. ¿Querés algo práctico?\\n\\nCliente: —Sí, práctico. Entonces me llevo el de acero. ¿Y la bombilla?\\n\\nVendedora: —Mirá, tenés esta de acero con filtro fino, que va bárbaro para yerba suave. Además dura años.\\n\\nCliente: —Perfecto. Y… ¿cómo preparo el mate para que salga rico?\\n\\nVendedora: —Clave: llená el mate hasta la mitad, agitá un poquito, dejá la yerba inclinada y poné agua tibia primero, no hirviendo, viste. Después sí, agregás agua más caliente y no le movés la bombilla.\\n\\nCliente: —Genial, che. Gracias por todas las recomendaciones.\\n\\nVendedora: —¡De nada! Cualquier cosa, chiflame. ¡Que lo disfrutes!","vocab":[{"term":"che","meaning":"Friendly attention-getter, like \'hey\'"},{"term":"viste","meaning":"Filler meaning \'you know?\'"},{"term":"tranqui","meaning":"Short for \'tranquilo\'; means \'relax, no worries\'"},{"term":"tenés","meaning":"Argentine form of \'tienes\' (\'you have\')"},{"term":"te copa","meaning":"Means \'do you like it?\' / \'are you into it?\'"},{"term":"mirá","meaning":"\'Look\'; used to introduce information"},{"term":"bárbaro","meaning":"Means \'great / awesome\'"},{"term":"chiflame","meaning":"Informal \'let me know\' (literally \'whistle at me\')"}],"quiz":[{"id":"q1","type":"single","question":"¿Qué tipo de yerba recomienda la vendedora para alguien que está empezando?","options":["Yerba intensa","Yerba suave","Yerba sin palo"],"answerIndex":1,"explanation":"La vendedora recomienda yerba suave para alguien que está empezando porque es más livianita."},{"id":"q2","type":"single","question":"¿Qué tipo de mate elige finalmente el cliente?","options":["Un mate de calabaza","Un mate de madera","Un mate de acero inoxidable"],"answerIndex":2,"explanation":"El cliente elige el mate de acero inoxidable porque es práctico y fácil de limpiar."},{"id":"q3","type":"single","question":"¿Qué característica destaca la vendedora de la bombilla que ofrece?","options":["Que es muy decorativa","Que tiene filtro fino y dura años","Que cambia el sabor de la yerba"],"answerIndex":1,"explanation":"La vendedora destaca que la bombilla tiene filtro fino y dura años."},{"id":"q4","type":"single","question":"¿Cuál es una recomendación clave para preparar bien el mate?","options":["Mover la bombilla todo el tiempo","Usar agua hirviendo desde el inicio","Colocar agua tibia primero y no mover la bombilla después"],"answerIndex":2,"explanation":"La vendedora recomienda poner agua tibia primero y no mover la bombilla después."},{"id":"q5","type":"single","question":"¿Qué expresión argentina usa la vendedora para cerrar la conversación?","options":["Nos vemos, pana","¡Chao, compa!","Cualquier cosa, chiflame"],"answerIndex":2,"explanation":"\'Chiflame\' es una expresión argentina informal que significa \'avísame\' o \'let me know\'."}]},{"id":"arg-02","level":"accent-argentine","title":"En una librería (literatura argentina)","duration":"1:26","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/argentina/Argentino_02_audio.mp3","snippet":"Una clienta busca libros de literatura argentina. La vendedora recomienda obras de Borges, Cortázar y Samanta Schweblin.","transcript":"—Hola, ¿qué tal? Estoy buscando algo de literatura argentina. ¿Tenés algo más de este autor? —muestra un libro de Borges.\\n\\n—Sí, claro, che. De Borges tenemos Ficciones y El Aleph. Si te gusta lo más fantástico, Ficciones es una joyita este libro.\\n\\n—¡Buenísimo! También quería algo de Cortázar. Siempre escucho hablar de Rayuela, viste.\\n\\n—Obvio. Rayuela es más largo y experimental, pero si querés empezar con algo corto, te recomiendo sus cuentos. Final del juego y Bestiario son lecturas rápidas pero potentes.\\n\\n—Perfecto. ¿Y algo más contemporáneo? Escuché el nombre Samanta Schweblin varias veces.\\n\\n—Sí, ella escribe terror psicológico muy sutil. Su novela Distancia de rescate sale mucho. También tenemos Pájaros en la boca, que es de cuentos y está bárbaro.\\n\\n—¿Y de precios cómo andan?\\n\\n—Mirá, los de Borges están alrededor de 5 mil pesos, los de Cortázar cerca de 4 mil, y Schweblin unos 6 mil porque es más reciente.\\n\\n—Bien. Me llevo Ficciones y Pájaros en la boca. A mí me encanta leer porque siento que desconecto del mundo por un rato, ¿viste?\\n\\n—Te entiendo. Para mí leer es viajar sin moverte. Bueno, che, te preparo los libros.\\n\\n—Genial, gracias por las recomendaciones.\\n\\n—¡De nada! Que los disfrutes.","vocab":[{"term":"experimental","meaning":"Experimental"},{"term":"potentes","meaning":"Powerful / impactful"},{"term":"terror psicológico","meaning":"Psychological horror"},{"term":"sutil","meaning":"Subtle"},{"term":"bárbaro","meaning":"Awesome / great (Argentine slang)"},{"term":"desconectar","meaning":"To disconnect / to switch off mentally"}],"quiz":[{"id":"q1","type":"single","question":"¿Qué dice la vendedora sobre el libro Ficciones de Borges?","options":["Que es muy difícil de entender","Que \'es una joyita este libro\'","Que casi nadie lo compra"],"answerIndex":1,"explanation":"La vendedora describe Ficciones como \'una joyita\', expresión argentina para algo excelente."},{"id":"q2","type":"single","question":"¿Qué recomienda la vendedora para empezar con Cortázar?","options":["Leer solo Rayuela","Empezar por sus novelas más largas","Empezar con sus cuentos, como Final del juego o Bestiario"],"answerIndex":2,"explanation":"La vendedora recomienda empezar con los cuentos de Cortázar porque son lecturas rápidas pero potentes."},{"id":"q3","type":"single","question":"¿Cómo describe la vendedora la escritura de Samanta Schweblin?","options":["Humor absurdo","Ensayo político","Terror psicológico muy sutil"],"answerIndex":2,"explanation":"La vendedora describe a Schweblin como autora de terror psicológico muy sutil."},{"id":"q4","type":"single","question":"¿Cuál es la razón que da el cliente para decir que le gusta leer?","options":["Porque aprende más sobre historia argentina","Porque mejora su vocabulario académico","Porque siente que desconecta del mundo por un rato"],"answerIndex":2,"explanation":"El cliente dice que le encanta leer porque siente que desconecta del mundo por un rato."},{"id":"q5","type":"single","question":"¿Qué comparación usa la vendedora para explicar lo que significa leer para ella?","options":["Leer es como ir al cine","Leer es como hacer deporte","Leer es como viajar sin moverte"],"answerIndex":2,"explanation":"La vendedora dice que para ella leer es como viajar sin moverte."}]},{"id":"arg-03","level":"accent-argentine","title":"Paseando por Palermo","duration":"0:45","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/argentina/Argentino_03_audio.mp3","snippet":"Lucía y Martín pasean por el barrio de Palermo en Buenos Aires, disfrutando del ambiente, los cafés y la arquitectura que mezcla lo moderno con lo antiguo.","transcript":"Lucía: —Che, está re lindo el día, ¿no? Este solcito acompaña un montón.\\n\\nMartín: —Sí, mal. Palermo así da ganas de caminar sin apuro. Vamos tranqui, total no tenemos nada que hacer.\\n\\nLucía: —Tal cual. Mirá ese café de la esquina, está lleno. Los domingos se arma lindo ambiente por acá.\\n\\nMartín: —Y sí, entre los cafés, el parque y la gente paseando, tiene onda. Fijate allá, hay una feria, capaz venden cosas artesanales.\\n\\nLucía: —Buenísimo. Me encanta cómo se mezcla lo moderno con lo antiguo en Buenos Aires. Esos edificios viejos tienen mucha historia.\\n\\nMartín: —Re sí. San Telmo y Recoleta también tienen esa arquitectura antigua que te hace viajar en el tiempo.\\n\\nLucía: —Totalmente. Bueno, caminemos un poco más y después nos sentamos a tomar un café, ¿te parece?\\n\\nMartín: —De una. Así disfrutamos el día como corresponde.","vocab":[{"term":"Che","meaning":"Hey / Oye / You know — Used to get someone\'s attention or start a conversation."},{"term":"Re lindo / re + adjetivo","meaning":"Really / very (nice, pretty, etc.) — Informal intensifier, very common in Argentina."},{"term":"Vamos tranqui","meaning":"Let\'s take it easy / Let\'s go slow — Doing something calmly, without rushing."},{"term":"Tiene onda","meaning":"It\'s cool / It has a nice vibe — Said about places, people, or situations."},{"term":"De una","meaning":"Sure / Absolutely / For sure — Strong, enthusiastic agreement."}],"quiz":[{"id":"q1","type":"single","question":"¿Por qué dicen que el día está \\"re lindo\\"?","options":["Porque va a llover más tarde","Porque hay sol y el clima acompaña","Porque hay pocos cafés abiertos"],"answerIndex":1,"explanation":"Lucía dice que el día está \'re lindo\' porque hay sol y el clima acompaña."},{"id":"q2","type":"single","question":"¿Qué les dan ganas de hacer en Palermo?","options":["Irse rápido a otro barrio","Quedarse en casa","Caminar sin apuro"],"answerIndex":2,"explanation":"Martín dice que Palermo así da ganas de caminar sin apuro."},{"id":"q3","type":"single","question":"¿Qué lugares menciona Martín como parte del ambiente del barrio?","options":["Solo edificios modernos","Cafés, el parque y la gente paseando","Museos y teatros"],"answerIndex":1,"explanation":"Martín menciona los cafés, el parque y la gente paseando como parte del ambiente."},{"id":"q4","type":"single","question":"¿Qué les gusta de la arquitectura de Buenos Aires?","options":["Que todos los edificios son nuevos","Que es igual en toda la ciudad","Que mezcla lo moderno con lo antiguo y tiene historia"],"answerIndex":2,"explanation":"A Lucía le encanta cómo se mezcla lo moderno con lo antiguo y que los edificios viejos tienen mucha historia."}]},{"id":"arg-04","level":"accent-argentine","title":"En una clase de tango","duration":"0:50","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/argentina/Argentino_04_audio.mp3","snippet":"Ana, la profesora de tango, ayuda a Sofía a mejorar su postura, ritmo y conexión con la música durante una clase.","transcript":"Ana: —Bueno, Sofi, arrancamos de nuevo desde el paso básico. Acordate de mantener la postura: espalda derecha, hombros relajados.\\n\\nSofía: —Dale, Ana. Siento que me apuro un poco cuando cambia el ritmo.\\n\\nAna: —Sí, se nota. No te apures. El tango no se corre, se camina. Escuchá bien la música y marcá más suave con los pies.\\n\\nSofía: —Ok, voy a tratar de aflojar. ¿Así está mejor?\\n\\nAna: —Mucho mejor. Ahora seguí mi guía, no pienses tanto el paso. Dejá que el cuerpo acompañe el ritmo.\\n\\nSofía: —Me cuesta no anticiparme, pero cuando me concentro en la música fluye más.\\n\\nAna: —Exacto. Mirá, en el giro bajá un poco más el peso y mantené el eje. Eso, ahí está.\\n\\nSofía: —¡Ah! Ahora lo sentí distinto. Es como más natural.\\n\\nAna: —Tal cual. Cuando conectás postura, ritmo y abrazo, el tango sale solo.","vocab":[{"term":"Arrancar (de nuevo)","meaning":"To start (again) — Used informally to mean beginning an activity, very common in classes or instructions."},{"term":"Postura","meaning":"Posture — Refers to the correct position of the body, especially important in dance."},{"term":"No te apures","meaning":"Don\'t rush / Take your time — A very common correction in Argentine Spanish."},{"term":"Seguí mi guía","meaning":"Follow my lead — Typical expression in tango, meaning to trust and follow the instructor\'s movements."},{"term":"Fluye","meaning":"It flows / It feels natural — Used when movements happen smoothly, without overthinking."}],"quiz":[{"id":"q1","type":"single","question":"¿Qué le pide la profesora a Sofía al inicio de la clase?","options":["Que cambie de pareja","Que empiece con pasos avanzados","Que vuelva al paso básico y cuide la postura"],"answerIndex":2,"explanation":"Ana le pide a Sofía que arranquen desde el paso básico y que mantenga la postura."},{"id":"q2","type":"single","question":"¿Cuál es el principal problema que tiene Sofía al bailar?","options":["No escucha la música","Se apura cuando cambia el ritmo","No recuerda los pasos"],"answerIndex":1,"explanation":"Sofía dice que siente que se apura un poco cuando cambia el ritmo."},{"id":"q3","type":"single","question":"¿Qué consejo le da la profesora para mejorar el baile?","options":["Pensar más cada movimiento","Bailar más rápido","Escuchar la música y marcar más suave"],"answerIndex":2,"explanation":"Ana le dice que escuche bien la música y marque más suave con los pies."},{"id":"q4","type":"single","question":"¿Qué ocurre cuando Sofía conecta postura, ritmo y guía?","options":["El baile se vuelve más difícil","El tango fluye de forma natural","Necesita más correcciones"],"answerIndex":1,"explanation":"Ana dice que cuando conectás postura, ritmo y abrazo, el tango sale solo."}]},{"id":"arg-05","level":"accent-argentine","title":"Hablando del último partido","duration":"0:55","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/argentina/Argentino_05_audio.mp3","snippet":"Nico y Fede comentan el emocionante partido de anoche entre Boca y River, el golazo, el ambiente del estadio y la pasión de la hinchada.","transcript":"Nico: —Che, ¿viste el partido de anoche? Tremendo lo de Boca, eh.\\n\\nFede: —Sí, boludo, estuvo re parejo hasta el segundo tiempo. Pero ese gol… ¡qué golazo!\\n\\nNico: —Mal. La clavó al ángulo, el arquero no pudo hacer nada. Ese pibe la rompió toda la noche.\\n\\nFede: —Totalmente. Igual River también jugó bien, eh. Hubo un par de jugadas que casi nos embocan.\\n\\nNico: —Sí, zafamos ahí. Pero el ambiente del estadio fue una locura, la gente no paraba de cantar.\\n\\nFede: —Eso suma un montón. Cuando la hinchada empuja, los jugadores se agrandan.\\n\\nNico: —Tal cual. Yo salí afónico de tanto gritar, pero valió la pena.\\n\\nFede: —De una. Partidos así dan gusto verlos, más allá de quién gane.","vocab":[{"term":"Che","meaning":"Hey / You know — Very common Argentine interjection used to get attention or start a sentence."},{"term":"Estuvo re parejo","meaning":"The match was very even / very close — Re is an informal intensifier meaning very."},{"term":"¡Qué golazo!","meaning":"What an amazing goal! — The suffix -azo adds emphasis and admiration."},{"term":"La clavó al ángulo","meaning":"He placed it perfectly in the top corner — Common football expression for a precise, unstoppable shot."},{"term":"La rompió","meaning":"He crushed it / He played amazingly well — Informal phrase meaning someone performed extremely well."},{"term":"Zafar / zafamos","meaning":"To get away with it / to escape danger — Used when a team avoids conceding a goal."},{"term":"La hinchada","meaning":"The fans / supporters — Refers to the passionate crowd supporting a team in the stadium."},{"term":"De una","meaning":"For sure / Absolutely — Strong, enthusiastic agreement in Argentine Spanish."}],"quiz":[{"id":"q1","type":"single","question":"¿Qué sensación general les dejó el partido a los dos amigos?","options":["Que fue fácil para un solo equipo","Que estuvo muy disputado y emocionante","Que fue desordenado y sin público"],"answerIndex":1,"explanation":"Fede dice que estuvo re parejo hasta el segundo tiempo, indicando que fue muy disputado."},{"id":"q2","type":"single","question":"Cuando dicen \\"la clavó al ángulo\\", ¿qué quieren expresar principalmente?","options":["Que el gol fue suerte","Que fue un remate muy preciso y difícil de atajar","Que el arquero estaba mal ubicado"],"answerIndex":1,"explanation":"La expresión \'la clavó al ángulo\' describe un remate muy preciso al ángulo del arco."},{"id":"q3","type":"single","question":"¿Por qué el ambiente del estadio fue tan importante para ellos?","options":["Porque distrajo a los jugadores","Porque hizo que el partido se suspendiera","Porque la energía de la gente influyó en el juego y la experiencia"],"answerIndex":2,"explanation":"Fede dice que cuando la hinchada empuja, los jugadores se agrandan."},{"id":"q4","type":"single","question":"¿Qué se puede inferir de la actitud de Nico al final de la conversación?","options":["Que se arrepiente de haber ido","Que, aunque quedó sin voz, disfrutó mucho el partido","Que no le gusta ver fútbol en el estadio"],"answerIndex":1,"explanation":"Nico dice que salió afónico de tanto gritar, pero valió la pena."}]},{"id":"mex-01","level":"accent-mexican","title":"Un día normal en la Ciudad de México","duration":"2:15","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/mexico/Mexicano_01_audio.mp3","snippet":"Diálogo sobre la vida cotidiana en la Ciudad de México: el metro, el tráfico, los puestos de comida y el ritmo acelerado de la capital.","transcript":"A: —¿Qué onda, María? ¿Cómo te fue hoy en la Ciudad de México?\\n\\nB: —Híjole… estuvo intenso. El metro venía llenísimo desde temprano. Me tuve que dejar pasar como tres trenes porque simplemente no cabía.\\n\\nA: —Sí, en la mañana es imposible. ¿Te fuiste por la Línea 3 otra vez?\\n\\nB: —Ajá, y luego el transborde estaba eterno. Después intenté agarrar el Metrobús, pero se tardó un buen por el tráfico en Insurgentes.\\n\\nA: —Clásico. A mí me pasó igual ayer; salí como a las siete y llegué a la oficina casi a las nueve. ¿Y al menos desayunaste algo?\\n\\nB: —Sí, afuera del metro había un puestito. Me compré un tamal verde y un atole de fresa. Eso sí, riquísimos.\\n\\nA: —Ah, qué bueno. Esos puestitos salvan la mañana. ¿Y cómo estuvo el regreso?\\n\\nB: —Un poco mejor, pero igual había tráfico pesado. Al final llegué como a las ocho de la noche.\\n\\nA: —Así es esto. El ritmo de vida aquí no perdona.\\n\\nB: —Para nada. Pero bueno, ya estoy en casa, así que a descansar.","vocab":[{"term":"¿Qué onda?","meaning":"Informal greeting meaning \'What\'s up?\'"},{"term":"¿Cómo te fue?","meaning":"\'How did it go?\' Used to ask about someone\'s day or experience."},{"term":"Se tardó un buen","meaning":"\'It took a long time / it was really slow.\' Mexican informal expression."},{"term":"Hora pico","meaning":"\'Rush hour.\' The busiest time with heavy traffic."},{"term":"Puesto / puestito","meaning":"\'Street food stand / small vendor.\' Very typical in Mexican cities."},{"term":"Tacos de canasta / tamales","meaning":"Common Mexican street foods, inexpensive and bought on the go."},{"term":"El metro venía llenísimo","meaning":"\'The subway was completely packed.\' Natural way to describe crowded transport."},{"term":"El ritmo de vida no perdona","meaning":"\'The fast pace of life doesn\'t forgive.\' Life in the city is intense and demanding."}],"quiz":[{"id":"q1","type":"single","question":"¿Por qué María tuvo que dejar pasar varios trenes del metro?","options":["Porque llegó tarde","Porque se equivocó de línea","Porque venían llenísimos y no cabía"],"answerIndex":2,"explanation":"María dice que tuvo que dejar pasar como tres trenes porque simplemente no cabía."},{"id":"q2","type":"single","question":"¿Qué transporte intentó tomar María después del metro?","options":["Un taxi","El Metrobús","Un trolebús"],"answerIndex":1,"explanation":"Después del metro, María intentó agarrar el Metrobús pero se tardó por el tráfico en Insurgentes."},{"id":"q3","type":"single","question":"¿Qué compró María para desayunar afuera del metro?","options":["Un tamal verde y un atole de fresa","Unos tacos de canasta","Un café y una concha"],"answerIndex":0,"explanation":"María se compró un tamal verde y un atole de fresa en un puestito afuera del metro."},{"id":"q4","type":"single","question":"Según la conversación, ¿qué caracteriza al ritmo de vida en la Ciudad de México?","options":["Es lento y relajado","Es muy ordenado","Es rápido y exigente"],"answerIndex":2,"explanation":"El amigo dice que \'el ritmo de vida aquí no perdona\', indicando que es rápido y exigente."},{"id":"q5","type":"single","question":"¿Cómo estuvo el regreso de María a su casa?","options":["Mucho peor que en la mañana","Un poco mejor, pero con tráfico pesado","Muy rápido y sin tráfico"],"answerIndex":1,"explanation":"María dice que el regreso estuvo un poco mejor, pero igual había tráfico pesado."}]},{"id":"mex-02","level":"accent-mexican","title":"Conversación en una taquería","duration":"2:30","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/mexico/Mexicano_02_audio.mp3","snippet":"Un cliente llega a una taquería por la noche. Aprenderás vocabulario típico mexicano como \'órale\', \'con todo\', \'campechano\' y expresiones de los taqueros.","transcript":"Cliente: —¡Buenas noches! ¿Todavía hay tacos?\\n\\nTaquero: —¡Órale, pásale! Aquí nunca se acaban. ¿De cuáles va a querer? Tengo pastor, suadero, campechano y longaniza.\\n\\nCliente: —Mmm… dame dos de pastor con piña y uno campechano, por favor.\\n\\nTaquero: —Va, ya están saliendo. ¿Con todo?\\n\\nCliente: —Sí, con todo, pero la cebolla poquita.\\n\\nTaquero: —Perfecto. ¿Y de salsas cómo anda? Tengo verde, roja, y una especial que sí pica en serio.\\n\\nCliente: —Uy… a ver, quiero probar, pero tampoco quiero llorar.\\n\\nTaquero: —Jajaja, entonces no le pongo de la especial. Esa sí está brava. Le pongo tantita verde, ¿sale?\\n\\nCliente: —Sí, mejor poquita. No quiero que me arda todo el camino a mi casa.\\n\\nTaquero: —Listo. ¿Va a querer algo de tomar? Tengo jamaica, horchata, tamarindo y limón con chía.\\n\\nCliente: —Uy, horchata, por favor. Un vaso grande.\\n\\nTaquero: —Ahorita se lo sirvo. Oiga, ¿va a querer más después? Porque los de suadero están buenos hoy, eh.\\n\\nCliente: —¿Sí? A ver… si me gustan estos regreso por dos más.\\n\\nTaquero: —Eso, así me gusta. Aquí estamos. Sus tacos están listos, joven.\\n\\nCliente: —¡Gracias! Se ven buenísimos.\\n\\nTaquero: —Pues órale, pruebe y me dice.\\n\\nCliente: —Mmm… ¡no inventes! El campechano está buenísimo.\\n\\nTaquero: —Le dije, joven. Aquí puro taco ganador.\\n\\nCliente: —Ya valí… sí me voy a echar otros dos de suadero.\\n\\nTaquero: —¡Eso! Ahorita se los preparo.","vocab":[{"term":"Órale","meaning":"Mexican expression meaning \'wow,\' \'okay,\' \'sounds good,\' or \'let\'s go,\' depending on tone."},{"term":"Con todo","meaning":"\'With everything on it\' (all toppings/ingredients included)."},{"term":"Pastor","meaning":"Marinated pork cooked on a vertical spit, often served with pineapple."},{"term":"Suadero","meaning":"A soft, thin cut of beef commonly used in street tacos."},{"term":"Campechano","meaning":"A mix of two meats in one taco (e.g., suadero + longaniza)."},{"term":"Aguas frescas","meaning":"Traditional Mexican flavored drinks (horchata, jamaica, tamarindo, etc.)."},{"term":"¿De cuáles va a querer?","meaning":"\'Which ones would you like?\' Typical taquero question."},{"term":"Está brava (la salsa)","meaning":"\'The salsa is really spicy / very hot.\'"}],"quiz":[{"id":"q1","type":"single","question":"¿Por qué el taquero decide no ponerle la salsa especial al cliente?","options":["Porque ya no le quedaba","Porque el cliente dijo que no quería llorar por lo picosa que estaba","Porque solo se la ofrece a clientes frecuentes"],"answerIndex":1,"explanation":"El cliente dijo que quería probar pero no quería llorar, así que el taquero no le puso la salsa especial."},{"id":"q2","type":"single","question":"¿Qué tipo de bebida pide el cliente para acompañar sus tacos?","options":["Agua de jamaica","Horchata","Limón con chía"],"answerIndex":1,"explanation":"El cliente pide horchata, un vaso grande."},{"id":"q3","type":"single","question":"¿Qué intención tiene el taquero cuando le pregunta al cliente si va a querer más tacos después?","options":["Quiere saber si debe cerrar la taquería","Quiere recomendarle los tacos de pastor","Quiere convencerlo de probar los tacos de suadero, que están buenos ese día"],"answerIndex":2,"explanation":"El taquero le dice que los de suadero están buenos ese día para convencerlo de probar más."},{"id":"q4","type":"single","question":"¿Qué expresa el taquero al decir \'órale\' al inicio de la conversación?","options":["Una bienvenida amistosa y aprobación para que el cliente pase","Enfado porque el cliente llegó tarde","Una despedida informal"],"answerIndex":0,"explanation":"\'Órale, pásale\' es una bienvenida amistosa típica mexicana."},{"id":"q5","type":"single","question":"¿Qué reacción tiene el cliente después de probar el taco campechano?","options":["Dice que está demasiado salado","Decide no pedir nada más","Le gusta tanto que pide dos tacos más"],"answerIndex":2,"explanation":"Al cliente le encanta el campechano y decide pedir dos tacos más de suadero."}]},{"id":"mex-03","level":"accent-mexican","title":"Planeando un viaje por México","duration":"1:50","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/mexico/Mexicano_03_audio.mp3","snippet":"Ana y Carlos planean un viaje por México. Aprenderás expresiones como \'está muy padre\', \'imperdible\', \'vale la pena\' y vocabulario de viajes.","transcript":"Ana: —Carlos, estoy planeando un viaje por México para enero. ¿Qué ciudades me recomiendas?\\n\\nCarlos: —Pues si quieres cultura y comida rica, Oaxaca es imperdible. El clima en enero está súper agradable.\\n\\nAna: —Oaxaca me encanta. También pensé en Guadalajara, porque dicen que está muy padre para caminar.\\n\\nCarlos: —Sí, y Tlaquepaque es buenísimo para artesanías. ¿Y la CDMX? Tiene muchísimo que hacer.\\n\\nAna: —Sí quiero ir, pero el tráfico me asusta.\\n\\nCarlos: —Usa metro o metrobús y ya. Además, hay hospedaje para todos los presupuestos.\\n\\nAna: —También quiero pasar por Puebla, nunca he probado el mole allá.\\n\\nCarlos: —Tienes que ir. Solo lleva suéter porque hace frío en la noche.\\n\\nAna: —¿Y Monterrey? Me dijeron que es caro.\\n\\nCarlos: —Un poco, sí, pero los paisajes valen la pena. Ahí conviene rentar coche.\\n\\nAna: —Creo que haré Oaxaca → CDMX → Puebla → Guadalajara. ¿Suena bien?\\n\\nCarlos: —Perfecto. Solo revisa vuelos entre ciudades para ahorrar tiempo.\\n\\nAna: —Gracias, Carlos. ¡Me emocioné más!\\n\\nCarlos: —Cuando vuelvas me cuentas… y me traes un mezcalito, ¿eh?\\n\\nAna: —Órale, queda hecho.","vocab":[{"term":"Imperdible","meaning":"Must-see / unmissable"},{"term":"Está súper agradable","meaning":"It\'s really nice / very pleasant"},{"term":"Está muy padre","meaning":"It\'s really cool / it\'s great (Mexican slang)"},{"term":"Artesanías","meaning":"Handicrafts / handcrafted goods"},{"term":"Hospedaje","meaning":"Lodging / accommodation"},{"term":"Presupuestos","meaning":"Budgets / price ranges"},{"term":"Valen la pena","meaning":"They\'re worth it"},{"term":"Órale, queda hecho","meaning":"Alright! / Deal! / Sounds good, it\'s done"}],"quiz":[{"id":"q1","type":"single","question":"¿Por qué Carlos recomienda Oaxaca?","options":["Porque es una ciudad muy barata","Porque tiene cultura y comida rica","Porque está cerca de Monterrey"],"answerIndex":1,"explanation":"Carlos dice que Oaxaca es imperdible si quieres cultura y comida rica."},{"id":"q2","type":"single","question":"¿Qué le preocupa a Ana sobre visitar la CDMX?","options":["El clima","El tráfico","Los museos"],"answerIndex":1,"explanation":"Ana dice que sí quiere ir a la CDMX pero el tráfico le asusta."},{"id":"q3","type":"single","question":"¿Qué recomienda Carlos para moverse en la CDMX?","options":["Caminar siempre","Usar metro o metrobús","Tomar taxis privados únicamente"],"answerIndex":1,"explanation":"Carlos recomienda usar metro o metrobús para evitar el tráfico."},{"id":"q4","type":"single","question":"¿Qué dice Carlos sobre Monterrey?","options":["Que es muy económico","Que no vale la pena visitarlo","Que es un poco caro, pero sus paisajes valen la pena"],"answerIndex":2,"explanation":"Carlos dice que Monterrey es un poco caro, pero los paisajes valen la pena."}]},{"id":"mex-04","level":"accent-mexican","title":"En una fiesta familiar mexicana","duration":"1:45","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/mexico/Mexicano_04_audio.mp3","snippet":"Laura y Carlos conversan en una fiesta familiar sobre la música, la comida y las tradiciones mexicanas como la \'carrilla\' entre familiares.","transcript":"Laura: —Oye, qué buena está la música, ¿no? Primero pusieron cumbia y ahora ya andan con la banda.\\n\\nCarlos: —Sí, aquí siempre es así. Empiezan tranqui y luego mi tío le sube todo al norteño, como si fuera cantina.\\n\\nLaura: —Jajaja, típico. Oye, ¿ya probaste el mole que hizo mi abuela?\\n\\nCarlos: —Claro, y también los tamales y la ensalada. La neta, uno viene a estas fiestas más por la comida que por la familia.\\n\\nLaura: —No seas grosero… bueno, tantito sí es cierto. Además, siempre salen las bromas. ¿Ya viste cómo le están echando carrilla a mi primo por llegar tarde?\\n\\nCarlos: —Sí, pobre. Pero pues así somos, si no te molestan, es porque no te quieren.\\n\\nLaura: —Exacto. A mis amigos extranjeros les sorprende eso, dicen que somos muy llevados.\\n\\nCarlos: —Pues es parte de la cultura. Mucha comida, música fuerte y familia metiéndose en todo.\\n\\nLaura: —Y aun así, no lo cambiaríamos por nada, ¿verdad?\\n\\nCarlos: —Jamás. Ahora sí, vamos por otro plato antes de que se acabe.","vocab":[{"term":"andar con + música/estilo","meaning":"To be playing / to be into (a certain style at the moment)"},{"term":"tranqui","meaning":"Chill / relaxed / easygoing"},{"term":"la neta","meaning":"Honestly / the truth is"},{"term":"echar carrilla","meaning":"To tease / to joke around with someone"},{"term":"ser llevados","meaning":"To be very playful / to tease people a lot (in a friendly way)"},{"term":"meterse en todo","meaning":"To get involved in everything / to meddle"},{"term":"no lo cambiaría por nada","meaning":"I wouldn\'t trade it for anything"}],"quiz":[{"id":"q1","type":"single","question":"¿Qué tipo de música se menciona en la fiesta?","options":["Solo música pop","Cumbia, banda y norteño","Rock y electrónica","Mariachi solamente"],"answerIndex":1,"explanation":"Laura menciona que primero pusieron cumbia y luego banda, y Carlos habla del norteño."},{"id":"q2","type":"single","question":"¿Qué comida menciona Carlos que ya probó en la fiesta?","options":["Mole, tamales y ensalada","Pozole y tacos","Ensalada y pastel","Mole y arroz"],"answerIndex":0,"explanation":"Carlos dice que probó el mole, los tamales y la ensalada."},{"id":"q3","type":"single","question":"Cuando Carlos dice que la gente va más por la comida que por la familia, ¿qué quiere expresar realmente?","options":["Que no le gusta convivir con su familia","Que la comida es una parte muy importante de estas fiestas","Que la familia no cocina bien","Que solo le interesa comer gratis"],"answerIndex":1,"explanation":"Carlos exagera de forma humorística para enfatizar lo deliciosa e importante que es la comida en las reuniones familiares mexicanas."},{"id":"q4","type":"single","question":"¿Qué se puede inferir sobre las bromas y la \'carrilla\' en este contexto cultural?","options":["Son una forma de faltar al respeto","Se hacen solo a personas que no caen bien","Son una muestra de cercanía y confianza","Se evitan en reuniones familiares"],"answerIndex":2,"explanation":"Carlos explica que \'si no te molestan, es porque no te quieren\', indicando que la carrilla es señal de cariño y confianza."}]},{"id":"mex-05","level":"accent-mexican","title":"Una cita en la oficina","duration":"1:30","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/mexico/Mexicano_05_audioi.mp3","snippet":"Rodrigo y Carlos coordinan la entrega de un proyecto urgente antes de una junta con el jefe. Vocabulario de oficina y expresiones mexicanas coloquiales.","transcript":"Rodrigo: —Oye, Carlos, ¿tienes un minutito? Quería hablar contigo del proyecto del cliente nuevo.\\n\\nCarlos: —Sí, claro. Dime, ¿qué onda? ¿Ya quedó la presentación?\\n\\nRodrigo: —Casi. Me falta revisar unos números, pero necesito que me eches la mano con la parte del presupuesto.\\n\\nCarlos: —Va, sin problema. ¿Para cuándo lo quiere el jefe?\\n\\nRodrigo: —Para mañana en la mañana. Me dijo que lo necesitaba antes de la junta de las diez.\\n\\nCarlos: —Uf, está justo el tiempo. Ahorita lo checo y te aviso si veo algo raro.\\n\\nRodrigo: —Gracias. Oye, ¿tú vas a poder llegar temprano mañana?\\n\\nCarlos: —Sí, entro desde las ocho. Si quieres, lo vemos rápido antes de la junta.\\n\\nRodrigo: —Perfecto. Así ya vamos más tranquilos y no nos agarra el jefe en curva.\\n\\nCarlos: —Exacto. Tú mándame el archivo y lo reviso hoy mismo.\\n\\nRodrigo: —Va, te lo mando en cinco minutos. ¡Gracias otra vez!","vocab":[{"term":"¿Qué onda?","meaning":"What\'s up? / What\'s going on?"},{"term":"¿Ya quedó?","meaning":"Is it done? / Is it ready?"},{"term":"echar la mano","meaning":"To help out / to lend a hand"},{"term":"Va","meaning":"Okay / sounds good / got it"},{"term":"Ahorita","meaning":"Right now / in a moment (can be ambiguous in Mexican Spanish)"},{"term":"lo checo y te aviso","meaning":"I\'ll check it and let you know"},{"term":"no nos agarra en curva","meaning":"So it doesn\'t catch us off guard / by surprise"}],"quiz":[{"id":"q1","type":"single","question":"¿Sobre qué quieren hablar Rodrigo y Carlos?","options":["Una junta interna del equipo","Un problema personal","El proyecto de un cliente nuevo","Un cambio de horario"],"answerIndex":2,"explanation":"Rodrigo le dice a Carlos que quiere hablar sobre el proyecto del cliente nuevo."},{"id":"q2","type":"single","question":"¿Para cuándo necesita el jefe el proyecto?","options":["Para el final de la semana","Para hoy en la tarde","Para mañana en la mañana, antes de la junta","Para después de la junta"],"answerIndex":2,"explanation":"Rodrigo dice que el jefe lo necesita para mañana en la mañana, antes de la junta de las diez."},{"id":"q3","type":"single","question":"Cuando Carlos dice \'Uf, está justo el tiempo\', ¿qué expresa principalmente?","options":["Que no quiere ayudar","Que el proyecto ya está terminado","Que el plazo es muy corto y hay presión de tiempo","Que no entiende el proyecto"],"answerIndex":2,"explanation":"Carlos expresa que el tiempo está muy ajustado para entregar el proyecto."},{"id":"q4","type":"single","question":"¿Qué se puede inferir sobre la relación laboral entre Rodrigo y Carlos?","options":["Es distante y formal","Es competitiva","Es colaborativa y de apoyo mutuo","Es conflictiva"],"answerIndex":2,"explanation":"Carlos acepta ayudar sin problema y proponen reunirse temprano para revisar juntos, mostrando colaboración."}]},{"id":"mex-06","level":"accent-mexican","title":"Llegar tarde \\"a la mexicana\\"","duration":"1:20","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/mexico/Mexicano_06_audio.mp3","snippet":"Noe y Raque hablan sobre la costumbre mexicana de llegar tarde a las reuniones. Aprenderás expresiones como \'a las dos mexicanas\', \'ahorita\' y \'quedar mal\'.","transcript":"Raque: —Oye, Noe, ¿no que la comida era a las dos?\\n\\nNoe: —Sí, sí… a las dos mexicanas.\\n\\nRaque: —Explícame eso otra vez, porque yo llegué puntual.\\n\\nNoe: —Pues es que aquí decir dos no siempre es dos.\\n\\nRaque: —Eso ya lo noté. Ya son casi tres.\\n\\nNoe: —Bueno, pero dime, ¿ya llegó alguien más?\\n\\nRaque: —Solo tu prima… y también llegó tarde.\\n\\nNoe: —¿Ves? Te dije.\\n\\nRaque: —Pero luego uno queda mal por llegar temprano.\\n\\nNoe: —Sí, eso sí pasa. Aquí llegas temprano y te ponen a ayudar.\\n\\nRaque: —Ya me di cuenta. ¿Llevo algo?\\n\\nNoe: —Sí, ahorita paso al Oxxo por unas bebidas.\\n\\nRaque: —Ay no, ¿ahorita? Eso puede ser en cinco minutos o en una hora.\\n\\nNoe: —Jajaja, ya voy, ya voy. ¡Órale!","vocab":[{"term":"a las dos mexicanas","meaning":"\'Mexican time\' / not exactly at two"},{"term":"llegar puntual","meaning":"To arrive on time"},{"term":"quedar mal","meaning":"To look bad / to leave a bad impression"},{"term":"te ponen a ayudar","meaning":"They make you help / they put you to work"},{"term":"¿Llevo algo?","meaning":"Should I bring anything?"},{"term":"ahorita","meaning":"Right now / in a bit / sometime soon (often flexible in Mexican Spanish)"},{"term":"Órale","meaning":"Alright! / Okay! / Let\'s go!"}],"quiz":[{"id":"q1","type":"single","question":"¿Qué significa \'a las dos mexicanas\' en la conversación?","options":["Que la comida empieza exactamente a las dos","Que la hora es aproximada y suele empezar más tarde","Que solo llegan familiares cercanos","Que la comida dura todo el día"],"answerIndex":1,"explanation":"En México, \'a las dos mexicanas\' significa que la hora es flexible y probablemente empezará más tarde."},{"id":"q2","type":"single","question":"¿Qué ocurre cuando alguien llega temprano, según la conversación?","options":["Se va a su casa","Es ignorado por los demás","Le piden que ayude con los preparativos","Se enoja y se queja"],"answerIndex":2,"explanation":"Noe dice que si llegas temprano, te ponen a ayudar con los preparativos."},{"id":"q3","type":"single","question":"Cuando Noe dice \'ahorita paso al Oxxo\', ¿por qué Raque se preocupa?","options":["Porque el Oxxo está muy lejos","Porque Noe no sabe qué comprar","Porque Raque ya no quiere esperar","Porque \'ahorita\' puede significar que tardará más de lo esperado"],"answerIndex":3,"explanation":"En México, \'ahorita\' es ambiguo y puede significar desde cinco minutos hasta una hora o más."},{"id":"q4","type":"single","question":"¿Qué aspecto cultural se refleja principalmente en la conversación?","options":["La importancia de la puntualidad estricta","El rechazo a ayudar en reuniones familiares","La costumbre de irse temprano de las fiestas","La flexibilidad con el tiempo en reuniones sociales"],"answerIndex":3,"explanation":"La conversación refleja la flexibilidad con el tiempo que es común en reuniones sociales mexicanas."}]},{"id":"mex-07","level":"accent-mexican","title":"El verdadero significado de \\"ahorita\\"","duration":"1:25","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/mexico/Mexicano_07_audio.mp3","snippet":"Ana y Luis discuten el significado ambiguo de \'ahorita\' en México. Aprenderás por qué esta palabra puede significar \'ahora\', \'en un rato\' o incluso \'nunca\'.","transcript":"Ana: —Luis, ¿me puedes mandar el archivo que te pedí?\\n\\nLuis: —Sí, ahorita te lo mando.\\n\\nAna: —Ajá… ¿ahorita cuándo exactamente?\\n\\nLuis: —Pues ahorita en un rato.\\n\\nAna: —¿Ves? Eso es justo lo que confunde.\\n\\nLuis: —Bueno, es que \'ahorita\' puede ser muchas cosas.\\n\\nAna: —Para mí solo significa ahora.\\n\\nLuis: —Aquí no siempre. A veces es \'en unos minutos\' y a veces es \'luego\'.\\n\\nAna: —Y a veces es \'nunca\'.\\n\\nLuis: —Jajaja, tampoco exageres.\\n\\nAna: —La semana pasada me dijiste \'ahorita te llamo\' y nunca llamaste.\\n\\nLuis: —Bueno, es que se me complicó.\\n\\nAna: —¿Ves? Por eso los extranjeros se desesperan con nosotros.\\n\\nLuis: —Tienes razón. Mejor digo \'en diez minutos\', suena menos directo pero al menos es claro.\\n\\nAna: —Eso sería un milagro viniendo de ti.\\n\\nLuis: —¡Oye! Ya, ya… te lo mando en cinco minutos, de verdad.","vocab":[{"term":"ahorita","meaning":"Right now / in a bit / later (very flexible in Mexican Spanish)"},{"term":"ahorita en un rato","meaning":"In a little while / soon (but not now)"},{"term":"ajá","meaning":"Uh-huh / yeah, right (often shows doubt or mild irony, depending on tone)"},{"term":"eso es justo lo que confunde","meaning":"That\'s exactly what causes confusion"},{"term":"se me complicó","meaning":"Something came up / it got complicated for me"},{"term":"suena menos directo","meaning":"It sounds less direct"}],"quiz":[{"id":"q1","type":"single","question":"¿Por qué Ana se confunde con la respuesta de Luis?","options":["Porque no entiende de qué archivo hablan","Porque Luis se ríe en lugar de responder","Porque la palabra \'ahorita\' no indica un tiempo exacto","Porque Luis se niega a mandar el archivo"],"answerIndex":2,"explanation":"Ana se confunde porque \'ahorita\' en México no indica un tiempo específico."},{"id":"q2","type":"single","question":"¿Qué diferentes significados puede tener \'ahorita\', según la conversación?","options":["Solo significa \'ahora mismo\'","Significa únicamente \'mañana\'","Significa \'nunca\'","Puede significar ahora, en unos minutos o más tarde"],"answerIndex":3,"explanation":"Luis explica que \'ahorita\' puede significar ahora, en unos minutos, o luego."},{"id":"q3","type":"single","question":"¿Qué problema cultural menciona Ana cuando habla de los extranjeros?","options":["Que no les gusta trabajar en equipo","Que se desesperan porque no entienden expresiones ambiguas","Que no comprenden los archivos digitales","Que llegan tarde a las reuniones"],"answerIndex":1,"explanation":"Ana dice que los extranjeros se desesperan porque no entienden la ambigüedad de \'ahorita\'."},{"id":"q4","type":"single","question":"¿Qué cambio decide hacer Luis al final de la conversación?","options":["No volver a trabajar con Ana","Mandar el archivo al día siguiente","Dar un tiempo claro en lugar de decir \'ahorita\'","Dejar de enviar archivos por mensaje"],"answerIndex":2,"explanation":"Luis decide dar un tiempo específico (\'en cinco minutos\') en lugar de usar \'ahorita\'."}]},{"id":"mex-08","level":"accent-mexican","title":"El picante y la identidad mexicana","duration":"1:30","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/mexico/Mexicano_08_audio.mp3","snippet":"Tom, un extranjero, aprende sobre la cultura del picante en México con ayuda de María. Vocabulario sobre comida picante y expresiones coloquiales.","transcript":"Tom: —María, ¿segura que esta salsa no pica nada?\\n\\nMaría: —Sí, está muy leve.\\n\\nTom: —Eso dijiste ayer… y sufrí.\\n\\nMaría: —Es que para mí eso no pica.\\n\\nTom: —Creo que tenemos escalas diferentes.\\n\\nMaría: —Totalmente. El picante aquí es parte de la comida.\\n\\nTom: —¿Desde niños comen así?\\n\\nMaría: —Sí, poco a poco. Empiezas con poquito.\\n\\nTom: —Ok, voy a probar otra vez.\\n\\nMaría: —Échale solo tantito.\\n\\nTom: —(prueba) Mmm… pica, pero está rico.\\n\\nMaría: —¿Ves? Eso pasa siempre.\\n\\nTom: —Me arde un poco, pero sigo comiendo.\\n\\nMaría: —Jajaja, eso es muy mexicano de tu parte.\\n\\nTom: —Creo que me estoy adaptando.\\n\\nMaría: —Ya eres mexicano honorario.","vocab":[{"term":"no pica nada","meaning":"It\'s not spicy at all"},{"term":"está muy leve","meaning":"It\'s very mild"},{"term":"eso no pica","meaning":"That\'s not spicy (to me)"},{"term":"échale solo tantito","meaning":"Just add a tiny bit"},{"term":"me arde","meaning":"It burns"},{"term":"muy mexicano de tu parte","meaning":"Very Mexican of you"},{"term":"mexicano honorario","meaning":"Honorary Mexican"}],"quiz":[{"id":"q1","type":"single","question":"¿Por qué Tom duda cuando María dice que la salsa \'no pica\'?","options":["Porque nunca ha probado salsa mexicana","Porque en otra ocasión María dijo lo mismo y la salsa sí picaba","Porque no le gusta la comida mexicana","Porque tiene alergia al chile"],"answerIndex":1,"explanation":"Tom recuerda que ayer María también dijo que no picaba y él sufrió."},{"id":"q2","type":"single","question":"¿Qué explica María sobre el picante en México?","options":["Que solo los adultos lo consumen","Que se evita en comidas familiares","Que forma parte de la comida y se aprende desde niños","Que solo se usa en salsas especiales"],"answerIndex":2,"explanation":"María explica que el picante es parte de la comida y que desde niños empiezan poco a poco."},{"id":"q3","type":"single","question":"Cuando María dice que Tom ya es \'muy mexicano\', ¿a qué se refiere?","options":["A que ya cocina comida mexicana","A que ya habla español perfectamente","A que ya no le pica el chile","A que se queja del picante pero sigue comiendo"],"answerIndex":3,"explanation":"María dice que es \'muy mexicano\' porque Tom sigue comiendo aunque le arde."},{"id":"q4","type":"single","question":"¿Qué idea cultural transmite principalmente la conversación?","options":["Que el picante es solo una moda","Que los extranjeros nunca se adaptan","Que la comida mexicana es peligrosa","Que el picante forma parte de la identidad y experiencia cultural mexicana"],"answerIndex":3,"explanation":"La conversación muestra cómo el picante es parte integral de la cultura y comida mexicana."}]},{"id":"mex-09","level":"accent-mexican","title":"La familia siempre opina","duration":"1:35","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/mexico/Mexicano_09_audio.mp3","snippet":"Sofía prepara a Diego para una comida familiar donde toda la familia querrá opinar sobre él. Aprenderás sobre la dinámica familiar mexicana y expresiones coloquiales.","transcript":"Sofía: —Oye, mi mamá volvió a preguntar si vienes el domingo.\\n\\nDiego: —¿Otra vez comida familiar?\\n\\nSofía: —Sí, y ahora también preguntó mi tía, la que siempre quiere saber todo.\\n\\nDiego: —¿Y por qué toda tu familia quiere saber tanto de mí?\\n\\nSofía: —Porque ya eres parte de la familia, aunque no quieras aceptarlo.\\n\\nDiego: —Eso suena un poco intenso, la verdad.\\n\\nSofía: —Lo es. Prepárate porque van a opinar de todo.\\n\\nDiego: —¿De qué tipo de cosas?\\n\\nSofía: —De tu trabajo, de tu acento, de si comes bien o no.\\n\\nDiego: —¿Y si digo que como muy sano?\\n\\nSofía: —No te creen. Mejor acepta la comida que te sirvan.\\n\\nDiego: —Entendido. Estrategia: llegar con hambre.\\n\\nSofía: —Exacto. Y sonreír mucho.\\n\\nDiego: —¿Aunque me pregunten cosas incómodas?\\n\\nSofía: —Sí, pero todo es con buena intención.\\n\\nDiego: —Eso espero.","vocab":[{"term":"querer saber todo","meaning":"To want to know everything / to be nosy"},{"term":"parte de la familia","meaning":"Part of the family"},{"term":"opinar de todo","meaning":"To have an opinion about everything"},{"term":"no te creen","meaning":"They don\'t believe you"}],"quiz":[{"id":"q1","type":"single","question":"¿Por qué la familia de Sofía pregunta tanto por Diego?","options":["Porque no confían en él","Porque creen que Diego no quiere ir a la comida","Porque quieren invitarlo a trabajar con ellos","Porque lo consideran parte de la familia"],"answerIndex":3,"explanation":"Sofía explica que la familia pregunta por Diego porque ya lo consideran parte de la familia."},{"id":"q2","type":"single","question":"¿Qué tipo de cosas menciona Sofía que su familia suele comentar?","options":["Solo temas políticos y económicos","El trabajo, el acento y la comida de Diego","Únicamente su relación con Sofía","Cosas que Diego pidió que comentaran"],"answerIndex":1,"explanation":"Sofía menciona que opinan sobre su trabajo, su acento y si come bien o no."},{"id":"q3","type":"single","question":"Cuando Sofía dice que todo es \'con buena intención\', ¿qué quiere decir?","options":["Que no harán preguntas","Que solo quieren criticarlo","Que aunque puede ser incómodo, lo hacen por cariño","Que Diego no debe contestar nada"],"answerIndex":2,"explanation":"Sofía quiere decir que aunque las preguntas pueden ser incómodas, la familia las hace con cariño."},{"id":"q4","type":"single","question":"¿Cuál es la \'estrategia\' que Diego entiende al final?","options":["Evitar las comidas familiares","Llegar tarde para que no lo interroguen","No hablar con la familia","Llegar con hambre y aceptar la comida"],"answerIndex":3,"explanation":"Diego entiende que debe llegar con hambre y aceptar la comida que le sirvan."}]},{"id":"mex-10","level":"accent-mexican","title":"Una fiesta mexicana \\"tranqui\\"","duration":"1:40","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/mexico/Mexicano_10_audio.mp3","snippet":"Paula y Jorge hablan sobre una fiesta \'pequeña\' que resulta no ser tan pequeña. Aprenderás vocabulario sobre fiestas y expresiones coloquiales mexicanas.","transcript":"Paula: —Entonces, ¿cómo es la fiesta de hoy?\\n\\nJorge: —Nada grande, algo tranqui.\\n\\nPaula: —Eso dices siempre. ¿Cuánta gente va a ir?\\n\\nJorge: —Pues… como veinte o veinticinco personas.\\n\\nPaula: —Eso no es poquito.\\n\\nJorge: —Para México sí, la verdad.\\n\\nPaula: —Bueno… ¿y va a haber comida o tengo que cenar antes?\\n\\nJorge: —No, claro que va a haber comida, aunque sea taquitos y botana.\\n\\nPaula: —¿De cuáles tacos?\\n\\nJorge: —Creo que de pastor y de bistec.\\n\\nPaula: —Ah, entonces sí voy.\\n\\nJorge: —Jajaja, obvio. La comida no puede faltar.\\n\\nPaula: —¿Y música?\\n\\nJorge: —Sí, lo que salga. Cumbia, reggaetón…\\n\\nPaula: —¿Y a qué hora termina?\\n\\nJorge: —Depende de cómo se ponga la fiesta.\\n\\nPaula: —O sea, puede ser a las tres de la mañana.\\n\\nJorge: —Exacto. Es una fiesta mexicana, ¿no?","vocab":[{"term":"tranqui","meaning":"Chill / relaxed / low-key"},{"term":"aunque sea","meaning":"At least / even if it\'s just"},{"term":"botana","meaning":"Snacks / finger food"},{"term":"obvio","meaning":"Obviously / of course"},{"term":"no puede faltar","meaning":"It\'s a must / it can\'t be missing"},{"term":"lo que salga","meaning":"Whatever comes up / whatever they play"},{"term":"depende de cómo se ponga la fiesta","meaning":"It depends on how the party goes / how it turns out"}],"quiz":[{"id":"q1","type":"single","question":"¿Cómo describe Jorge la fiesta al principio?","options":["Como una fiesta muy formal","Como una reunión solo familiar","Como algo pequeño y \'tranqui\'","Como una fiesta sorpresa"],"answerIndex":2,"explanation":"Jorge describe la fiesta como \'algo tranqui\', es decir, algo relajado y pequeño."},{"id":"q2","type":"single","question":"¿Qué tipo de comida menciona Jorge que habrá en la fiesta?","options":["Solo pastel y postres","Tacos (de pastor y bistec) y botana","Cena elegante con varios platillos","Cada quien lleva su comida"],"answerIndex":1,"explanation":"Jorge menciona que habrá taquitos de pastor y bistec, además de botana."},{"id":"q3","type":"single","question":"Cuando Paula dice \'Eso no es poquito\', ¿qué está expresando?","options":["Que no le gusta ir a fiestas","Que no conoce a nadie en la fiesta","Que para ella, 20 o 25 personas no es una fiesta pequeña","Que no quiere quedarse mucho tiempo"],"answerIndex":2,"explanation":"Paula expresa que 20 o 25 personas no le parece una cantidad pequeña para una fiesta."},{"id":"q4","type":"single","question":"¿Qué idea cultural se refleja al final cuando Jorge dice \'es una fiesta mexicana\'?","options":["Que suelen ser más grandes y largas de lo que se planea","Que no hay mucha música","Que solo se baila cumbia","Que siempre terminan temprano"],"answerIndex":0,"explanation":"Jorge implica que las fiestas mexicanas suelen ser más grandes y largas de lo planeado."}]},{"id":"esp-01","level":"accent-spanish","title":"En una terraza tomando un café","duration":"1:30","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/espa%C3%B1a/Espa%C3%B1a_01_audio.mp3","snippet":"Marta y Diego se encuentran en una terraza y charlan sobre el calor, planes del fin de semana y quedan para verse. Aprenderás expresiones típicas españolas.","transcript":"Marta: —¡Hombre, Diego! ¿Qué tal todo? ¡Hace siglos que no te veo!\\n\\nDiego: —Pues bien, aquí vamos tirando. ¿Y tú qué tal?\\n\\nMarta: —Bien también. Oye, ¿pedimos algo? Me voy a tomar un café solo.\\n\\nDiego: —Yo creo que me voy a pedir un cortado… o mira, una caña, que hace un calorazo.\\n\\nMarta: —Jajaja, ¡siempre igual! Pero sí, hoy hace buen tiempo. Se está genial en la terraza.\\n\\nDiego: —Ya ves. ¿Y qué vais a hacer tú y tus compis este finde?\\n\\nMarta: —Pues estábamos pensando en ir a la playa o dar una vuelta por el centro. ¿Te apuntas?\\n\\nDiego: —¡Venga, me apunto! ¿A qué hora quedamos?\\n\\nMarta: —Sobre las seis, ¿te parece?\\n\\nDiego: —Perfecto. ¡Camarero, una caña por favor!","vocab":[{"term":"¡Hombre!","meaning":"An expression like \'Hey!\' or \'Wow!\', used to greet or show surprise."},{"term":"Tirando","meaning":"\'Getting by\' / \'Doing okay.\'"},{"term":"Café solo","meaning":"Black coffee (espresso without milk)."},{"term":"Cortado","meaning":"Espresso with a small amount of milk."},{"term":"Caña","meaning":"A small draft beer."},{"term":"Calorazo","meaning":"Intense heat / very hot weather."},{"term":"Compis","meaning":"Colloquial for \'mates\', \'buddies\', or \'friends.\'"},{"term":"Camarero","meaning":"Waiter."}],"quiz":[{"id":"q1","type":"single","question":"¿Qué bebida decide pedir finalmente Diego?","options":["Un café solo","Una caña","Un cortado"],"answerIndex":1,"explanation":"Diego decide pedir una caña porque hace mucho calor."},{"id":"q2","type":"single","question":"¿Qué planes tiene Marta para el fin de semana?","options":["Visitar a su familia","Ir al cine","Ir a la playa o dar una vuelta por el centro"],"answerIndex":2,"explanation":"Marta y sus compis estaban pensando en ir a la playa o dar una vuelta por el centro."},{"id":"q3","type":"single","question":"¿Por qué Diego decide pedir una caña?","options":["Porque tiene mucha sed después de hacer ejercicio","Porque hace mucho calor (\'calorazo\')","Porque Marta le insiste"],"answerIndex":1,"explanation":"Diego pide una caña porque hace un calorazo (mucho calor)."},{"id":"q4","type":"single","question":"¿A qué hora proponen quedar?","options":["A las cinco","Sobre las seis","A las ocho"],"answerIndex":1,"explanation":"Marta propone quedar sobre las seis."}]},{"id":"esp-02","level":"accent-spanish","title":"Planeando un viaje por España","duration":"1:40","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/espa%C3%B1a/Espa%C3%B1a_02_audio.mp3","snippet":"Lucía y Carlos planean un viaje por España: Madrid, Sevilla, Valencia y Barcelona. Aprenderás expresiones como \'pillar un tren\', \'está a tope\' y \'viajazo\'.","transcript":"Lucía: —Oye, Carlos, ¿ya habéis pensado por dónde queréis empezar el viaje por España? Yo había pensado empezar por Madrid.\\n\\nCarlos: —Sí, lo estuvimos comentando. Desde allí es fácil pillar un tren de Renfe. Podríamos coger el AVE a Sevilla, que se llega en nada.\\n\\nLucía: —¡Genial! Sevilla merece la pena, aunque he oído que estos días está a tope de turistas.\\n\\nCarlos: —Ya… pero aun así me apetece mucho ir. Y después podríamos bajar a Valencia. Así probáis una paella auténtica.\\n\\nLucía: —Me parece perfecto. Y ya para rematar, Barcelona. Dicen que la Sagrada Familia impresiona muchísimo.\\n\\nCarlos: —Sí, así hacéis un recorrido completo. ¿Queréis que vaya mirando ya horarios antes de que suban los precios?\\n\\nLucía: —Sí, porfa. Echadle un vistazo esta tarde y luego me decís qué opción os convence más.\\n\\nCarlos: —Hecho. ¡Va a ser un viajazo!","vocab":[{"term":"Pillar (un tren)","meaning":"To catch / to take (a train)."},{"term":"Está a tope","meaning":"It\'s packed / very crowded."},{"term":"Merece la pena","meaning":"It\'s worth it."},{"term":"Paella auténtica","meaning":"Authentic paella."},{"term":"Rematar (el recorrido)","meaning":"To finish off / to wrap up (the route)."},{"term":"Impresiona muchísimo","meaning":"It\'s extremely impressive."},{"term":"Echadle un vistazo","meaning":"Take a look (at it)."},{"term":"Viajazo","meaning":"An amazing trip / an epic trip."}],"quiz":[{"id":"q1","type":"single","question":"¿Por qué Lucía propone empezar el viaje en Madrid?","options":["Porque allí vive su familia","Porque es fácil pillar un tren desde allí","Porque los hoteles son más baratos"],"answerIndex":1,"explanation":"Desde Madrid es fácil pillar un tren de Renfe para ir a otras ciudades."},{"id":"q2","type":"single","question":"¿Qué dice Lucía sobre Sevilla?","options":["Que no le interesa visitarla","Que merece la pena, aunque está a tope de turistas","Que queda muy lejos y es complicado llegar"],"answerIndex":1,"explanation":"Lucía dice que Sevilla merece la pena, aunque está a tope de turistas."},{"id":"q3","type":"single","question":"¿Cuál es la razón para ir a Valencia según Carlos?","options":["Para que prueben una paella auténtica","Porque es la ciudad más barata del viaje","Porque allí tienen amigos"],"answerIndex":0,"explanation":"Carlos propone ir a Valencia para que prueben una paella auténtica."},{"id":"q4","type":"single","question":"¿Qué propone Carlos hacer antes de que suban los precios?","options":["Reservar los hoteles","Comprar las entradas para la Sagrada Familia","Mirar los horarios de los trenes"],"answerIndex":2,"explanation":"Carlos propone mirar los horarios de los trenes antes de que suban los precios."}]},{"id":"esp-03","level":"accent-spanish","title":"En un supermercado en España","duration":"1:30","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/espa%C3%B1a/Espa%C3%B1a_03_audio.mp3","snippet":"Un cliente pregunta por productos en un supermercado español. Aprenderás el uso del vosotros y expresiones como \'un pelín\', \'de sobra\' y \'¿Queréis bolsa?\'.","transcript":"Empleado: —Buenas, ¿os puedo ayudar en algo?\\n\\nCliente: —Sí, por favor. ¿Sabéis dónde están las galletas integrales? No las encuentro por ningún lado.\\n\\nEmpleado: —Claro, están en el pasillo tres, justo al lado de los cereales. Si queréis, os acompaño.\\n\\nCliente: —Perfecto, gracias. Oye, ¿tenéis leche sin lactosa de esta marca? En mi país es muy común, pero aquí no la veo tanto.\\n\\nEmpleado: —Sí, aquí manejamos menos marcas, pero mirad: tenemos esta que es bastante buena.\\n\\nCliente: —Genial. ¿Y sabéis si hoy abre la sección de pescadería? Me dijeron que los horarios cambian según el día.\\n\\nEmpleado: —Sí, hoy cierra un pelín antes, a las seis. Si os pasáis ahora, llegáis de sobra.\\n\\nCliente: —Vale, me paso luego.\\n\\nEmpleado: —Perfecto. Cuando terminéis, pasaos por la caja, por favor.\\n\\nCliente (en la caja): —Buenas.\\n\\nEmpleado: —Hola. ¿Queréis bolsa? Tenemos de papel o de tela.\\n\\nCliente: —Una de papel, gracias.\\n\\nEmpleado: —Fenomenal. ¿Tenéis la tarjeta del supermercado?\\n\\nCliente: —No, todavía no la tenemos.\\n\\nEmpleado: —No pasa nada. Pues serían 12,40 €.\\n\\nCliente: —Aquí tenéis. ¡Gracias por todo!\\n\\nEmpleado: —A vosotros. ¡Que tengáis buen día!","vocab":[{"term":"un pelín","meaning":"A little bit / just a tiny bit."},{"term":"pasáis (por la caja)","meaning":"You all go / you all pass through."},{"term":"llegáis de sobra","meaning":"You arrive with plenty of time / more than enough time."},{"term":"¿Os puedo ayudar en algo?","meaning":"Can I help you with anything?"},{"term":"¿Tenéis…?","meaning":"Do you (plural) have…?"},{"term":"justo al lado de…","meaning":"Right next to…"},{"term":"si queréis, os acompaño","meaning":"If you (plural) want, I\'ll go with you / I can show you."},{"term":"¿Queréis bolsa?","meaning":"Do you (plural) want a bag?"}],"quiz":[{"id":"q1","type":"single","question":"¿Qué indica el cliente cuando comenta que en su país la leche sin lactosa es \'muy común\'?","options":["Que prefiere no comprar leche en España","Que no sabe si en España existe ese producto","Que le sorprende que en España haya menos variedad de esa marca"],"answerIndex":2,"explanation":"El cliente expresa sorpresa de que en España no sea tan común como en su país."},{"id":"q2","type":"single","question":"¿Qué sugiere el empleado al decir \'Si os pasáis ahora, llegáis de sobra\'?","options":["Que la pescadería está cerrada y no vale la pena ir","Que todavía hay tiempo para ir antes de que cierre a las seis","Que deberían ir mañana porque hoy está demasiado llena"],"answerIndex":1,"explanation":"El empleado indica que si van ahora, llegarán con tiempo de sobra antes de que cierre a las seis."},{"id":"q3","type":"single","question":"¿Por qué el empleado ofrece acompañar al cliente al pasillo tres?","options":["Porque el supermercado es muy grande y complicado","Porque el cliente pidió ayuda para encontrar los cereales","Porque quiere facilitarle encontrar las galletas integrales sin perder tiempo"],"answerIndex":2,"explanation":"El empleado ofrece acompañarlo para que encuentre fácilmente las galletas integrales."},{"id":"q4","type":"single","question":"¿Qué se puede inferir cuando el empleado pregunta si tienen la tarjeta del supermercado?","options":["Que sin la tarjeta no pueden pagar","Que la tarjeta es obligatoria para comprar productos frescos","Que existe un sistema de fidelidad o descuentos asociado a la tarjeta"],"answerIndex":2,"explanation":"La pregunta sobre la tarjeta indica un sistema de fidelidad o descuentos para clientes."}]},{"id":"col-01","level":"accent-colombian","title":"Tomando tinto en una cafetería","duration":"1:20","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/colombia/Colombia_01_audio.mp3","snippet":"Andrés y Laura se encuentran en una cafetería en Bogotá. Aprenderás expresiones colombianas como \'quiubo\', \'tintico\', \'una nota\' y \'aguacero\'.","transcript":"Andrés: —¡Quiubo! Hace rato no te veía.\\n\\nLaura: —¡Andrés! ¿Cómo estás? Yo bien, ahí voy. ¿Y tú qué? Te ves un poco cansado.\\n\\nAndrés: —Sí, el tráfico estaba terrible hoy. Pero bueno, ya con este tintico el día mejora.\\n\\nLaura: —Total. Aquí preparan un tinto delicioso. ¿Quieres pedir algo para acompañar? Tienen un cheesecake de maracuyá que es una nota.\\n\\nAndrés: —Uy, suena buenísimo. ¿Y tú qué planes tienes para hoy?\\n\\nLaura: —Nada muy especial. Voy a trabajar un rato desde casa y luego tengo que pasar por el centro, pero ojalá no llueva porque el clima está todo loco.\\n\\nAndrés: —Sí, amaneció con sol y ahora parece que va a caer un aguacero en cualquier momento.\\n\\nLaura: —Así es Bogotá. Bueno, pide tú primero.\\n\\nAndrés: —Listo. Eh, joven, ¿nos regala dos tintos y una porción de cheesecake, por favor?\\n\\nMesero: —Claro que sí, ya se los traigo.\\n\\nLaura: —Gracias. Bueno, cuéntame, ¿cómo va todo en el trabajo?\\n\\nAndrés: —Ahí, movidito, pero bien. Te cuento mientras llega el tinto.","vocab":[{"term":"tinto","meaning":"Black coffee (Colombian style)."},{"term":"quiubo","meaning":"Hey! / What\'s up?"},{"term":"una nota","meaning":"Awesome / really good."},{"term":"aguacero","meaning":"Downpour / heavy rain."},{"term":"el clima está todo loco","meaning":"The weather is really unpredictable / crazy weather."},{"term":"movidito","meaning":"Busy / hectic / full of activity."}],"quiz":[{"id":"q1","type":"single","question":"¿Qué sugiere la reacción de Andrés cuando dice que el tintico \'mejora el día\'?","options":["Que no le gusta el café colombiano","Que el tinto le ayuda a relajarse después de un día estresante","Que solo fue a la cafetería por el postre"],"answerIndex":1,"explanation":"Andrés llegó cansado por el tráfico, pero el tinto le ayuda a sentirse mejor."},{"id":"q2","type":"single","question":"¿Por qué Laura menciona que \'el clima está todo loco\'?","options":["Porque no quiere pasar por el centro","Porque el clima cambió rápidamente de sol a amenaza de aguacero","Porque no le gusta el clima de su ciudad"],"answerIndex":1,"explanation":"Laura dice que el clima está loco porque amaneció con sol pero parece que va a llover."},{"id":"q3","type":"single","question":"¿Qué se puede inferir cuando Laura describe el cheesecake de maracuyá como \'una nota\'?","options":["Que no lo recomienda porque es demasiado dulce","Que nunca lo ha probado antes","Que es muy bueno y lo recomienda con entusiasmo"],"answerIndex":2,"explanation":"\'Una nota\' es una expresión colombiana que significa que algo es muy bueno."},{"id":"q4","type":"single","question":"¿Qué implica la respuesta de Andrés sobre su trabajo (\'movidito, pero bien\')?","options":["Que está pensando en renunciar","Que ha estado ocupado, pero las cosas marchan de forma positiva","Que no tiene mucho trabajo últimamente"],"answerIndex":1,"explanation":"\'Movidito\' indica que ha estado ocupado, pero \'bien\' sugiere que todo va positivamente."}]},{"id":"col-02","level":"accent-colombian","title":"Una visita al centro de Medellín","duration":"1:25","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/colombia/Colombia_02_audio.mp3","snippet":"Juan le cuenta a Mariana sobre su visita al centro de Medellín. Aprenderás expresiones paisas como \'parce\', \'bacano\', \'ratico\' y \'nos vemos pues\'.","transcript":"Mariana: —¡Ey, Juan! ¿Cómo te fue hoy por el centro? Dicen que el tráfico está una locura.\\n\\nJuan: —No, parce, tenés que ver eso. Los buses iban llenísimos y el metro iba rápido, pero igual tocó esperar un ratico.\\n\\nMariana: —Me lo imagino. Igual, el centro siempre está movido. ¿Alcanzaste a pasar por el Parque Berrío?\\n\\nJuan: —Sí, pasé un momentico. La gente por allá es muy querida, todo el mundo te saluda. Además, todo queda cerquita, entonces uno camina y llega de una a los sitios.\\n\\nMariana: —Qué bacano. Yo casi no voy, siempre me quedo por Laureles o por El Poblado porque son más tranquilos.\\n\\nJuan: —Sí, total. Pero de vez en cuando vale la pena ir al centro, ver las esculturas de Botero, caminar un rato… Eso sí, hay que ir con paciencia por el tráfico.\\n\\nMariana: —Seguro. ¿Y qué vas a hacer ahora?\\n\\nJuan: —Voy pa\' la casa a descansar un poco. Ese paseo me dejó rendido.\\n\\nMariana: —Hacés bien. Bueno, hablamos luego.\\n\\nJuan: —Listo, que estés bien. Nos vemos pues.","vocab":[{"term":"tráfico está una locura","meaning":"The traffic is crazy."},{"term":"ratico","meaning":"A little while / a short moment."},{"term":"todo queda cerquita","meaning":"Everything is very close by."},{"term":"bacano","meaning":"Cool / great."},{"term":"vale la pena","meaning":"It\'s worth it."},{"term":"rendido","meaning":"Exhausted / worn out."},{"term":"parce","meaning":"Dude / buddy / mate (coloquial paisa)."},{"term":"nos vemos pues","meaning":"See you then / see you later (tono muy colombiano)."}],"quiz":[{"id":"q1","type":"single","question":"¿Qué indica Juan cuando dice que \'los buses iban llenísimos\'?","options":["Que casi no había gente en el transporte","Que el transporte público estaba completamente lleno y era difícil moverse","Que decidió no usar el bus ese día"],"answerIndex":1,"explanation":"Juan indica que los buses estaban muy llenos, lo que hacía difícil moverse."},{"id":"q2","type":"single","question":"¿Por qué Mariana dice que casi no va al centro?","options":["Porque no conoce bien la zona","Porque le parece peligroso","Porque prefiere lugares como Laureles y El Poblado, que son más tranquilos"],"answerIndex":2,"explanation":"Mariana prefiere quedarse por Laureles o El Poblado porque son más tranquilos."},{"id":"q3","type":"single","question":"¿Qué se puede inferir cuando Juan afirma que \'todo queda cerquita\'?","options":["Que el centro tiene pocas cosas para ver","Que las distancias son tan grandes que es mejor usar transporte","Que es fácil caminar y llegar rápido a muchos lugares del centro"],"answerIndex":2,"explanation":"Juan dice que todo queda cerca, así que uno puede caminar y llegar rápido."},{"id":"q4","type":"single","question":"¿Qué transmite Juan al decir que el paseo lo dejó \'rendido\'?","options":["Que no disfrutó la visita","Que quiere volver al centro de inmediato","Que terminó muy cansado después de caminar y lidiar con el tráfico"],"answerIndex":2,"explanation":"\'Rendido\' significa que terminó muy cansado después del paseo."}]},{"id":"col-03","level":"accent-colombian","title":"Preguntando direcciones en Bogotá","duration":"1:15","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/colombia/Colombia_03_audio.mp3","snippet":"Carlos pide direcciones para llegar a una estación de TransMilenio. Aprenderás diminutivos colombianos como \'derechito\', \'cuadrita\', \'vueltica\' y \'mismito\'.","transcript":"Carlos: —Hola, disculpa, ¿tú sabes cómo llego a una estación de TransMilenio por aquí cerca?\\n\\nPaula: —Claro, ¿a cuál vas?\\n\\nCarlos: —A la de Calle 72, creo que así se llama.\\n\\nPaula: —Sí, esa queda cerquita. Mira, sigues derechito por esta carrera hasta la próxima esquina.\\n\\nCarlos: —¿Por la Carrera 11?\\n\\nPaula: —Exacto, por la 11. Caminas como dos cuadritas y en la segunda te metes por ahí a la vueltica a la derecha.\\n\\nCarlos: —Perfecto. ¿Y de ahí ya se ve la estación?\\n\\nPaula: —Sí, ahí mismito. Vas a ver la entrada grande roja. Cuando subas al bus, acuérdate: te bajas en la siguiente si vas hacia el norte.\\n\\nCarlos: —Listo, súper claro. Muchas gracias.\\n\\nPaula: —Con gusto. Bogotá es grande, pero uno se acostumbra.\\n\\nCarlos: —Sí, se nota. Bueno, me voy antes de que se llene más.\\n\\nPaula: —Dale, que te vaya bien. ¡Chao!\\n\\nCarlos: —¡Chao, gracias!","vocab":[{"term":"derechito","meaning":"Straight ahead / straight forward."},{"term":"mismito","meaning":"Right there / exactly there."},{"term":"vueltica","meaning":"A small turn / just around the corner."},{"term":"te bajas en la siguiente","meaning":"You get off at the next stop."},{"term":"cuadrita","meaning":"Small block (short street block)."},{"term":"TransMilenio","meaning":"Bogotá\'s bus rapid transit system (BRT)."},{"term":"enredada","meaning":"Confusing / tricky to navigate."},{"term":"ubicar(se)","meaning":"To find your way / to orient yourself."}],"quiz":[{"id":"q1","type":"single","question":"¿Qué instrucción inicial le da Paula a Carlos para encontrar la estación?","options":["Girar a la derecha inmediatamente","Seguir derechito por la carrera hasta la próxima esquina","Cruzar hacia la avenida principal"],"answerIndex":1,"explanation":"Paula le dice que siga derechito por la carrera hasta la próxima esquina."},{"id":"q2","type":"single","question":"¿Por qué Paula menciona que la estación está \'ahí mismito\'?","options":["Porque es difícil de encontrar","Porque está muy cerca y es fácil de identificar","Porque Carlos ya había ido antes"],"answerIndex":1,"explanation":"\'Ahí mismito\' indica que la estación está muy cerca y es fácil de ver."},{"id":"q3","type":"single","question":"¿Qué se puede inferir de la recomendación \'te bajas en la siguiente si vas hacia el norte\'?","options":["Que Carlos debe bajarse después de varias paradas","Que la dirección no importa para bajarse","Que la parada correcta depende de la dirección del bus"],"answerIndex":2,"explanation":"La instrucción indica que la parada correcta depende de hacia dónde va el bus."},{"id":"q4","type":"single","question":"¿Qué implica que Carlos diga \'me voy antes de que se llene más\'?","options":["Que prefiere caminar todo el trayecto","Que el transporte suele llenarse y quiere evitar aglomeraciones","Que la estación está cerrada a esa hora"],"answerIndex":1,"explanation":"Carlos quiere irse antes de que el transporte se llene más de gente."}]},{"id":"cu-01","level":"accent-cuban","title":"En una cafetería de barrio","duration":"1:15","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/cuba/Cuba_01_audio.mp3","snippet":"Luisa y Manuel conversan sobre comprar café en su barrio. Aprenderás expresiones cubanas como \'asere\', \'¿qué bolá?\', \'fundido\' y \'¿qué va?\'.","transcript":"Luisa: —Asere, ¿qué bolá? Oye, ¿tú sabes si aquí venden café pa\' llevar?\\n\\nManuel: —Claro, mi hermana, ahí mismo en la esquina. Ese cafecito está buenísimo, fuertecito, como tiene que ser.\\n\\nLuisa: —Perfecto, porque ando medio fundida hoy. ¿Tú vas a pedir algo?\\n\\nManuel: —Sí, voy a coger uno también, chiquitico, pa\' despertarme un poco. Con este calor no hay quien aguante.\\n\\nLuisa: —Dímelo a mí… Esto está fuerte de verdad. Oye, ¿y demoran mucho?\\n\\nManuel: —No, qué va. Eso es rápido. Pides, pagas y en nada ya estás saliendo con el café en la mano.\\n\\nLuisa: —Buenísimo. Entonces vamos ahora, que después se llena.\\n\\nManuel: —Dale, vamos pa\' allá. Así aprovechamos antes de que apriete más el sol.","vocab":[{"term":"asere","meaning":"Buddy / mate. Very common informal way to address a friend in Cuba."},{"term":"¿qué bolá?","meaning":"What\'s up? Extremely typical Cuban greeting used among friends."},{"term":"pa\'","meaning":"For / to. Informal reduction of \'para\', very common in spoken Cuban Spanish."},{"term":"cafecito","meaning":"Small coffee / espresso. Diminutive used to sound friendly or affectionate."},{"term":"fuertecito","meaning":"Strong. Diminutive that softens the tone, not the meaning."},{"term":"ando medio fundido","meaning":"I\'m pretty exhausted. Colloquial expression meaning very tired."},{"term":"¿qué va?","meaning":"No way / not at all. Used to strongly deny or downplay something."},{"term":"en nada","meaning":"In no time. Means something will happen very quickly."}],"quiz":[{"id":"q1","type":"single","question":"¿Por qué Luisa quiere comprar café?","options":["Porque tiene frío","Porque va a trabajar toda la noche","Porque está cansada"],"answerIndex":2,"explanation":"Luisa dice que anda \'medio fundida\', lo que significa que está cansada."},{"id":"q2","type":"single","question":"¿Cómo describe Manuel el café del lugar?","options":["Suave y dulce","Muy caro","Fuerte y de buena calidad"],"answerIndex":2,"explanation":"Manuel dice que el cafecito está \'buenísimo, fuertecito, como tiene que ser\'."},{"id":"q3","type":"single","question":"¿Qué comenta Manuel sobre el tiempo de espera?","options":["Que siempre hay mucha fila","Que es rápido y no demora","Que hay que esperar bastante"],"answerIndex":1,"explanation":"Manuel dice \'No, qué va. Eso es rápido. En nada ya estás saliendo con el café\'."},{"id":"q4","type":"single","question":"¿Por qué deciden ir en ese momento a comprar el café?","options":["Porque el lugar va a cerrar","Porque quieren evitar que se llene más tarde","Porque ya no hace calor"],"answerIndex":1,"explanation":"Luisa dice \'vamos ahora, que después se llena\' para evitar las multitudes."}]},{"id":"cu-02","level":"accent-cuban","title":"Preguntando direcciones en La Habana","duration":"1:10","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/cuba/Cuba_02_audio.mp3","snippet":"Raúl pide direcciones para llegar a la Plaza Vieja. Aprenderás expresiones cubanas como \'momentico\', \'cerquita\', \'no tiene pérdida\' y \'en nada\'.","transcript":"Raúl: —Asere, discúlpame un momentico… ¿tú sabes cómo llego a la Plaza Vieja desde aquí?\\n\\nClaudia: —Sí, claro, eso queda cerquita. Mira, sigues derecho por esta calle hasta el final y ahí doblas a la izquierda.\\n\\nRaúl: —¿Todo derecho, sin perderme?\\n\\nClaudia: —Exacto. No tiene pérdida. Caminas como cinco minutos y ya estás ahí mismo.\\n\\nRaúl: —Buenísimo. ¿Queda cerca del malecón o no?\\n\\nClaudia: —Sí, está relativamente cerca. Después sigues caminando un poquito más y llegas al malecón en nada.\\n\\nRaúl: —Perfecto, muchas gracias.\\n\\nClaudia: —De nada, asere. Que disfrutes La Habana.","vocab":[{"term":"asere","meaning":"Buddy / mate. Very common informal way to address someone in Cuba."},{"term":"momentico","meaning":"Just a moment. Diminutive used to sound polite and friendly."},{"term":"queda cerquita","meaning":"It\'s very close. Informal way to say a place is nearby."},{"term":"sigues derecho","meaning":"Go straight. Common expression when giving directions."},{"term":"doblas","meaning":"You turn. Informal imperative form used in spoken directions."},{"term":"no tiene pérdida","meaning":"You can\'t miss it. Means it\'s very easy to find."},{"term":"en nada","meaning":"In no time. Indicates something happens very quickly."},{"term":"un poquito más","meaning":"A little bit more. Softens the instruction and sounds natural."}],"quiz":[{"id":"q1","type":"single","question":"¿A dónde quiere llegar Raúl?","options":["A la Plaza Vieja","Al malecón","A una cafetería"],"answerIndex":0,"explanation":"Raúl pregunta cómo llegar a la Plaza Vieja."},{"id":"q2","type":"single","question":"¿Qué debe hacer primero Raúl según Claudia?","options":["Doblar inmediatamente a la izquierda","Caminar hasta el final de la calle","Tomar un transporte"],"answerIndex":1,"explanation":"Claudia le dice que siga derecho hasta el final de la calle."},{"id":"q3","type":"single","question":"¿Cuánto tiempo aproximadamente le tomará llegar a la Plaza Vieja?","options":["Unos cinco minutos","Más de quince minutos","Cerca de media hora"],"answerIndex":0,"explanation":"Claudia dice que camina como cinco minutos y ya está ahí."},{"id":"q4","type":"single","question":"¿Qué sugiere Claudia después de llegar a la Plaza Vieja?","options":["Volver por el mismo camino","Ir directamente a una cafetería","Seguir caminando para llegar al malecón"],"answerIndex":2,"explanation":"Claudia sugiere que después puede seguir caminando un poquito más para llegar al malecón."}]},{"id":"cu-03","level":"accent-cuban","title":"Hablando del calor y del día","duration":"1:05","file":"https://pub-2e2bb754f8ae47e0bdbd03c6797a5776.r2.dev/accents/cuba/Cuba_03_audio.mp3","snippet":"Mario y Yanelis conversan sobre el calor intenso del día. Aprenderás expresiones cubanas como \'está fuerte\', \'no afloja\', \'un ratico\' y \'ahorita\'.","transcript":"Mario: —Oye, Yanelis, esto está fuerte hoy… desde temprano el sol no afloja.\\n\\nYanelis: —Dímelo a mí. Yo salí un momentico y ya estoy sudando toda. No se puede ni caminar.\\n\\nMario: —Y eso que todavía no es mediodía. ¿Tienes algo que hacer ahora o vas pa\' la casa?\\n\\nYanelis: —Voy pa\' la casa un ratico. Con este calor no dan ganas de hacer nada.\\n\\nMario: —Te entiendo perfecto. Yo pensaba pasar por el mercado, pero mejor lo dejo pa\' más tarde.\\n\\nYanelis: —Sí, mejor. Ahorita refresca un poco y se aguanta más.\\n\\nMario: —Entonces hablamos después. Cuídate.\\n\\nYanelis: —Dale, nos vemos más tarde.","vocab":[{"term":"está fuerte","meaning":"It\'s intense / tough. Common expression to describe strong heat or difficult conditions."},{"term":"no afloja","meaning":"It doesn\'t let up. Means the heat or situation continues without easing."},{"term":"momentico","meaning":"Just a moment. Diminutive used to sound casual and friendly."},{"term":"no se puede ni caminar","meaning":"You can barely walk. Emphasizes how overwhelming the heat feels."},{"term":"pa\' la casa","meaning":"To the house / home. Informal reduction of \'para la casa\'."},{"term":"un ratico","meaning":"For a little while. Very common informal time expression."},{"term":"no dan ganas","meaning":"You don\'t feel like it. Expresses lack of motivation."},{"term":"ahorita","meaning":"Later / in a little while. Time expression whose meaning depends on context."}],"quiz":[{"id":"q1","type":"single","question":"¿De qué hablan principalmente Mario y Yanelis?","options":["De un problema en el trabajo","De un viaje próximo","Del calor del día"],"answerIndex":2,"explanation":"Mario y Yanelis hablan principalmente del calor intenso del día."},{"id":"q2","type":"single","question":"¿Qué le pasa a Yanelis cuando sale un momento?","options":["Se siente cansada por el trabajo","Empieza a sudar enseguida","Se moja por la lluvia"],"answerIndex":1,"explanation":"Yanelis dice que salió un momentico y ya está sudando toda."},{"id":"q3","type":"single","question":"¿Qué planes tenía Mario inicialmente?","options":["Ir al mercado","Visitar a unos amigos","Quedarse en casa todo el día"],"answerIndex":0,"explanation":"Mario pensaba pasar por el mercado, pero decide dejarlo para más tarde."},{"id":"q4","type":"single","question":"¿Por qué deciden dejar los planes para más tarde?","options":["Porque el mercado está cerrado","Porque están muy ocupados","Porque el calor es demasiado fuerte"],"answerIndex":2,"explanation":"Deciden esperar porque el calor es muy intenso y \'ahorita refresca un poco\'."}]}]');

